 IF product->>'artifact_digest' IS DISTINCT FROM artifact OR product->>'schema_digest' IS DISTINCT FROM encode(sha256(p_schema),'hex') OR product->>'recipe_digest' IS DISTINCT FROM encode(sha256(p_recipe),'hex') THEN
  RAISE EXCEPTION 'native artifact/schema/recipe identity differs' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT FROM sem.input WHERE release_id=run.release_id AND input_kind='dependency' AND input_name='execution/schema/pdf_products' AND encode(sha256(content),'hex')=p_contract) THEN
  RAISE EXCEPTION 'native contract not archived by task release' USING ERRCODE='23514'; END IF;
 IF encode(sha256(p_schema),'hex') IS DISTINCT FROM '3123788cfea7ddd282a4ec8fdeafee98d106ec2863d6722bbde4fc2f3f2e1bc1' OR NOT EXISTS(SELECT FROM sem.input WHERE release_id=run.release_id AND input_kind='dependency' AND input_name='execution/implementation/pdf/docling-validation.schema.json' AND encode(sha256(content),'hex')=product->>'schema_digest') THEN
  RAISE EXCEPTION 'native validation schema not admitted by release' USING ERRCODE='23514'; END IF;
 SELECT * INTO previous FROM ops.native_document_product WHERE task_id=p_task AND product_key=product->>'product_key';
 IF FOUND THEN
  IF previous.content_digest<>digest OR previous.payload<>p_payload OR previous.contract_digest<>p_contract THEN
   RAISE EXCEPTION 'immutable native replay differs' USING ERRCODE='23514'; END IF;
  RETURN digest;
 END IF;
 PERFORM sem.require_execution_operation(run.release_id,'publish_native_document');
 IF run.sealed OR run.status NOT IN ('created','running') OR job.status<>'running' THEN
  RAISE EXCEPTION 'run/attempt no longer accepts native products' USING ERRCODE='P0004'; END IF;
 IF num_nonnulls(product->>'parent_task_id',product->>'parent_product_key',product->>'parent_digest') NOT IN (0,3) THEN
  RAISE EXCEPTION 'incomplete native parent identity' USING ERRCODE='23514'; END IF;
 IF product ? 'parent_task_id' THEN
  SELECT * INTO STRICT parent FROM ops.native_document_product WHERE task_id=(product->>'parent_task_id')::bigint AND product_key=product->>'parent_product_key' AND content_digest=product->>'parent_digest';
  IF NOT EXISTS(SELECT FROM ops.source_build b JOIN ops.task t ON t.id=b.task_id JOIN ops.run r ON r.id=t.run_id WHERE b.task_id=parent.task_id AND b.artifact_digest=artifact AND r.project_id=run.project_id) THEN
   RAISE EXCEPTION 'native parent outside original/release/project custody' USING ERRCODE='23514'; END IF;
 END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(COALESCE(product->'derivation_mappings','[]')) m
 LEFT JOIN kb.native_document_item origin ON origin.task_id=parent.task_id AND origin.product_key=parent.product_key AND origin.pointer=m->>'origin_pointer'
 CROSS JOIN LATERAL (SELECT CASE WHEN m->>'source_field'='cell_text' THEN origin.native_json->'data'->'table_cells'->((m->>'cell_index')::integer)->>'text' ELSE origin.native_json->>'text' END spelling) source
 CROSS JOIN LATERAL (SELECT product->'document' #> string_to_array(substr(m->>'pointer',3),'/') node) target
 WHERE product->>'parent_task_id' IS NULL OR origin.pointer IS NULL OR target.node IS NULL
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(product->'items') i WHERE i->>'pointer'=m->>'pointer')
  OR source.spelling IS NULL OR (m->>'start')::bigint>(m->>'end')::bigint OR (m->>'start')::bigint<0 OR (m->>'end')::bigint>char_length(source.spelling)
  OR (m->>'source_field'='cell_text') IS DISTINCT FROM (m->>'cell_index' IS NOT NULL)
  OR (m->>'kind'='table_cell') IS DISTINCT FROM (m->>'source_field'='cell_text')
  OR (m->>'kind' IN ('native_text_range','table_cell') AND target.node->>'orig' IS DISTINCT FROM substr(source.spelling,(m->>'start')::integer+1,(m->>'end')::integer-(m->>'start')::integer))
  OR (m->>'kind'='vector_region_anchor' AND (target.node->>'orig' IS DISTINCT FROM '' OR substr(source.spelling,(m->>'start')::integer+1,(m->>'end')::integer-(m->>'start')::integer) ~ '[^[:space:]]'))) THEN
 RAISE EXCEPTION 'native derivation endpoints/range are unqualified' USING ERRCODE='23514'; END IF;
 INSERT INTO kb.source_artifact(artifact_digest,content) SELECT encode(sha256(content),'hex'),content FROM unnest(ARRAY[p_original,p_schema,p_recipe]) content WHERE content IS NOT NULL ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT FROM ops.source_build WHERE task_id=p_task AND release_id=run.release_id AND artifact_digest=artifact) THEN
  RAISE EXCEPTION 'source build immutable identity differs' USING ERRCODE='23514'; END IF;
 INSERT INTO ops.native_document_product(task_id,product_key,content_digest,release_id,contract_digest,schema_digest,recipe_digest,parent_task_id,parent_product_key,parent_digest,native_json,health,payload)
 VALUES(p_task,product->>'product_key',digest,run.release_id,p_contract,product->>'schema_digest',product->>'recipe_digest',(product->>'parent_task_id')::bigint,product->>'parent_product_key',product->>'parent_digest',product->'document',product->'health',p_payload);
 INSERT INTO kb.native_document_item(task_id,product_key,pointer,ordinal,label,parent_pointer,section_pointer,content_layer,text,native_json)
 SELECT p_task,product->>'product_key',i.pointer,i.ordinal,i.label,i.parent_pointer,i.section_pointer,i.content_layer,i.text,product->'document' #> string_to_array(substr(i.pointer,3),'/') FROM jsonb_populate_recordset(NULL::kb.native_document_item,product->'items') i;
 INSERT INTO kb.native_document_region(task_id,product_key,pointer,region_index,page_no,page_width,page_height,"left",top,"right",bottom,origin)
 SELECT p_task,product->>'product_key',i.pointer,i.region_index,i.page_no,i.page_width,i.page_height,i."left",i.top,i."right",i.bottom,i.origin FROM jsonb_populate_recordset(NULL::kb.native_document_region,product->'regions') i;
 INSERT INTO kb.native_document_derivation(task_id,product_key,pointer,mapping_index,origin_pointer,source_field,start_offset,end_offset,cell_index,kind)
 SELECT p_task,product->>'product_key',m.value->>'pointer',m.n-1,m.value->>'origin_pointer',m.value->>'source_field',(m.value->>'start')::bigint,(m.value->>'end')::bigint,(m.value->>'cell_index')::bigint,m.value->>'kind'
 FROM jsonb_array_elements(COALESCE(product->'derivation_mappings','[]')) WITH ORDINALITY m(value,n);
 IF jsonb_array_length(COALESCE(product->'recognition_coverage','[]'))>0 AND (product->'health'->>'inline_coverage'<>'unknown' OR product->'health'->>'cell_coverage'<>'unknown') THEN
  RAISE EXCEPTION 'scoped recognition rows cannot imply global inline/cell coverage' USING ERRCODE='23514'; END IF;
 INSERT INTO kb.native_document_coverage(task_id,product_key,section_pointer,membership,universe,outcome,policy)
 SELECT p_task,product->>'product_key',r.section_pointer,r.membership,r.universe,r.outcome,r.policy
 FROM jsonb_populate_recordset(NULL::kb.native_document_coverage,COALESCE(product->'recognition_coverage','[]')) r;
 FOR coverage IN SELECT value FROM jsonb_array_elements(COALESCE(product->'recognition_coverage','[]')) LOOP
  IF NOT EXISTS(SELECT FROM kb.native_document_item i WHERE i.task_id=p_task AND i.product_key=product->>'product_key' AND i.pointer=coverage->>'section_pointer' AND i.label IN ('section','chapter')) THEN
   RAISE EXCEPTION 'recognition coverage row is not a native organizational scope' USING ERRCODE='23514'; END IF;
  IF coverage->>'outcome'='complete' AND coverage->>'universe' IN ('display','inline') AND EXISTS(
   SELECT FROM kb.native_document_item i JOIN kb.native_document_item owner ON owner.task_id=i.task_id AND owner.product_key=i.product_key AND owner.pointer=i.parent_pointer
   WHERE i.task_id=p_task AND i.product_key=product->>'product_key' AND i.label='formula'
    AND i.pointer IN (SELECT ops.native_scope_items(p_task,product->>'product_key',coverage->>'section_pointer',coverage->>'membership'))
    AND ((coverage->>'universe'='display' AND owner.label NOT IN ('table','inline')) OR (coverage->>'universe'='inline' AND owner.label='inline'))
    AND NOT EXISTS(SELECT FROM jsonb_array_elements(product->'health'->'formula_outcomes') outcome WHERE outcome->>'pointer'=i.pointer AND outcome->>'outcome'='succeeded')) THEN
   RAISE EXCEPTION 'complete scoped formula coverage lacks attributable recognition' USING ERRCODE='23514'; END IF;
 END LOOP;
 IF EXISTS(SELECT FROM jsonb_array_elements(COALESCE(product->'cell_reports','[]')) report
 LEFT JOIN kb.native_document_item item ON item.task_id=p_task AND item.product_key=product->>'product_key' AND item.pointer=report->>'table_pointer'
 CROSS JOIN LATERAL (SELECT item.native_json->'data'->'table_cells'->((report->>'cell_index')::integer) value) cell
 WHERE item.pointer IS NULL OR item.label<>'table' OR cell.value IS NULL OR NOT EXISTS(SELECT FROM kb.native_document_region region WHERE region.task_id=p_task AND region.product_key=product->>'product_key' AND region.pointer=item.pointer AND region.page_no=(report->>'page_no')::bigint)
 OR (report->>'classification'='prose' AND (report->>'outcome'<>'not_requested' OR report->>'formula_pointer' IS NOT NULL))
 OR (report->>'classification'='math' AND report->>'outcome'='succeeded' AND (cell.value->'ref'->>'$ref' IS DISTINCT FROM report->>'formula_pointer' OR NOT EXISTS(SELECT FROM kb.native_document_item formula WHERE formula.task_id=p_task AND formula.product_key=product->>'product_key' AND formula.pointer=report->>'formula_pointer' AND formula.label='formula') OR NOT EXISTS(SELECT FROM jsonb_array_elements(product->'health'->'formula_outcomes') outcome WHERE outcome->>'pointer'=report->>'formula_pointer' AND outcome->>'outcome'='succeeded')))) THEN
 RAISE EXCEPTION 'native cell report is outside table/page/recognition custody' USING ERRCODE='23514'; END IF;
 INSERT INTO kb.native_document_cell_report(task_id,product_key,table_pointer,cell_index,page_no,classification,basis,outcome,formula_pointer,error)
 SELECT p_task,product->>'product_key',r.table_pointer,r.cell_index,r.page_no,r.classification,r.basis,r.outcome,r.formula_pointer,r.error
 FROM jsonb_populate_recordset(NULL::kb.native_document_cell_report,COALESCE(product->'cell_reports','[]')) r;
 IF product ? 'runtime_report' THEN INSERT INTO kb.native_document_runtime VALUES(p_task,product->>'product_key',product->'runtime_report'); END IF;
 FOR coverage IN SELECT value FROM jsonb_array_elements(COALESCE(product->'recognition_coverage','[]')) WHERE value->>'universe'='cell' AND value->>'outcome'='complete' LOOP
  IF EXISTS(SELECT FROM kb.native_document_cell_report r WHERE r.task_id=p_task AND r.product_key=product->>'product_key'
   AND r.table_pointer IN (SELECT ops.native_scope_items(p_task,product->>'product_key',coverage->>'section_pointer',coverage->>'membership'))
   AND (r.classification='unknown' OR (r.classification='math' AND r.outcome<>'succeeded'))) THEN
   RAISE EXCEPTION 'complete scoped cell coverage contains unresolved recognition/classification' USING ERRCODE='23514'; END IF;
  IF EXISTS(WITH expected AS (
   SELECT item.pointer table_pointer,c.n-1 cell_index FROM kb.native_document_item item
   LEFT JOIN kb.native_document_item source ON source.task_id=parent.task_id AND source.product_key=parent.product_key AND source.pointer=item.pointer
   CROSS JOIN LATERAL jsonb_array_elements(COALESCE(source.native_json->'data'->'table_cells',item.native_json->'data'->'table_cells','[]')) WITH ORDINALITY c(value,n)
   WHERE item.task_id=p_task AND item.product_key=product->>'product_key' AND item.label='table'
    AND item.pointer IN (SELECT ops.native_scope_items(p_task,product->>'product_key',coverage->>'section_pointer',coverage->>'membership'))
    AND (length(trim(COALESCE(c.value->>'text','')))>0 OR c.value->'ref'->>'$ref' IS NOT NULL)
  ) SELECT FROM expected LEFT JOIN kb.native_document_cell_report actual ON actual.task_id=p_task AND actual.product_key=product->>'product_key' AND actual.table_pointer=expected.table_pointer AND actual.cell_index=expected.cell_index WHERE actual.table_pointer IS NULL) THEN
   RAISE EXCEPTION 'complete scoped cell coverage lacks its exact nonempty cell inventory' USING ERRCODE='23514'; END IF;
 END LOOP;
 IF EXISTS(SELECT FROM kb.native_document_cell_report report WHERE report.task_id=p_task AND report.product_key=product->>'product_key' AND NOT EXISTS(
  SELECT FROM kb.native_document_coverage c WHERE c.task_id=p_task AND c.product_key=product->>'product_key' AND c.universe='cell' AND report.table_pointer IN (SELECT ops.native_scope_items(p_task,product->>'product_key',c.section_pointer,c.membership)))) THEN
  RAISE EXCEPTION 'native cell report is outside declared recognition scope' USING ERRCODE='23514'; END IF;
 -- Compare the complete access universe, not only whichever rows the caller supplied.
 IF EXISTS(
 WITH RECURSIVE nodes AS (
  SELECT '#/'||field.key||'/'||(entry.n-1)::text pointer,entry.value node FROM jsonb_each(product->'document') field
  CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(field.value)='array' THEN field.value ELSE '[]'::jsonb END) WITH ORDINALITY entry(value,n)
  WHERE entry.value ? 'self_ref'
  UNION ALL SELECT product->'document'->'body'->>'self_ref',product->'document'->'body'
  UNION ALL SELECT product->'document'->'furniture'->>'self_ref',product->'document'->'furniture'
 ), walk(pointer,path,trail,scope) AS (
  SELECT pointer,ARRAY[CASE pointer WHEN '#/body' THEN 0 ELSE 1 END]::bigint[],ARRAY[pointer]::text[],NULL::text FROM nodes WHERE pointer IN ('#/body','#/furniture')
  UNION ALL
  SELECT child->>'$ref',w.path||n,w.trail||(child->>'$ref'),CASE WHEN target.node->>'label' IN ('section','chapter') THEN target.pointer ELSE w.scope END
  FROM walk w JOIN nodes parent_node ON parent_node.pointer=w.pointer
  CROSS JOIN LATERAL jsonb_array_elements(COALESCE(parent_node.node->'children','[]'::jsonb)) WITH ORDINALITY entry(child,n)
  JOIN nodes target ON target.pointer=child->>'$ref'
  WHERE NOT (child->>'$ref')=ANY(w.trail)
 ), ordered AS (
  SELECT pointer,path,scope FROM walk
  UNION ALL SELECT pointer,ARRAY[2]::bigint[],NULL::text FROM nodes WHERE NOT EXISTS(SELECT FROM walk WHERE walk.pointer=nodes.pointer)
 ), expected AS (
  SELECT nodes.*,row_number() OVER(ORDER BY ordered.path,nodes.pointer)-1 ordinal,ordered.scope
  FROM nodes JOIN ordered USING(pointer)
 )
 SELECT FROM expected e FULL JOIN (SELECT * FROM kb.native_document_item WHERE task_id=p_task AND product_key=product->>'product_key') actual USING(pointer)
 WHERE e.pointer IS NULL OR actual.pointer IS NULL OR actual.ordinal IS DISTINCT FROM e.ordinal
 OR actual.content_layer IS DISTINCT FROM e.node->>'content_layer'
 OR e.node->>'self_ref' IS DISTINCT FROM e.pointer
 OR actual.label IS DISTINCT FROM e.node->>'label'
 OR actual.text IS DISTINCT FROM e.node->>'text'
 OR actual.native_json IS DISTINCT FROM e.node
 OR actual.parent_pointer IS DISTINCT FROM e.node->'parent'->>'$ref'
 OR (actual.parent_pointer IS NOT NULL AND NOT EXISTS(SELECT FROM nodes p WHERE p.pointer=actual.parent_pointer))
 OR actual.section_pointer IS DISTINCT FROM e.scope
 OR EXISTS(SELECT FROM jsonb_array_elements(COALESCE(e.node->'children','[]'::jsonb)) child LEFT JOIN nodes target ON target.pointer=child->>'$ref' WHERE target.pointer IS NULL OR target.node->'parent'->>'$ref' IS DISTINCT FROM e.pointer)
 ) THEN RAISE EXCEPTION 'native access universe/order/membership differs' USING ERRCODE='23514'; END IF;
 -- One set-shaped provenance projection avoids repeated whole-document pointer lookup.
 IF EXISTS(
 WITH nodes AS (
  SELECT entry.value node FROM jsonb_each(product->'document') field
  CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(field.value)='array' THEN field.value ELSE '[]'::jsonb END) entry(value)
  WHERE entry.value ? 'self_ref'
 ), expected AS (
  SELECT node->>'self_ref' pointer,n-1 region_index,prov,
   product->'document'->'pages'->(prov->>'page_no')->'size' page_size
  FROM nodes CROSS JOIN LATERAL jsonb_array_elements(COALESCE(node->'prov','[]'::jsonb)) WITH ORDINALITY regions(prov,n)
 )
 SELECT FROM expected e FULL JOIN (SELECT * FROM kb.native_document_region WHERE task_id=p_task AND product_key=product->>'product_key') r USING(pointer,region_index)
 WHERE e.pointer IS NULL OR r.pointer IS NULL
 OR (e.prov->>'page_no')::bigint IS DISTINCT FROM r.page_no
 OR (e.page_size->>'width')::numeric IS DISTINCT FROM r.page_width
 OR (e.page_size->>'height')::numeric IS DISTINCT FROM r.page_height
 OR (e.prov->'bbox'->>'l')::numeric IS DISTINCT FROM r."left"
 OR (e.prov->'bbox'->>'t')::numeric IS DISTINCT FROM r.top
 OR (e.prov->'bbox'->>'r')::numeric IS DISTINCT FROM r."right"
 OR (e.prov->'bbox'->>'b')::numeric IS DISTINCT FROM r.bottom
 OR CASE e.prov->'bbox'->>'coord_origin' WHEN 'TOPLEFT' THEN 'top_left' WHEN 'BOTTOMLEFT' THEN 'bottom_left' END IS DISTINCT FROM r.origin
 ) THEN RAISE EXCEPTION 'native region projection differs' USING ERRCODE='23514'; END IF;
 RETURN digest;
END $native$;
REVOKE ALL ON FUNCTION ops.publish_native_document(bigint,bigint,text,text,bytea,bytea,bytea,bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.publish_native_document(bigint,bigint,text,text,bytea,bytea,bytea,bytea) TO corpus_sem_writer;

CREATE OR REPLACE FUNCTION ops.retain_pdf_original(p_task bigint,p_attempt bigint,p_holder text,p_original bytea,p_recipe bytea) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $original$
DECLARE job ops.task; run ops.run; artifact text:=encode(sha256(p_original),'hex'); recipe text:=encode(sha256(p_recipe),'hex');
BEGIN
 SELECT r.* INTO STRICT run FROM ops.run r JOIN ops.task t ON t.run_id=r.id WHERE t.id=p_task FOR SHARE OF r;
 SELECT * INTO STRICT job FROM ops.task WHERE id=p_task AND run_id=run.id FOR UPDATE;
 IF job.attempt<>p_attempt OR job.claimed_by IS DISTINCT FROM p_holder OR job.status<>'running' OR run.sealed OR run.status NOT IN ('created','running') THEN
  RAISE EXCEPTION 'stale PDF original attempt' USING ERRCODE='P0004'; END IF;
 PERFORM sem.require_execution_operation(run.release_id,'retain_pdf_original');
 IF substring(p_original FROM 1 FOR 5)<>convert_to('%PDF-','UTF8') THEN
  RAISE EXCEPTION 'PDF-only source requires PDF bytes' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT FROM kb.document d WHERE d.project_id=run.project_id AND d.content_hash=artifact AND ((job.unit_type='document' AND d.id=job.unit_id) OR (job.unit_type='source_view' AND EXISTS(SELECT FROM kb.source_view v JOIN ops.run_source_view s ON s.source_view_id=v.id WHERE v.id=job.unit_id AND s.run_id=run.id AND v.document_id=d.id)))) THEN
  RAISE EXCEPTION 'PDF original differs from task document custody' USING ERRCODE='23514'; END IF;
 INSERT INTO kb.source_artifact(artifact_digest,content) SELECT encode(sha256(content),'hex'),content FROM unnest(ARRAY[p_original,p_recipe]) content ON CONFLICT DO NOTHING;
 INSERT INTO ops.source_build(task_id,release_id,artifact_digest,recipe_digest) VALUES(p_task,run.release_id,artifact,recipe) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT FROM ops.source_build WHERE task_id=p_task AND release_id=run.release_id AND artifact_digest=artifact AND recipe_digest=recipe) THEN
  RAISE EXCEPTION 'immutable source build differs' USING ERRCODE='23514'; END IF;
 RETURN artifact;
END $original$;
REVOKE ALL ON FUNCTION ops.retain_pdf_original(bigint,bigint,text,bytea,bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.retain_pdf_original(bigint,bigint,text,bytea,bytea) TO corpus_sem_writer;

-- One native containment projection serves membership validation and scoped recognition.
CREATE OR REPLACE FUNCTION ops.native_scope_items(p_task bigint,p_key text,p_section text,p_membership text)
RETURNS SETOF text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $scope$
 WITH RECURSIVE subtree AS (
  SELECT pointer FROM kb.native_document_item WHERE task_id=p_task AND product_key=p_key AND pointer=p_section
  UNION ALL SELECT child.pointer FROM kb.native_document_item child JOIN subtree parent ON child.parent_pointer=parent.pointer
   WHERE child.task_id=p_task AND child.product_key=p_key AND p_membership='descendants'
 ) SELECT pointer FROM kb.native_document_item WHERE task_id=p_task AND product_key=p_key AND content_layer='body'
  AND ((p_membership='direct' AND section_pointer=p_section) OR (p_membership='descendants' AND pointer IN (SELECT pointer FROM subtree)))
$scope$;
REVOKE ALL ON FUNCTION ops.native_scope_items(bigint,text,text,text) FROM PUBLIC;

-- Immutable section views are instances, never fabricated document/rendition rows.
CREATE OR REPLACE FUNCTION ops.publish_source_view(p_run bigint,p_task bigint,p_attempt bigint,p_holder text,p_position bigint,p_payload bytea,p_recipe bytea) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $view$
DECLARE job ops.task; run ops.run; product jsonb; parsing_item jsonb; projection jsonb; piece jsonb;
 native ops.native_document_product; section kb.native_document_item; previous kb.source_view; result bigint;
 pos bigint:=0; stop bigint; node jsonb; spelling text; piece_pointer text; expected jsonb; coverage_universe text; local_coverage text; coverage_row kb.native_document_coverage;
BEGIN
 SELECT * INTO STRICT run FROM ops.run WHERE id=p_run FOR SHARE;
 SELECT * INTO STRICT job FROM ops.task WHERE id=p_task AND run_id=p_run FOR UPDATE;
 PERFORM sem.require_execution_operation(run.release_id,'publish_source_view');
 IF job.attempt<>p_attempt OR job.claimed_by IS DISTINCT FROM p_holder THEN RAISE EXCEPTION 'source view attempt lost' USING ERRCODE='P0004'; END IF;
 product:=convert_from(p_payload,'UTF8')::jsonb;
 IF jsonb_typeof(product) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: PdfSourceViewPublication' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(product) key WHERE key<>ALL(ARRAY['key','document_id','native_task_id','native_product_key','native_content_digest','section_pointer','membership','projection_digest','recipe_digest','projection','replaces_source_view_id','analysis_eligible'])) OR NOT (product ? 'key') OR (product ? 'key' AND (jsonb_typeof(product->'key') IS DISTINCT FROM 'string')) OR NOT (product ? 'document_id') OR (product ? 'document_id' AND (jsonb_typeof(product->'document_id') IS DISTINCT FROM 'number' OR product->>'document_id' !~ '^[0-9]+$')) OR (product ? 'document_id' AND (product->>'document_id')::numeric < 1) OR NOT (product ? 'native_task_id') OR (product ? 'native_task_id' AND (jsonb_typeof(product->'native_task_id') IS DISTINCT FROM 'number' OR product->>'native_task_id' !~ '^[0-9]+$')) OR (product ? 'native_task_id' AND (product->>'native_task_id')::numeric < 1) OR NOT (product ? 'native_product_key') OR (product ? 'native_product_key' AND (jsonb_typeof(product->'native_product_key') IS DISTINCT FROM 'string')) OR NOT (product ? 'native_content_digest') OR (product ? 'native_content_digest' AND (jsonb_typeof(product->'native_content_digest') IS DISTINCT FROM 'string')) OR (product ? 'native_content_digest' AND product->>'native_content_digest' !~ '^[0-9a-f]{64}$') OR NOT (product ? 'section_pointer') OR (product ? 'section_pointer' AND (jsonb_typeof(product->'section_pointer') IS DISTINCT FROM 'string')) OR (product ? 'section_pointer' AND product->>'section_pointer' !~ '^#(/[^/]+)+$') OR NOT (product ? 'membership') OR (product ? 'membership' AND (jsonb_typeof(product->'membership') IS DISTINCT FROM 'string' OR product->>'membership' NOT IN ('descendants','direct'))) OR NOT (product ? 'projection_digest') OR (product ? 'projection_digest' AND (jsonb_typeof(product->'projection_digest') IS DISTINCT FROM 'string')) OR (product ? 'projection_digest' AND product->>'projection_digest' !~ '^[0-9a-f]{64}$') OR NOT (product ? 'recipe_digest') OR (product ? 'recipe_digest' AND (jsonb_typeof(product->'recipe_digest') IS DISTINCT FROM 'string')) OR (product ? 'recipe_digest' AND product->>'recipe_digest' !~ '^[0-9a-f]{64}$') OR NOT (product ? 'projection') OR (product ? 'projection' AND (jsonb_typeof(product->'projection') IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(product->'projection') key WHERE key<>ALL(ARRAY['text','pieces','items','ancestors','health'])) OR NOT (product->'projection' ? 'text') OR (product->'projection' ? 'text' AND (jsonb_typeof(product->'projection'->'text') IS DISTINCT FROM 'string')) OR (product->'projection' ? 'pieces' AND (jsonb_typeof(product->'projection'->'pieces') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(product->'projection'->'pieces') nested_record WHERE jsonb_typeof(nested_record) IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(nested_record) key WHERE key<>ALL(ARRAY['item_ref','start','end','kind','cell_index','source_field'])) OR (nested_record ? 'item_ref' AND (jsonb_typeof(nested_record->'item_ref') IS DISTINCT FROM 'string')) OR (nested_record ? 'item_ref' AND nested_record->>'item_ref' !~ '^#(/[^/]+)+$') OR NOT (nested_record ? 'start') OR (nested_record ? 'start' AND (jsonb_typeof(nested_record->'start') IS DISTINCT FROM 'number' OR nested_record->>'start' !~ '^[0-9]+$')) OR (nested_record ? 'start' AND (nested_record->>'start')::numeric < 0) OR NOT (nested_record ? 'end') OR (nested_record ? 'end' AND (jsonb_typeof(nested_record->'end') IS DISTINCT FROM 'number' OR nested_record->>'end' !~ '^[0-9]+$')) OR (nested_record ? 'end' AND (nested_record->>'end')::numeric < 0) OR NOT (nested_record ? 'kind') OR (nested_record ? 'kind' AND (jsonb_typeof(nested_record->'kind') IS DISTINCT FROM 'string')) OR (nested_record ? 'cell_index' AND (jsonb_typeof(nested_record->'cell_index') IS DISTINCT FROM 'number' OR nested_record->>'cell_index' !~ '^[0-9]+$')) OR (nested_record ? 'cell_index' AND (nested_record->>'cell_index')::numeric < 0) OR (nested_record ? 'source_field' AND (jsonb_typeof(nested_record->'source_field') IS DISTINCT FROM 'string')))))) OR NOT (product->'projection' ? 'items') OR (product->'projection' ? 'items' AND (jsonb_typeof(product->'projection'->'items') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(product->'projection'->'items') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string') OR jsonb_array_length(product->'projection'->'items') < 1)) OR (product->'projection' ? 'items' AND EXISTS(SELECT FROM jsonb_array_elements_text(product->'projection'->'items') element WHERE element !~ '^#(/[^/]+)+$')) OR (product->'projection' ? 'ancestors' AND (jsonb_typeof(product->'projection'->'ancestors') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(product->'projection'->'ancestors') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string'))) OR (product->'projection' ? 'ancestors' AND EXISTS(SELECT FROM jsonb_array_elements_text(product->'projection'->'ancestors') element WHERE element !~ '^#(/[^/]+)+$')) OR NOT (product->'projection' ? 'health') OR (product->'projection' ? 'health' AND (jsonb_typeof(product->'projection'->'health') IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(product->'projection'->'health') key WHERE key<>ALL(ARRAY['conversion','display_coverage','inline_coverage','cell_coverage','issues','formula_outcomes','candidate_policy','cells_policy','inline_scope','cell_scope','inline_membership','cell_membership'])) OR NOT (product->'projection'->'health' ? 'conversion') OR (product->'projection'->'health' ? 'conversion' AND (jsonb_typeof(product->'projection'->'health'->'conversion') IS DISTINCT FROM 'string' OR product->'projection'->'health'->>'conversion' NOT IN ('failure','partial_success','success'))) OR NOT (product->'projection'->'health' ? 'display_coverage') OR (product->'projection'->'health' ? 'display_coverage' AND (jsonb_typeof(product->'projection'->'health'->'display_coverage') IS DISTINCT FROM 'string' OR product->'projection'->'health'->>'display_coverage' NOT IN ('complete','partial','unknown','unsupported'))) OR NOT (product->'projection'->'health' ? 'inline_coverage') OR (product->'projection'->'health' ? 'inline_coverage' AND (jsonb_typeof(product->'projection'->'health'->'inline_coverage') IS DISTINCT FROM 'string' OR product->'projection'->'health'->>'inline_coverage' NOT IN ('complete','partial','unknown','unsupported'))) OR NOT (product->'projection'->'health' ? 'cell_coverage') OR (product->'projection'->'health' ? 'cell_coverage' AND (jsonb_typeof(product->'projection'->'health'->'cell_coverage') IS DISTINCT FROM 'string' OR product->'projection'->'health'->>'cell_coverage' NOT IN ('complete','partial','unknown','unsupported'))) OR (product->'projection'->'health' ? 'issues' AND (jsonb_typeof(product->'projection'->'health'->'issues') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(product->'projection'->'health'->'issues') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string'))) OR (product->'projection'->'health' ? 'formula_outcomes' AND (jsonb_typeof(product->'projection'->'health'->'formula_outcomes') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(product->'projection'->'health'->'formula_outcomes') nested_record WHERE jsonb_typeof(nested_record) IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(nested_record) key WHERE key<>ALL(ARRAY['pointer','outcome','error'])) OR NOT (nested_record ? 'pointer') OR (nested_record ? 'pointer' AND (jsonb_typeof(nested_record->'pointer') IS DISTINCT FROM 'string')) OR (nested_record ? 'pointer' AND nested_record->>'pointer' !~ '^#(/[^/]+)+$') OR NOT (nested_record ? 'outcome') OR (nested_record ? 'outcome' AND (jsonb_typeof(nested_record->'outcome') IS DISTINCT FROM 'string' OR nested_record->>'outcome' NOT IN ('failed','not_requested','succeeded','unknown'))) OR (nested_record ? 'error' AND (jsonb_typeof(nested_record->'error') IS DISTINCT FROM 'string')))))) OR (product->'projection'->'health' ? 'candidate_policy' AND (jsonb_typeof(product->'projection'->'health'->'candidate_policy') IS DISTINCT FROM 'string' OR product->'projection'->'health'->>'candidate_policy' NOT IN ('native-font-token-vector-v2','native-math-font-or-token-v1'))) OR (product->'projection'->'health' ? 'cells_policy' AND (jsonb_typeof(product->'projection'->'health'->'cells_policy') IS DISTINCT FROM 'string' OR product->'projection'->'health'->>'cells_policy' NOT IN ('all-nonempty-selected-cells-v1'))) OR (product->'projection'->'health' ? 'inline_scope' AND (jsonb_typeof(product->'projection'->'health'->'inline_scope') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(product->'projection'->'health'->'inline_scope') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string'))) OR (product->'projection'->'health' ? 'inline_scope' AND EXISTS(SELECT FROM jsonb_array_elements_text(product->'projection'->'health'->'inline_scope') element WHERE element !~ '^#(/[^/]+)+$')) OR (product->'projection'->'health' ? 'cell_scope' AND (jsonb_typeof(product->'projection'->'health'->'cell_scope') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(product->'projection'->'health'->'cell_scope') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string'))) OR (product->'projection'->'health' ? 'cell_scope' AND EXISTS(SELECT FROM jsonb_array_elements_text(product->'projection'->'health'->'cell_scope') element WHERE element !~ '^#(/[^/]+)+$')) OR (product->'projection'->'health' ? 'inline_membership' AND (jsonb_typeof(product->'projection'->'health'->'inline_membership') IS DISTINCT FROM 'string' OR product->'projection'->'health'->>'inline_membership' NOT IN ('descendants','direct'))) OR (product->'projection'->'health' ? 'cell_membership' AND (jsonb_typeof(product->'projection'->'health'->'cell_membership') IS DISTINCT FROM 'string' OR product->'projection'->'health'->>'cell_membership' NOT IN ('descendants','direct'))))))))) OR (product ? 'replaces_source_view_id' AND (jsonb_typeof(product->'replaces_source_view_id') IS DISTINCT FROM 'number' OR product->>'replaces_source_view_id' !~ '^[0-9]+$')) OR (product ? 'replaces_source_view_id' AND (product->>'replaces_source_view_id')::numeric < 1) OR NOT (product ? 'analysis_eligible') OR (product ? 'analysis_eligible' AND (jsonb_typeof(product->'analysis_eligible') IS DISTINCT FROM 'boolean')) THEN RAISE EXCEPTION 'parsing record shape differs: PdfSourceViewPublication' USING ERRCODE='23514'; END IF;

 projection:=product->'projection';
 IF product->>'recipe_digest' IS DISTINCT FROM encode(sha256(p_recipe),'hex') OR
 product->>'projection_digest' IS DISTINCT FROM encode(sha256(convert_to(data.canonical_json(projection),'UTF8')),'hex') THEN
 RAISE EXCEPTION 'source view recipe/projection identity differs' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT native FROM ops.native_document_product WHERE task_id=(product->>'native_task_id')::bigint AND product_key=product->>'native_product_key' AND content_digest=product->>'native_content_digest';
 -- Cross-release reuse is explicitly pinned to an archived native schema and producer contract.
 IF NOT EXISTS(SELECT FROM kb.document d JOIN ops.source_build b ON b.artifact_digest=d.content_hash JOIN ops.task t ON t.id=b.task_id JOIN ops.run r ON r.id=t.run_id
 WHERE d.id=(product->>'document_id')::bigint AND d.project_id=run.project_id AND b.task_id=native.task_id AND r.project_id=run.project_id AND EXISTS(SELECT FROM ops.source_build own WHERE own.task_id=p_task AND own.artifact_digest=b.artifact_digest)) THEN
 RAISE EXCEPTION 'native source view outside original/project custody' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT FROM sem.input WHERE release_id=native.release_id AND input_kind='dependency' AND input_name='execution/schema/pdf_products' AND encode(sha256(content),'hex')=native.contract_digest)
 OR NOT EXISTS(SELECT FROM sem.input WHERE release_id=run.release_id AND input_kind='dependency' AND input_name='execution/implementation/pdf/docling-validation.schema.json' AND encode(sha256(content),'hex')=native.schema_digest) THEN
 RAISE EXCEPTION 'native producer/consumer schema compatibility is unavailable' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT section FROM kb.native_document_item WHERE task_id=native.task_id AND product_key=native.product_key AND pointer=product->>'section_pointer';
 IF section.label NOT IN ('section','chapter') THEN RAISE EXCEPTION 'source view requires admitted section container' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements_text(projection->'items') ptr WHERE NOT EXISTS(SELECT FROM kb.native_document_item WHERE task_id=native.task_id AND product_key=native.product_key AND pointer=ptr))
 OR EXISTS(SELECT FROM jsonb_array_elements_text(COALESCE(projection->'ancestors','[]')) ptr WHERE NOT EXISTS(SELECT FROM kb.native_document_item WHERE task_id=native.task_id AND product_key=native.product_key AND pointer=ptr)) THEN
 RAISE EXCEPTION 'source view references an unqualified occurrence' USING ERRCODE='23514'; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements_text(projection->'items'))<>(SELECT count(DISTINCT value) FROM jsonb_array_elements_text(projection->'items')) THEN
 RAISE EXCEPTION 'source view repeats an occurrence' USING ERRCODE='23514'; END IF;
 SELECT COALESCE(jsonb_agg(pointer ORDER BY ordinal),'[]'::jsonb) INTO expected FROM kb.native_document_item
 WHERE task_id=native.task_id AND product_key=native.product_key AND pointer IN (SELECT ops.native_scope_items(native.task_id,native.product_key,section.pointer,product->>'membership'));
 IF projection->'items' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'source view membership/order is incomplete or differs' USING ERRCODE='23514'; END IF;
 WITH RECURSIVE ancestry AS (
 SELECT p.*,0 depth FROM kb.native_document_item p WHERE p.task_id=native.task_id AND p.product_key=native.product_key AND p.pointer=section.parent_pointer
 UNION ALL SELECT p.*,a.depth+1 FROM kb.native_document_item p JOIN ancestry a ON p.pointer=a.parent_pointer WHERE p.task_id=native.task_id AND p.product_key=native.product_key
 ) SELECT COALESCE(jsonb_agg(pointer ORDER BY depth DESC),'[]'::jsonb) INTO expected FROM ancestry WHERE pointer NOT IN ('#/body','#/furniture');
 IF COALESCE(projection->'ancestors','[]') IS DISTINCT FROM expected THEN RAISE EXCEPTION 'source view ancestry differs' USING ERRCODE='23514'; END IF;
 FOR piece IN SELECT value FROM jsonb_array_elements(projection->'pieces') LOOP
  stop:=(piece->>'end')::bigint;
  IF (piece->>'start')::bigint<>pos OR stop<=pos OR stop>char_length(projection->>'text') THEN
   RAISE EXCEPTION 'source view pieces do not partition text' USING ERRCODE='23514'; END IF;
  spelling:=substr(projection->>'text',(pos+1)::integer,(stop-pos)::integer);
  IF piece->>'kind'='synthetic_separator' THEN
   IF piece->>'item_ref' IS NOT NULL OR spelling<>E'\n' THEN RAISE EXCEPTION 'unqualified synthetic source text' USING ERRCODE='23514'; END IF;
  ELSIF piece->>'kind'='native_text' THEN
   piece_pointer:=piece->>'item_ref';
   IF NOT (projection->'items' ? piece_pointer) THEN RAISE EXCEPTION 'piece outside selected source occurrences' USING ERRCODE='23514'; END IF;
   SELECT native_json INTO STRICT node FROM kb.native_document_item WHERE task_id=native.task_id AND product_key=native.product_key AND pointer=piece_pointer;
   IF piece->>'source_field'='cell_text' THEN
    node:=node->'data'->'table_cells'->((piece->>'cell_index')::integer);
   END IF;
   IF spelling IS DISTINCT FROM (node->>(CASE WHEN piece->>'source_field'='cell_text' THEN 'text' ELSE COALESCE(piece->>'source_field','text') END)) OR COALESCE(piece->>'source_field','text') NOT IN ('text','orig','cell_text') THEN
    RAISE EXCEPTION 'projected source text differs from native occurrence' USING ERRCODE='23514'; END IF;
  ELSE RAISE EXCEPTION 'unadmitted source projection operation' USING ERRCODE='23514'; END IF;
  pos:=stop;
 END LOOP;
 SELECT (native.health - 'formula_outcomes') || jsonb_build_object('formula_outcomes',COALESCE(jsonb_agg(o.value ORDER BY o.n) FILTER(WHERE projection->'items' ? (o.value->>'pointer')),'[]')) INTO expected FROM jsonb_array_elements(COALESCE(native.health->'formula_outcomes','[]')) WITH ORDINALITY o(value,n);
 IF EXISTS(SELECT FROM kb.native_document_coverage WHERE task_id=native.task_id AND product_key=native.product_key) THEN
  expected:=expected-ARRAY['inline_scope','cell_scope','inline_membership','cell_membership','candidate_policy','cells_policy'];
  FOREACH coverage_universe IN ARRAY ARRAY['display','inline','cell'] LOOP
   SELECT * INTO coverage_row FROM kb.native_document_coverage c WHERE c.task_id=native.task_id AND c.product_key=native.product_key AND c.universe=coverage_universe AND
    ((c.section_pointer=section.pointer AND c.membership=product->>'membership') OR (c.outcome='complete' AND c.membership='descendants' AND (c.section_pointer=section.pointer OR projection->'ancestors' ? c.section_pointer)))
    ORDER BY (c.section_pointer=section.pointer AND c.membership=product->>'membership') DESC,c.section_pointer LIMIT 1;
   IF FOUND THEN
    expected:=jsonb_set(expected,ARRAY[coverage_universe||'_coverage'],to_jsonb(coverage_row.outcome));
    IF coverage_universe<>'display' THEN
     expected:=jsonb_set(expected,ARRAY[coverage_universe||'_scope'],jsonb_build_array(section.pointer));
     expected:=jsonb_set(expected,ARRAY[coverage_universe||'_membership'],to_jsonb(product->>'membership'));
     expected:=jsonb_set(expected,ARRAY[CASE coverage_universe WHEN 'inline' THEN 'candidate_policy' ELSE 'cells_policy' END],to_jsonb(coverage_row.policy));
    END IF;
   ELSE expected:=jsonb_set(expected,ARRAY[coverage_universe||'_coverage'],'"unknown"'::jsonb); END IF;
  END LOOP;
 ELSE
 SELECT CASE WHEN count(i.pointer)=0 OR bool_and(COALESCE(o.value->>'outcome'='succeeded',false)) THEN 'complete' WHEN count(o.value)>0 THEN 'partial' ELSE 'unknown' END INTO local_coverage
 FROM kb.native_document_item i LEFT JOIN kb.native_document_item parent ON parent.task_id=i.task_id AND parent.product_key=i.product_key AND parent.pointer=i.parent_pointer
 LEFT JOIN jsonb_array_elements(COALESCE(native.health->'formula_outcomes','[]')) o(value) ON o.value->>'pointer'=i.pointer
 WHERE i.task_id=native.task_id AND i.product_key=native.product_key AND projection->'items' ? i.pointer AND i.label='formula' AND COALESCE(parent.label,'') NOT IN ('table','inline');
 expected:=jsonb_set(expected,'{display_coverage}',to_jsonb(local_coverage));
 FOREACH coverage_universe IN ARRAY ARRAY['inline','cell'] LOOP
  IF native.health->>(coverage_universe||'_coverage') IN ('complete','partial') AND NOT COALESCE((
   ((native.health->(coverage_universe||'_scope') ? section.pointer) AND native.health->>(coverage_universe||'_membership')=product->>'membership') OR
   (native.health->>(coverage_universe||'_membership')='descendants' AND ((native.health->(coverage_universe||'_scope') ? section.pointer) OR EXISTS(SELECT FROM jsonb_array_elements_text(COALESCE(projection->'ancestors','[]')) parent WHERE native.health->(coverage_universe||'_scope') ? parent)))),false) THEN
   expected:=jsonb_set(expected,ARRAY[coverage_universe||'_coverage'],'"unknown"'::jsonb);
  END IF;
 END LOOP;
 END IF;
 IF pos<>char_length(projection->>'text') OR projection->'health' IS DISTINCT FROM expected THEN
 RAISE EXCEPTION 'source view text extent/health differs' USING ERRCODE='23514'; END IF;
 SELECT * INTO previous FROM kb.source_view WHERE key=product->>'key' AND release_id=run.release_id;
 IF FOUND THEN
  IF previous.projection IS DISTINCT FROM projection OR previous.native_content_digest<>native.content_digest OR previous.recipe_digest<>product->>'recipe_digest' OR previous.analysis_eligible IS DISTINCT FROM (product->>'analysis_eligible')::boolean THEN
   RAISE EXCEPTION 'immutable source view replay differs' USING ERRCODE='23514'; END IF;
  result:=previous.id;
 ELSE
  IF run.sealed OR run.status NOT IN ('created','running') OR job.status<>'running' THEN RAISE EXCEPTION 'source view run is no longer writable' USING ERRCODE='P0004'; END IF;
  INSERT INTO kb.source_artifact(artifact_digest,content) VALUES(encode(sha256(p_recipe),'hex'),p_recipe) ON CONFLICT DO NOTHING;
  INSERT INTO kb.source_view(analysis_eligible,key,document_id,release_id,native_task_id,native_product_key,native_content_digest,section_pointer,membership,projection_digest,recipe_digest,projection)
  VALUES((product->>'analysis_eligible')::boolean,product->>'key',(product->>'document_id')::bigint,run.release_id,native.task_id,native.product_key,native.content_digest,section.pointer,product->>'membership',product->>'projection_digest',product->>'recipe_digest',projection) RETURNING id INTO result;
 END IF;
 IF product->>'replaces_source_view_id' IS NOT NULL AND NOT EXISTS(SELECT FROM ops.run_source_view rs JOIN kb.source_view old ON old.id=rs.source_view_id WHERE rs.run_id=p_run AND old.id=(product->>'replaces_source_view_id')::bigint AND old.document_id=(product->>'document_id')::bigint AND old.section_pointer=section.pointer AND old.membership=product->>'membership') THEN
 RAISE EXCEPTION 'source view replacement differs from selected original/section' USING ERRCODE='23514'; END IF;
 IF run.sealed OR run.status NOT IN ('created','running') OR job.status<>'running' THEN
  IF NOT EXISTS(SELECT FROM ops.run_source_view WHERE run_id=p_run AND source_view_id=result AND position=p_position AND supersedes_source_view_id IS NOT DISTINCT FROM (product->>'replaces_source_view_id')::bigint) THEN
   RAISE EXCEPTION 'terminal source view replay cannot change selection' USING ERRCODE='P0004'; END IF;
  RETURN result;
 END IF;
 INSERT INTO ops.run_source_view(run_id,source_view_id,position,supersedes_source_view_id) VALUES(p_run,result,p_position,(product->>'replaces_source_view_id')::bigint) ON CONFLICT DO NOTHING;
 RETURN result;
END $view$;
REVOKE ALL ON FUNCTION ops.publish_source_view(bigint,bigint,bigint,text,bigint,bytea,bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.publish_source_view(bigint,bigint,bigint,text,bigint,bytea,bytea) TO corpus_sem_writer;

CREATE OR REPLACE FUNCTION ops.select_reused_source_views(p_run bigint,p_task bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $reuse$
DECLARE job ops.task; run ops.run;
BEGIN
 SELECT * INTO STRICT run FROM ops.run WHERE id=p_run FOR SHARE;
 SELECT * INTO STRICT job FROM ops.task WHERE id=p_task AND run_id=p_run;
 PERFORM sem.require_execution_operation(run.release_id,'publish_source_view');
 IF job.status<>'reused' OR job.reused_task_id IS NULL OR NOT ops.valid_reuse(job) OR run.sealed THEN
 RAISE EXCEPTION 'source view reuse is not bound to successful source origin' USING ERRCODE='23514'; END IF;
 INSERT INTO ops.run_source_view(run_id,source_view_id,position)
 SELECT p_run,v.id,s.position FROM kb.source_view v JOIN ops.run_source_view s ON s.source_view_id=v.id JOIN ops.task t ON t.run_id=s.run_id
 WHERE t.id=job.reused_task_id AND v.native_task_id=job.reused_task_id ON CONFLICT DO NOTHING;
END $reuse$;
REVOKE ALL ON FUNCTION ops.select_reused_source_views(bigint,bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.select_reused_source_views(bigint,bigint) TO corpus_sem_writer;

CREATE OR REPLACE FUNCTION ops.capture_native_source_frame(p_task bigint,p_hash text,p_frame jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $frame$
DECLARE job ops.task; view kb.source_view; context jsonb; expected jsonb; previous ops.native_source_frame; sentence jsonb; piece jsonb;
BEGIN
 SELECT * INTO STRICT job FROM ops.task WHERE id=p_task FOR UPDATE;
 PERFORM sem.require_execution_operation(job.release_id,'capture_native_source_frame');
 SELECT * INTO STRICT view FROM kb.source_view WHERE id=(p_frame->>'source_view_id')::bigint;
 IF job.unit_type<>'source_view' OR job.unit_id<>view.id OR job.packet_hash IS DISTINCT FROM p_hash OR job.unit_key IS DISTINCT FROM p_frame->>'unit_ref'
 OR NOT EXISTS(SELECT FROM ops.run_source_view WHERE run_id=job.run_id AND source_view_id=view.id)
 OR p_frame->>'section_pointer' IS DISTINCT FROM view.section_pointer OR p_frame->>'membership' IS DISTINCT FROM view.membership
 OR p_frame->>'text' IS DISTINCT FROM view.projection->>'text'
 OR p_frame->>'projection_digest' IS DISTINCT FROM view.projection_digest OR p_frame->>'recipe_digest' IS DISTINCT FROM view.recipe_digest
 OR (p_frame->'native_product'->>'task_id')::bigint IS DISTINCT FROM view.native_task_id
 OR p_frame->'native_product'->>'product_key' IS DISTINCT FROM view.native_product_key
 OR p_frame->'native_product'->>'content_digest' IS DISTINCT FROM view.native_content_digest THEN
 RAISE EXCEPTION 'native packet frame differs from selected source view/task' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(view.projection->'pieces') WITH ORDINALITY piece(value,n)
  WHERE piece.value->>'kind'='native_text' AND piece.value->>'item_ref' IS NOT NULL AND (piece.value->>'end')::bigint>(piece.value->>'start')::bigint
  AND NOT EXISTS(SELECT FROM jsonb_array_elements(p_frame->'sentences') supplied WHERE supplied->>'id'='native_evidence:'||(piece.n-1)::text)) THEN
 RAISE EXCEPTION 'native evidence alias inventory is incomplete' USING ERRCODE='23514'; END IF;
 FOR sentence IN SELECT value FROM jsonb_array_elements(p_frame->'sentences') WHERE starts_with(value->>'id','native_evidence:') LOOP
  IF substring(sentence->>'id' FROM length('native_evidence:')+1) !~ '^(0|[1-9][0-9]*)$' THEN
   RAISE EXCEPTION 'native evidence alias has an invalid piece ordinal' USING ERRCODE='23514'; END IF;
  piece:=view.projection->'pieces'->(substring(sentence->>'id' FROM length('native_evidence:')+1)::integer);
  IF piece IS NULL OR piece->>'kind'<>'native_text' OR piece->>'item_ref' IS NULL OR (sentence->>'start')::bigint IS DISTINCT FROM (piece->>'start')::bigint OR (sentence->>'end')::bigint IS DISTINCT FROM (piece->>'end')::bigint THEN
   RAISE EXCEPTION 'native evidence alias differs from its exact retained piece' USING ERRCODE='23514'; END IF;
 END LOOP;
 context:=(p_frame->>'native_context')::jsonb;
 SELECT jsonb_build_object('pieces',view.projection->'pieces','health',view.projection->'health',
 'items',(SELECT COALESCE(jsonb_agg(i.native_json ORDER BY ptr.n),'[]') FROM jsonb_array_elements_text(view.projection->'items') WITH ORDINALITY ptr(value,n) JOIN kb.native_document_item i ON i.task_id=view.native_task_id AND i.product_key=view.native_product_key AND i.pointer=ptr.value),
 'ancestors',(SELECT COALESCE(jsonb_agg(i.native_json ORDER BY ptr.n),'[]') FROM jsonb_array_elements_text(COALESCE(view.projection->'ancestors','[]')) WITH ORDINALITY ptr(value,n) JOIN kb.native_document_item i ON i.task_id=view.native_task_id AND i.product_key=view.native_product_key AND i.pointer=ptr.value)) INTO expected
 FROM ops.native_document_product p WHERE p.task_id=view.native_task_id AND p.product_key=view.native_product_key;
 IF context IS DISTINCT FROM expected THEN RAISE EXCEPTION 'native packet omitted or changed supplied source context' USING ERRCODE='23514'; END IF;
 SELECT * INTO previous FROM ops.native_source_frame WHERE task_id=p_task;
 IF FOUND THEN
  IF previous.packet_hash<>p_hash OR previous.context_json IS DISTINCT FROM context
   OR (SELECT count(*) FROM ops.native_source_frame_sentence WHERE task_id=p_task)<>jsonb_array_length(p_frame->'sentences')
   OR EXISTS(SELECT FROM jsonb_array_elements(p_frame->'sentences') item LEFT JOIN ops.native_source_frame_sentence saved ON saved.task_id=p_task AND saved.sentence_id=item->>'id'
    WHERE saved.task_id IS NULL OR saved.locator IS DISTINCT FROM item->>'locator' OR saved.start_offset IS DISTINCT FROM (item->>'start')::bigint OR saved.end_offset IS DISTINCT FROM (item->>'end')::bigint)
  THEN RAISE EXCEPTION 'immutable native frame replay differs' USING ERRCODE='23514'; END IF;
  RETURN;
 END IF;
 INSERT INTO ops.native_source_frame VALUES(p_task,p_hash,p_frame->>'unit_ref',view.id,view.native_task_id,view.native_product_key,view.native_content_digest,view.projection_digest,view.recipe_digest,context);
 FOR sentence IN SELECT value FROM jsonb_array_elements(p_frame->'sentences') LOOP
  IF (sentence->>'start')::bigint<0 OR (sentence->>'end')::bigint<=(sentence->>'start')::bigint OR (sentence->>'end')::bigint>char_length(view.projection->>'text') THEN
   RAISE EXCEPTION 'native frame sentence lies outside projected text' USING ERRCODE='23514'; END IF;
  PERFORM ops.native_source_address(view.id,sentence->>'locator',(sentence->>'start')::bigint,(sentence->>'end')::bigint);
  INSERT INTO ops.native_source_frame_sentence VALUES(p_task,sentence->>'id',sentence->>'locator',(sentence->>'start')::bigint,(sentence->>'end')::bigint);
 END LOOP;
END $frame$;
REVOKE ALL ON FUNCTION ops.capture_native_source_frame(bigint,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.capture_native_source_frame(bigint,text,jsonb) TO corpus_sem_writer;

CREATE OR REPLACE FUNCTION ops.select_source_view(p_run bigint,p_source_run bigint,p_view bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $select$
DECLARE target ops.run; origin ops.run;
BEGIN
 SELECT * INTO STRICT target FROM ops.run WHERE id=p_run FOR SHARE;
 SELECT * INTO STRICT origin FROM ops.run WHERE id=p_source_run;
 PERFORM sem.require_execution_operation(target.release_id,'publish_source_view');
 IF target.sealed OR target.project_id<>origin.project_id OR target.release_id<>origin.release_id OR NOT EXISTS(SELECT FROM ops.run_source_view WHERE run_id=p_source_run AND source_view_id=p_view) THEN
 RAISE EXCEPTION 'source request selection differs from qualified origin' USING ERRCODE='23514'; END IF;
 INSERT INTO ops.run_source_view(run_id,source_view_id,position) VALUES(p_run,p_view,0) ON CONFLICT DO NOTHING;
END $select$;
REVOKE ALL ON FUNCTION ops.select_source_view(bigint,bigint,bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.select_source_view(bigint,bigint,bigint) TO corpus_sem_writer;

CREATE OR REPLACE FUNCTION ops.publish_pdf_region_artifact(p_task bigint,p_attempt bigint,p_holder text,p_selection jsonb,p_recipe bytea,p_content bytea) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $artifact$
DECLARE job ops.task; run ops.run; product ops.native_document_product; previous ops.native_region_artifact; digest text;
BEGIN
 SELECT * INTO STRICT job FROM ops.task WHERE id=p_task FOR UPDATE;
 SELECT * INTO STRICT run FROM ops.run WHERE id=job.run_id FOR SHARE;
 PERFORM sem.require_execution_operation(run.release_id,'publish_pdf_region_artifact');
 IF run.sealed OR job.status<>'running' OR job.attempt<>p_attempt OR job.claimed_by IS DISTINCT FROM p_holder THEN RAISE EXCEPTION 'region artifact attempt lost' USING ERRCODE='P0004'; END IF;
 SELECT * INTO STRICT product FROM ops.native_document_product WHERE task_id=(p_selection->>'task_id')::bigint AND product_key=p_selection->>'product_key' AND content_digest=p_selection->>'content_digest';
 IF NOT EXISTS(SELECT FROM ops.source_build b JOIN kb.document d ON d.content_hash=b.artifact_digest WHERE b.task_id=product.task_id AND d.project_id=run.project_id AND
 ((job.unit_type='document' AND job.unit_id=d.id) OR (job.unit_type='source_view' AND EXISTS(SELECT FROM kb.source_view v JOIN ops.run_source_view rs ON rs.source_view_id=v.id WHERE rs.run_id=run.id AND v.id=job.unit_id AND v.document_id=d.id))))
 OR NOT EXISTS(SELECT FROM kb.native_document_region WHERE task_id=product.task_id AND product_key=product.product_key AND pointer=p_selection->>'pointer' AND region_index=(p_selection->>'region_index')::bigint) THEN
 RAISE EXCEPTION 'render artifact is outside selected native original/region' USING ERRCODE='23514'; END IF;
 digest:=encode(sha256(p_content),'hex');
 SELECT * INTO previous FROM ops.native_region_artifact WHERE task_id=p_task;
 IF FOUND THEN
 IF previous.artifact_digest<>digest OR previous.recipe_digest<>encode(sha256(p_recipe),'hex') THEN RAISE EXCEPTION 'immutable region artifact replay differs' USING ERRCODE='23514'; END IF;
 RETURN digest; END IF;
 INSERT INTO kb.source_artifact SELECT encode(sha256(content),'hex'),content FROM unnest(ARRAY[p_recipe,p_content]) content ON CONFLICT DO NOTHING;
 INSERT INTO ops.native_region_artifact VALUES(p_task,product.task_id,product.product_key,product.content_digest,p_selection->>'pointer',(p_selection->>'region_index')::bigint,encode(sha256(p_recipe),'hex'),digest);
 RETURN digest;
END $artifact$;
REVOKE ALL ON FUNCTION ops.publish_pdf_region_artifact(bigint,bigint,text,jsonb,bytea,bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.publish_pdf_region_artifact(bigint,bigint,text,jsonb,bytea,bytea) TO corpus_sem_writer;

CREATE OR REPLACE FUNCTION ops.add_source_task_dependency(p_child bigint,p_parent bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $dependency$
DECLARE child ops.task; parent ops.task; view kb.source_view; ancestor kb.source_view; dependency text;
BEGIN
 SELECT * INTO STRICT child FROM ops.task WHERE id=p_child;
 SELECT * INTO STRICT parent FROM ops.task WHERE id=p_parent;
 PERFORM sem.require_execution_operation(child.release_id,'schedule');
 SELECT * INTO STRICT view FROM kb.source_view WHERE id=child.unit_id;
 SELECT * INTO STRICT ancestor FROM kb.source_view WHERE id=parent.unit_id;
 SELECT params->>'source_dependencies' INTO dependency FROM ops.method_config WHERE id=child.method_config_id;
 IF child.run_id<>parent.run_id OR child.unit_type<>'source_view' OR parent.unit_type<>'source_view'
 OR view.native_task_id<>ancestor.native_task_id OR view.native_product_key<>ancestor.native_product_key OR view.native_content_digest<>ancestor.native_content_digest THEN
 RAISE EXCEPTION 'source prerequisite is outside bound run/product' USING ERRCODE='23514'; END IF;
 IF dependency='ancestor_source_view' THEN
  IF child.method_config_id<>parent.method_config_id OR NOT(view.projection->'ancestors' ? ancestor.section_pointer) THEN
   RAISE EXCEPTION 'source prerequisite is not a declared ancestor' USING ERRCODE='23514'; END IF;
 ELSIF dependency='source_view_interpretation' THEN
  IF child.unit_id<>parent.unit_id OR NOT EXISTS(SELECT FROM ops.method_config consumer JOIN ops.method_config producer ON producer.id=parent.method_config_id JOIN ops.method method ON method.id=producer.method_id
    WHERE consumer.id=child.method_config_id AND consumer.params->>'source_dependency_method'=method.name) THEN
   RAISE EXCEPTION 'source prerequisite is not the declared same-view interpretation producer' USING ERRCODE='23514'; END IF;
 ELSE RAISE EXCEPTION 'source method has no admitted prerequisite declaration' USING ERRCODE='23514'; END IF;
 INSERT INTO ops.task_dependency VALUES(p_child,p_parent,dependency) ON CONFLICT DO NOTHING;
END $dependency$;
REVOKE ALL ON FUNCTION ops.add_source_task_dependency(bigint,bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.add_source_task_dependency(bigint,bigint) TO corpus_sem_writer;

CREATE OR REPLACE FUNCTION ops.validate_measurement_definition() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $fn$
DECLARE bound_release text; task_run bigint;
BEGIN
 SELECT r.release_id,t.run_id INTO bound_release,task_run FROM ops.task t JOIN ops.run r ON r.id=t.run_id WHERE t.id=NEW.task_id;
 IF task_run IS DISTINCT FROM NEW.run_id THEN RAISE EXCEPTION 'measurement producer run differs from task' USING ERRCODE='23514'; END IF;
 IF bound_release IS NOT NULL AND jsonb_typeof(NEW.detail)<>'object' THEN
 RAISE EXCEPTION 'measurement detail requires source object' USING ERRCODE='23514'; END IF;
 IF bound_release IS NOT NULL AND NEW.value IS NOT NULL THEN
 IF NEW.value::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'measurement requires finite source value' USING ERRCODE='23514'; END IF;
 PERFORM NEW.value::double precision;
 END IF;
 IF bound_release IS NOT NULL AND NEW.scope_type='run' AND NEW.scope_id IS NOT NULL AND NOT EXISTS (SELECT FROM ops.run target JOIN ops.run producer ON producer.id=NEW.run_id WHERE target.id=NEW.scope_id AND target.release_id=bound_release AND target.project_id=producer.project_id) THEN
 RAISE EXCEPTION 'measurement run subject is outside bound project/release' USING ERRCODE='23514'; END IF;
 IF bound_release IS NOT NULL AND NEW.scope_type='source_view' AND NOT EXISTS(SELECT FROM kb.source_view v JOIN ops.run_source_view r ON r.source_view_id=v.id WHERE r.run_id=NEW.run_id AND (NEW.scope_id IS NULL OR v.id=NEW.scope_id) AND (NEW.scope_key IS NULL OR v.key=NEW.scope_key)) THEN RAISE EXCEPTION 'source-view metric outside selected run' USING ERRCODE='23514'; END IF;
 IF bound_release IS NOT NULL AND NEW.scope_type='segment' AND NOT EXISTS (SELECT FROM kb.segment s JOIN kb.rendition rd ON rd.id=s.rendition_id JOIN kb.document doc ON doc.id=rd.document_id JOIN ops.run producer ON producer.id=NEW.run_id WHERE doc.project_id=producer.project_id AND (NEW.scope_id IS NOT NULL OR NEW.scope_key IS NOT NULL) AND (NEW.scope_id IS NULL OR s.id=NEW.scope_id) AND (NEW.scope_key IS NULL OR s.segment_key=NEW.scope_key)) THEN
 RAISE EXCEPTION 'measurement segment subject is outside bound project' USING ERRCODE='23514'; END IF;
 IF bound_release IS NOT NULL AND NOT EXISTS (SELECT FROM sem.metric_definition d WHERE d.release_id=bound_release AND d.metric_id=NEW.metric AND d.subject_kind=NEW.scope_type) THEN
 RAISE EXCEPTION 'unresolved metric or incompatible measurement subject' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $fn$;

CREATE OR REPLACE FUNCTION ops.complete_task(p_task bigint,p_attempt bigint,p_holder text,p_rows jsonb,p_outcome text,p_error jsonb,p_envelope jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE t ops.task; r ops.run; item jsonb; ids bigint[] := '{}'; oid bigint; digest text; native_input jsonb; origin kb.observation; view kb.source_view; ancestor kb.source_view;
BEGIN
 SELECT * INTO STRICT t FROM ops.task WHERE id=p_task;
 SELECT * INTO STRICT r FROM ops.run WHERE id=t.run_id FOR SHARE;
 SELECT * INTO STRICT t FROM ops.task WHERE id=p_task FOR UPDATE;
 digest := encode(sha256(convert_to(jsonb_build_array(p_rows,p_outcome,p_error,p_envelope)::text,'UTF8')),'hex');
 IF t.status IN ('done','empty','failed') AND t.attempt=p_attempt AND t.claimed_by=p_holder AND t.result_digest=digest THEN
   RETURN jsonb_build_object('transaction','replay','receipt',jsonb_build_object('task_id',t.id,'run_id',t.run_id,'release_id',t.release_id,'attempt',t.attempt,'protocol',t.status,'result_digest',t.result_digest,'observation_ids',to_jsonb(ARRAY(SELECT id FROM kb.observation WHERE task_id=t.id ORDER BY ordinal))));
 END IF;
 IF r.sealed OR r.status NOT IN ('created','running') OR t.status<>'running' OR t.attempt<>p_attempt OR t.claimed_by IS DISTINCT FROM p_holder THEN
   RAISE EXCEPTION 'task attempt lost or run sealed' USING ERRCODE='P0004';
 END IF;
 IF p_outcome NOT IN ('done','empty','failed') OR (p_outcome='done')<>(jsonb_array_length(p_rows)>0) OR (p_outcome='failed')<>(p_error<>'null'::jsonb) THEN
   RAISE EXCEPTION 'inconsistent terminal outcome';
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
   IF t.unit_type='source_view' AND (item->>'source_view_id')::bigint IS DISTINCT FROM t.unit_id THEN
    RAISE EXCEPTION 'native observation differs from producing source-view task unit' USING ERRCODE='23514'; END IF;
   IF item->>'rendition_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM ops.run_rendition rr WHERE rr.run_id=t.run_id AND rr.rendition_id=(item->>'rendition_id')::bigint) THEN
     RAISE EXCEPTION 'observation rendition outside run';
   END IF;
   IF item->>'source_view_id' IS NOT NULL THEN
    IF item->>'rendition_id' IS NOT NULL OR item->>'span_id' IS NOT NULL OR item->>'segment_id' IS NOT NULL OR NOT EXISTS(SELECT FROM ops.run_source_view WHERE run_id=t.run_id AND source_view_id=(item->>'source_view_id')::bigint) THEN
     RAISE EXCEPTION 'native observation is outside run or aliases coordinates' USING ERRCODE='23514'; END IF;
    SELECT * INTO STRICT view FROM kb.source_view WHERE id=(item->>'source_view_id')::bigint;
    FOR native_input IN SELECT value FROM jsonb_array_elements(COALESCE(item->'payload'->'inputs','[]')) LOOP
     IF jsonb_typeof(native_input) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: PdfNativeObservationInput' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(native_input) key WHERE key<>ALL(ARRAY['observation_key','role'])) OR NOT (native_input ? 'observation_key') OR (native_input ? 'observation_key' AND (jsonb_typeof(native_input->'observation_key') IS DISTINCT FROM 'string')) OR NOT (native_input ? 'role') OR (native_input ? 'role' AND (jsonb_typeof(native_input->'role') IS DISTINCT FROM 'string' OR native_input->>'role' NOT IN ('binding_site','mention','native_analysis','native_parent_context'))) THEN RAISE EXCEPTION 'parsing record shape differs: PdfNativeObservationInput' USING ERRCODE='23514'; END IF;

     SELECT * INTO STRICT origin FROM kb.observation WHERE release_id=t.release_id AND observation_key=native_input->>'observation_key';
     IF NOT EXISTS(SELECT FROM ops.task selected WHERE selected.run_id=t.run_id AND (selected.id=origin.task_id OR selected.reused_task_id=origin.task_id) AND selected.status IN ('done','empty','reused')) THEN
      RAISE EXCEPTION 'native observation input is not a selected completed source' USING ERRCODE='23514'; END IF;
     SELECT * INTO STRICT ancestor FROM kb.source_view WHERE id=origin.source_view_id;
     IF ancestor.native_task_id<>view.native_task_id OR ancestor.native_product_key<>view.native_product_key OR ancestor.native_content_digest<>view.native_content_digest
       OR (native_input->>'role'='native_parent_context' AND NOT(view.projection->'ancestors' ? ancestor.section_pointer))
       OR (native_input->>'role'<>'native_parent_context' AND ancestor.id<>view.id)
       OR (native_input->>'role'='native_analysis' AND origin.kind<>'record') THEN
      RAISE EXCEPTION 'native observation input differs from its declared source relation' USING ERRCODE='23514'; END IF;
    END LOOP;
    IF item->'payload'->>'native_pointer' IS NOT NULL AND NOT EXISTS(SELECT FROM kb.source_view v JOIN kb.native_document_item n ON n.task_id=v.native_task_id AND n.product_key=v.native_product_key AND n.pointer=item->'payload'->>'native_pointer' WHERE v.id=(item->>'source_view_id')::bigint AND v.projection->'items' ? n.pointer) THEN
     RAISE EXCEPTION 'native observation pointer outside selected view' USING ERRCODE='23514'; END IF;
    IF num_nonnulls(item->'payload'->>'projected_start',item->'payload'->>'projected_end') NOT IN (0,2)
      OR num_nonnulls(item->'payload'->>'recognized_start',item->'payload'->>'recognized_end') NOT IN (0,2)
      OR (item->'payload'->>'recognized_start' IS NOT NULL AND NOT EXISTS(SELECT FROM kb.native_document_item n WHERE n.task_id=view.native_task_id AND n.product_key=view.native_product_key AND n.pointer=item->'payload'->>'native_pointer' AND 0<=(item->'payload'->>'recognized_start')::bigint AND (item->'payload'->>'recognized_start')::bigint<(item->'payload'->>'recognized_end')::bigint AND (item->'payload'->>'recognized_end')::bigint<=char_length(n.native_json->>'text'))) THEN
     RAISE EXCEPTION 'native observation extent is not a qualified native/projected range' USING ERRCODE='23514'; END IF;
    IF item->'payload'->>'projected_start' IS NOT NULL AND NOT EXISTS(SELECT FROM kb.source_view v WHERE v.id=(item->>'source_view_id')::bigint AND 0<=(item->'payload'->>'projected_start')::bigint AND (item->'payload'->>'projected_start')::bigint<(item->'payload'->>'projected_end')::bigint AND (item->'payload'->>'projected_end')::bigint<=char_length(v.projection->>'text')) THEN
     RAISE EXCEPTION 'native projected observation outside text' USING ERRCODE='23514'; END IF;
   END IF;
   INSERT INTO kb.observation(task_id,release_id,observation_key,ordinal,kind,payload_definition,payload,rendition_id,segment_id,span_id,score,outcome,source_view_id)
   VALUES(t.id,t.release_id,item->>'observation_key',(item->>'ordinal')::bigint,item->>'kind',item->>'payload_definition',item->'payload',(item->>'rendition_id')::bigint,(item->>'segment_id')::bigint,(item->>'span_id')::bigint,(item->>'score')::numeric,coalesce(item->>'outcome','produced'),(item->>'source_view_id')::bigint) RETURNING id INTO oid;
   ids:=array_append(ids,oid);
 END LOOP;
 IF p_envelope IS NOT NULL THEN INSERT INTO ops.task_result(task_id,release_id,body) VALUES(t.id,t.release_id,p_envelope); END IF;
 UPDATE ops.task SET status=p_outcome,result_digest=digest,error=CASE WHEN coalesce(t.error ? 'semantic_proposal_first_result',false) THEN coalesce(nullif(p_error,'null'::jsonb),'{}'::jsonb)||jsonb_build_object('semantic_proposal_first_result',t.error->'semantic_proposal_first_result') ELSE nullif(p_error,'null'::jsonb) END,finished_at=clock_timestamp(),lease_until=NULL WHERE id=t.id;
 RETURN jsonb_build_object('transaction','applied','receipt',jsonb_build_object('task_id',t.id,'run_id',t.run_id,'release_id',t.release_id,'attempt',t.attempt,'protocol',p_outcome,'result_digest',digest,'observation_ids',to_jsonb(ids)));
END $$;
ALTER FUNCTION ops.complete_task(bigint,bigint,text,jsonb,text,jsonb,jsonb) OWNER TO corpus_sem_publisher;
REVOKE ALL ON FUNCTION ops.complete_task(bigint,bigint,text,jsonb,text,jsonb,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.complete_task(bigint,bigint,text,jsonb,text,jsonb,jsonb) TO corpus_sem_writer;


SET LOCAL role TO 'corpus_sem_publisher';
CREATE OR REPLACE FUNCTION sem.require_execution_projection(r text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE document jsonb; model jsonb; actual jsonb; expected jsonb;
BEGIN
 SELECT convert_from(prepared_bytes,'UTF8')::jsonb INTO STRICT document FROM sem.release WHERE release_id=r;
 -- Historical finalized archives retain their recorded projection ABI without backfill.
 IF (SELECT convert_from(manifest_bytes,'UTF8')::jsonb->'profile'->>'compiler_version' FROM sem.release WHERE release_id=r)<>'13' THEN RETURN; END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('kind',kind,'name',name,'body_hex',encode(body,'hex')) ORDER BY kind,name),'[]'::jsonb) INTO actual FROM sem.registry_row WHERE release_id=r;
 SELECT COALESCE(jsonb_agg(value ORDER BY value->>'kind',value->>'name'),'[]'::jsonb) INTO expected FROM jsonb_array_elements(document->'products'->'registry_rows');
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'archived registry projection differs' USING ERRCODE='23514'; END IF;
 SELECT convert_from(body,'UTF8')::jsonb INTO model FROM sem.registry_row WHERE release_id=r AND kind='execution_model';
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb) INTO expected FROM (SELECT r release_id,o->>'id' operation_id,o->>'implementation' implementation_id,b->>'version' implementation_version FROM jsonb_array_elements(model->'operations') o JOIN jsonb_array_elements(model->'implementations') b ON b->>'id'=o->>'implementation') x;
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb) INTO actual FROM sem.execution_operation x WHERE release_id=r;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'archived execution_operation projection differs' USING ERRCODE='23514'; END IF;
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb) INTO expected FROM (SELECT r release_id,t->>'id' transition_id,t->>'operation' operation_id,t->>'lifecycle' lifecycle FROM jsonb_array_elements(model->'transitions') t) x;
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb) INTO actual FROM sem.execution_transition x WHERE release_id=r;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'archived execution_transition projection differs' USING ERRCODE='23514'; END IF;
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb) INTO expected FROM (SELECT r release_id,t->>'id' transition_id,b.value prior_state,a.value result_state FROM jsonb_array_elements(model->'transitions') t CROSS JOIN LATERAL jsonb_array_elements_text(t->'from_states') b CROSS JOIN LATERAL jsonb_array_elements_text(t->'to_states') a) x;
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb) INTO actual FROM sem.execution_edge x WHERE release_id=r;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'archived execution_edge projection differs' USING ERRCODE='23514'; END IF;
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb) INTO expected FROM (SELECT r release_id,o->>'id' operation_id,e.value effect_id,(SELECT d->>'version' FROM jsonb_array_elements(model->'effect_definitions') d WHERE d->>'id'=e.value) effect_version FROM jsonb_array_elements(model->'operations') o CROSS JOIN LATERAL jsonb_array_elements_text(o->'effects') e) x;
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb) INTO actual FROM sem.operation_effect x WHERE release_id=r;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'archived operation_effect projection differs' USING ERRCODE='23514'; END IF;
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb) INTO expected FROM (SELECT r release_id,t->>'id' transition_id,e.value effect_id,(SELECT d->>'version' FROM jsonb_array_elements(model->'effect_definitions') d WHERE d->>'id'=e.value) effect_version FROM jsonb_array_elements(model->'transitions') t CROSS JOIN LATERAL jsonb_array_elements_text(t->'effects') e) x;
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb) INTO actual FROM sem.transition_effect x WHERE release_id=r;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'archived transition_effect projection differs' USING ERRCODE='23514'; END IF;
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb) INTO expected FROM (SELECT r release_id,rule->>'policy_id' policy_id,rule->>'evidence_tier' evidence_tier,rule->>'agreement' agreement,rule->>'decision' decision,rule->>'decision_tier' decision_tier FROM sem.artifact a CROSS JOIN LATERAL jsonb_array_elements(convert_from(a.content,'UTF8')::jsonb->'decision_rules') rule WHERE a.release_id=r AND a.artifact_name='operation/scientific-policy.json') x;
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb) INTO actual FROM sem.scientific_decision_rule x WHERE release_id=r;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'archived scientific_decision_rule projection differs' USING ERRCODE='23514'; END IF;
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb) INTO expected FROM (WITH declarations AS (SELECT d FROM jsonb_array_elements(document->'products'->'definitions') d), props AS (
 SELECT d,p FROM declarations CROSS JOIN LATERAL jsonb_array_elements(d->'properties') p
 ) SELECT DISTINCT r release_id,d->>'iri' class_id,p->>'iri' property_id,roles.role
 FROM props CROSS JOIN LATERAL (
 SELECT 'identity' role WHERE EXISTS(SELECT FROM jsonb_array_elements(d->'identity_groups') g CROSS JOIN LATERAL jsonb_array_elements_text(g) member WHERE member.value=p->>'name')
 UNION ALL SELECT 'required' WHERE (p->>'required')::boolean OR COALESCE((p->>'minimum_cardinality')::integer,0)>0
 UNION ALL SELECT 'display' WHERE EXISTS(SELECT FROM sem.registry_row reg WHERE reg.release_id=r AND reg.kind='operation_property' AND convert_from(reg.body,'UTF8')::jsonb->>'class'=d->>'name' AND convert_from(reg.body,'UTF8')::jsonb->>'property'=p->>'iri' AND convert_from(reg.body,'UTF8')::jsonb->>'cs:role'='display')
 ) roles) x;
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb) INTO actual FROM sem.operation_property_role x WHERE release_id=r;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'archived operation_property_role projection differs' USING ERRCODE='23514'; END IF;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION sem.require_execution_projection (text) FROM PUBLIC;
SET LOCAL role TO 'corpus_sem_publisher';
CREATE OR REPLACE FUNCTION sem.refuse_immutable_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'pg_temp' AS $$
BEGIN
 RAISE EXCEPTION 'immutable semantic content: %.% %',TG_TABLE_SCHEMA,TG_TABLE_NAME,TG_OP USING ERRCODE='23514';
END
$$;
CREATE OR REPLACE FUNCTION sem.guard_finalized_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
BEGIN
 IF EXISTS(SELECT FROM sem.release_finalization WHERE release_id=NEW.release_id) THEN
  RAISE EXCEPTION 'finalized release cannot acquire intrinsic meaning: %',NEW.release_id USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END
$$;
CREATE OR REPLACE FUNCTION sem.publish_release_archive(payload jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE r text; digest text; relation_name text; actual jsonb; expected jsonb; replay boolean;
 names constant text[]:=ARRAY['release','input','artifact','registry_row','class_definition','property_definition','vocabulary_member','metric_definition','execution_operation','scientific_decision_rule','class_hierarchy','property_applicability','identity_slot','conditional_rule','execution_transition','operation_effect','conditional_atom','execution_edge','transition_effect','operation_property_role'];
BEGIN
 PERFORM sem.require_admission_caller();
 IF jsonb_typeof(payload)<>'object' OR ARRAY(SELECT jsonb_object_keys(payload) ORDER BY 1)
   IS DISTINCT FROM ARRAY(SELECT unnest(names) ORDER BY 1) THEN
  RAISE EXCEPTION 'archive relation set differs' USING ERRCODE='23514'; END IF;
 IF jsonb_array_length(payload->'release')<>1 THEN RAISE EXCEPTION 'one complete release required'; END IF;
 r:=payload->'release'->0->>'release_id'; digest:=payload->'release'->0->>'content_digest';
 IF r IS NULL OR digest IS NULL THEN RAISE EXCEPTION 'archive identity missing'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(r,0));
 replay:=EXISTS(SELECT FROM sem.release_finalization WHERE release_id=r);
 FOREACH relation_name IN ARRAY names LOOP
  IF jsonb_typeof(payload->relation_name)<>'array' THEN RAISE EXCEPTION 'archive rows must be arrays'; END IF;
  IF EXISTS(SELECT FROM jsonb_array_elements(payload->relation_name) row WHERE row->>'release_id' IS DISTINCT FROM r) THEN
   RAISE EXCEPTION 'archive row has wrong release' USING ERRCODE='23514'; END IF;
  EXECUTE format('SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),''[]''::jsonb) FROM jsonb_populate_recordset(NULL::sem.%I,$1) t',relation_name)
   INTO expected USING payload->relation_name;
  IF NOT replay THEN
   EXECUTE format('INSERT INTO sem.%I SELECT * FROM jsonb_populate_recordset(NULL::sem.%I,$1)',relation_name,relation_name) USING payload->relation_name;
  END IF;
  EXECUTE format('SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),''[]''::jsonb) FROM sem.%I t WHERE release_id=$1',relation_name)
   INTO actual USING r;
  IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'archive replay differs: %',relation_name USING ERRCODE='23505'; END IF;
 END LOOP;
 IF EXISTS(SELECT FROM sem.release WHERE release_id=r AND encode(sha256(prepared_bytes),'hex')<>content_digest)
 OR EXISTS(SELECT FROM sem.input WHERE release_id=r AND encode(sha256(content),'hex')<>content_digest)
 OR EXISTS(SELECT FROM sem.artifact WHERE release_id=r AND encode(sha256(content),'hex')<>content_digest) THEN
  RAISE EXCEPTION 'archive content digest differs' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM sem.release WHERE release_id=r AND (release_id<>'release:'||encode(sha256(manifest_bytes),'hex') OR convert_from(prepared_bytes,'UTF8')::jsonb->'products'->>'release_id' IS DISTINCT FROM release_id)) THEN RAISE EXCEPTION 'archive manifest identity differs' USING ERRCODE='23514'; END IF;
 PERFORM sem.require_archive_bytes(r);
 PERFORM sem.require_execution_projection(r);
 IF NOT replay THEN INSERT INTO sem.release_finalization VALUES(r,digest); END IF;
 RETURN r;
END
$$;
CREATE OR REPLACE FUNCTION sem.record_deployment_admission(r text, p text, d text, k text, c bytea) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
BEGIN
 PERFORM sem.require_admission_caller();
 IF NOT EXISTS(SELECT FROM sem.release_finalization WHERE release_id=r) THEN RAISE EXCEPTION 'release is not finalized'; END IF;
 INSERT INTO sem.deployment_admission VALUES(r,p,d,k,c,encode(sha256(c),'hex')) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT FROM sem.deployment_admission WHERE release_id=r AND physical_id=p AND deployment_id=d AND kind=k AND content=c AND content_digest=encode(sha256(c),'hex')) THEN
  RAISE EXCEPTION 'deployment admission replay differs' USING ERRCODE='23505'; END IF;
END
$$;
CREATE OR REPLACE FUNCTION sem.record_sql_admission(r text, ik text, n text, p text, c bytea) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
BEGIN
 PERFORM sem.require_admission_caller();
 IF NOT EXISTS(SELECT FROM sem.release_finalization WHERE release_id=r) THEN RAISE EXCEPTION 'release is not finalized'; END IF;
 INSERT INTO sem.sql_admission(release_id,input_kind,input_name,physical_id,content,content_digest)
 VALUES(r,ik,n,p,c,encode(sha256(c),'hex')) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT FROM sem.sql_admission WHERE release_id=r AND input_kind=ik AND input_name=n AND physical_id=p AND content=c AND content_digest=encode(sha256(c),'hex')) THEN
  RAISE EXCEPTION 'SQL admission replay differs' USING ERRCODE='23505'; END IF;
END
$$;
CREATE OR REPLACE FUNCTION sem.activate_release(p text, r text, parent text, g bigint) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE result bigint;
BEGIN
 PERFORM sem.require_admission_caller();
 IF NOT EXISTS(SELECT FROM sem.release_finalization WHERE release_id=r) THEN RAISE EXCEPTION 'release is not finalized'; END IF;
 PERFORM data.require_execution_release(r);
 UPDATE data.project SET active_release_id=r,generation=generation+1
 WHERE project_id=p AND active_release_id IS NOT DISTINCT FROM parent AND generation=g RETURNING generation INTO result;
 IF NOT FOUND THEN RAISE EXCEPTION 'stale activation token' USING ERRCODE='40001'; END IF;
 RETURN result;
END
$$;
CREATE OR REPLACE FUNCTION data.begin_inference_workspace(r text, z text, revision bigint, snapshot text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
BEGIN
 IF current_setting('transaction_isolation') NOT IN ('repeatable read','serializable') OR nullif(snapshot,'') IS NULL THEN
  RAISE EXCEPTION 'inference requires bound repeatable snapshot'; END IF;
 IF NOT EXISTS(SELECT FROM data.realization WHERE release_id=r AND realization_id=z AND data_revision=revision) THEN
  RAISE EXCEPTION 'inference source revision differs' USING ERRCODE='P0004'; END IF;
 IF to_regclass('pg_temp.semantic_inference_work') IS NOT NULL OR to_regclass('pg_temp.semantic_inference_binding') IS NOT NULL THEN
  RAISE EXCEPTION 'preexisting inference workspace'; END IF;
 CREATE TEMP TABLE semantic_inference_binding(release_id text,realization_id text,data_revision bigint,snapshot text) ON COMMIT DROP;
 INSERT INTO pg_temp.semantic_inference_binding VALUES(r,z,revision,snapshot);
 CREATE TEMP TABLE semantic_inference_work(subject text NOT NULL,predicate text NOT NULL,object text NOT NULL,context text,qualification text,context_key text NOT NULL,PRIMARY KEY(subject,predicate,object,context_key)) ON COMMIT DROP;
 GRANT SELECT,INSERT ON pg_temp.semantic_inference_work TO corpus_sem_writer;
 GRANT UPDATE(qualification) ON pg_temp.semantic_inference_work TO corpus_sem_writer;
END
$$;
CREATE OR REPLACE FUNCTION data.end_inference_workspace(r text, z text, revision bigint, snapshot text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE name text;
BEGIN
 FOREACH name IN ARRAY ARRAY['semantic_inference_work','semantic_inference_binding'] LOOP
  IF NOT EXISTS(SELECT FROM pg_class WHERE relnamespace=pg_my_temp_schema() AND relname=name AND relkind='r' AND relpersistence='t' AND relowner=current_user::regrole) THEN
   RAISE EXCEPTION 'untrusted inference workspace'; END IF;
 END LOOP;
 IF (SELECT array_agg(attname||':'||format_type(atttypid,atttypmod) ORDER BY attnum) FROM pg_attribute
      WHERE attrelid='pg_temp.semantic_inference_work'::regclass AND attnum>0 AND NOT attisdropped)
    IS DISTINCT FROM ARRAY['subject:text','predicate:text','object:text','context:text','qualification:text','context_key:text']
 OR (SELECT array_agg(attname||':'||format_type(atttypid,atttypmod) ORDER BY attnum) FROM pg_attribute
      WHERE attrelid='pg_temp.semantic_inference_binding'::regclass AND attnum>0 AND NOT attisdropped)
    IS DISTINCT FROM ARRAY['release_id:text','realization_id:text','data_revision:bigint','snapshot:text'] THEN
  RAISE EXCEPTION 'inference workspace shape differs'; END IF;
 IF NOT EXISTS(SELECT FROM pg_temp.semantic_inference_binding b WHERE (b.release_id,b.realization_id,b.data_revision,b.snapshot)=(r,z,revision,$4)) THEN RAISE EXCEPTION 'inference binding differs'; END IF;
 DROP TABLE pg_temp.semantic_inference_work,pg_temp.semantic_inference_binding;
END
$$;
CREATE OR REPLACE FUNCTION data.require_runtime_principal(purpose text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE principal name:=session_user; required_role text; owner_oid oid;
BEGIN
 required_role:=CASE purpose WHEN 'read' THEN 'corpus_sem_reader' WHEN 'write' THEN 'corpus_sem_writer' WHEN 'evaluate' THEN 'corpus_sem_evaluator' WHEN 'admit' THEN 'corpus_sem_admitter' END;
 IF required_role IS NULL THEN RAISE EXCEPTION 'unknown runtime purpose'; END IF;
 SELECT nspowner INTO owner_oid FROM pg_namespace WHERE nspname='sem';
 IF NOT pg_has_role(principal,required_role,'USAGE') OR current_setting('role') NOT IN ('none',principal::text)
 OR EXISTS(SELECT FROM pg_roles WHERE oid=principal::regrole AND (rolsuper OR rolcreaterole OR rolcreatedb OR rolbypassrls OR rolreplication))
 OR pg_has_role(principal,'corpus_sem_publisher','MEMBER') OR pg_has_role(principal,owner_oid,'MEMBER')
 OR has_database_privilege(principal,current_database(),'TEMP')
 OR EXISTS(SELECT FROM pg_namespace WHERE nspname IN ('sem','data','ops','kb','eval') AND has_schema_privilege(principal,oid,'CREATE'))
 OR EXISTS(SELECT FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('sem','data') AND c.relkind IN ('r','p') AND (has_table_privilege(principal,c.oid,'INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER') OR has_any_column_privilege(principal,c.oid,'INSERT,UPDATE'))) THEN
  RAISE EXCEPTION 'unrestricted or mismatched runtime principal for %',purpose USING ERRCODE='42501'; END IF;
 IF NOT has_table_privilege(principal,'sem.release','SELECT')
 OR (purpose='read' AND NOT has_table_privilege(principal,'data.realization','SELECT'))
 OR (purpose='write' AND NOT has_function_privilege(principal,'data.begin_stage()','EXECUTE'))
 OR (purpose='evaluate' AND NOT has_schema_privilege(principal,'eval','USAGE'))
 OR (purpose='admit' AND NOT has_function_privilege(principal,'sem.publish_release_archive(jsonb)','EXECUTE')) THEN
  RAISE EXCEPTION 'required runtime capability unavailable' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(data.execution_contract_descriptor()->'functions') contract
  JOIN pg_proc p ON p.oid=to_regprocedure(contract->>'signature')
  WHERE has_function_privilege(principal,p.oid,'EXECUTE') IS DISTINCT FROM ((contract->'execute_roles') ? required_role)) THEN
  RAISE EXCEPTION 'runtime operation privileges differ from purpose contract' USING ERRCODE='42501'; END IF;
 IF purpose<>'evaluate'  AND EXISTS(SELECT FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='eval' AND c.relkind IN ('r','p') AND has_table_privilege(principal,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')) THEN
  RAISE EXCEPTION 'runtime principal has independent reference access' USING ERRCODE='42501'; END IF;
END
$$;
CREATE OR REPLACE FUNCTION data.is_bound_statement(r text, c text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE bound text; base text; model jsonb;
BEGIN
 SELECT convert_from(body,'UTF8')::jsonb INTO model FROM sem.registry_row
 WHERE release_id=r AND kind='effective_bindings' AND name='effective-bindings-11';
 IF model IS NOT NULL THEN bound:=model->'statement'->>'class_iri';
 ELSE
  SELECT target.class_id INTO bound FROM sem.class_definition binding
  JOIN sem.property_applicability field ON field.release_id=binding.release_id AND field.class_id=binding.class_id
  JOIN sem.class_definition target ON target.release_id=field.release_id AND target.name=field.range_name
  WHERE binding.release_id=r AND binding.name='AgentStatementBinding' AND field.constraints->>'name'='statement'
   AND NOT field.multivalued AND NOT COALESCE((field.constraints->>'inlined')::boolean,false);
  IF bound IS NULL AND EXISTS(SELECT FROM sem.release WHERE release_id=r AND profile='semantic-1')
     AND NOT EXISTS(SELECT FROM sem.class_definition WHERE release_id=r AND name='AgentStatementBinding') THEN
   SELECT class_id INTO bound FROM sem.class_definition WHERE release_id=r AND name='SourceStatement';
  END IF;
  IF bound IS NULL THEN RAISE EXCEPTION 'missing archived statement binding' USING ERRCODE='23514'; END IF;
  -- Historical archives have no v11 effective product. Validate their explicitly
  -- supported protocol instead of accepting any class named by a legacy binding.
  SELECT class_id INTO base FROM sem.class_definition WHERE release_id=r AND name='SourceStatement';
  IF base IS NULL OR NOT (bound=base OR EXISTS(SELECT FROM sem.class_hierarchy
      WHERE release_id=r AND class_id=bound AND ancestor_id=base))
     OR NOT EXISTS(SELECT FROM sem.class_definition WHERE release_id=r AND class_id=bound AND NOT abstract)
     OR NOT EXISTS(SELECT FROM sem.property_applicability p WHERE p.release_id=r AND p.class_id=bound
       AND p.constraints->>'name'='id' AND NOT p.multivalued
       AND NOT COALESCE((p.constraints->>'inlined')::boolean,false)
       AND p.constraints->>'native_range' IN ('string','uri','uriorcurie')
       AND EXISTS(SELECT FROM sem.identity_slot i WHERE i.release_id=r AND i.class_id=bound
           AND i.group_id='0' AND i.position=0 AND i.property_id=p.property_id)
       AND (SELECT count(*) FROM sem.identity_slot i WHERE i.release_id=r AND i.class_id=bound AND i.group_id='0')=1)
     OR NOT EXISTS(SELECT FROM sem.property_applicability p WHERE p.release_id=r AND p.class_id=bound
       AND p.constraints->>'name'='locator' AND p.required AND NOT p.multivalued
       AND NOT COALESCE((p.constraints->>'inlined')::boolean,false)
       AND p.constraints->>'native_range' IN ('string','uri','uriorcurie'))
     OR NOT EXISTS(SELECT FROM sem.property_applicability p WHERE p.release_id=r AND p.class_id=bound
       AND p.constraints->>'name'='statement_kind' AND NOT p.multivalued
       AND NOT COALESCE((p.constraints->>'inlined')::boolean,false)
       AND EXISTS(SELECT FROM sem.vocabulary_member v WHERE v.release_id=r AND v.vocabulary_id=p.range_name)) THEN
   RAISE EXCEPTION 'invalid archived source-statement protocol; derive a supported bound release' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN bound IS NOT NULL AND EXISTS(SELECT FROM sem.class_definition WHERE release_id=r AND class_id=bound)
  AND (c=bound OR EXISTS(SELECT FROM sem.class_hierarchy WHERE release_id=r AND class_id=c AND ancestor_id=bound));
END
$$;
CREATE OR REPLACE FUNCTION data.check_evidence_source() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE observation kb.observation; ev data.evidence; span kb.span; method_name text;
 operation_version text; uri text; rendition_key text; matched boolean; locator_matched boolean; synthesis jsonb;
 native_view kb.source_view; native_frame ops.native_source_frame; address jsonb; first_offset bigint; last_offset bigint;
BEGIN
 SELECT * INTO STRICT observation FROM kb.observation WHERE id=NEW.observation_id;
 IF NEW.source_view_id IS NOT NULL OR observation.source_view_id IS NOT NULL THEN
  IF observation.release_id IS DISTINCT FROM NEW.release_id OR
   observation.source_view_id IS DISTINCT FROM NEW.source_view_id OR
   NEW.rendition_id IS NOT NULL OR NEW.span_id IS NOT NULL OR observation.rendition_id IS NOT NULL OR
   observation.payload_definition<>'AgentStoredBatch' OR NEW.native_address IS NULL THEN
   RAISE EXCEPTION 'native evidence source differs from its bound observation' USING ERRCODE='23514'; END IF;
  SELECT * INTO STRICT native_view FROM kb.source_view WHERE id=NEW.source_view_id;
  SELECT f.* INTO STRICT native_frame FROM ops.native_source_frame f JOIN ops.task t ON t.id=f.task_id
   AND t.packet_hash=f.packet_hash AND t.unit_key=f.unit_ref WHERE f.task_id=observation.task_id;
  IF native_view.release_id IS DISTINCT FROM observation.release_id OR
   native_frame.source_view_id IS DISTINCT FROM native_view.id OR
   native_frame.product_task_id IS DISTINCT FROM native_view.native_task_id OR
   native_frame.product_key IS DISTINCT FROM native_view.native_product_key OR
   native_frame.product_digest IS DISTINCT FROM native_view.native_content_digest OR
   native_frame.projection_digest IS DISTINCT FROM native_view.projection_digest OR
   native_frame.recipe_digest IS DISTINCT FROM native_view.recipe_digest OR
   native_frame.unit_ref IS DISTINCT FROM observation.payload->>'unit_ref' THEN
   RAISE EXCEPTION 'native evidence frame differs from selected source custody' USING ERRCODE='23514'; END IF;
  SELECT m.name,m.version,d.source_uri INTO STRICT method_name,operation_version,uri
   FROM ops.task t JOIN ops.method_config c ON c.id=t.method_config_id JOIN ops.method m ON m.id=c.method_id
   JOIN kb.document d ON d.id=native_view.document_id WHERE t.id=observation.task_id;
  SELECT * INTO STRICT ev FROM data.evidence WHERE evidence_id=NEW.evidence_id
   AND release_id=NEW.release_id AND realization_id=NEW.realization_id;
  IF (ev.source_uri,ev.provider,ev.operation_version) IS DISTINCT FROM (uri,method_name,operation_version) THEN
   RAISE EXCEPTION 'native evidence provider/source differs from bound observation' USING ERRCODE='23514'; END IF;
  address:=substring(ops.native_source_address(native_view.id,NEW.native_address) FROM 5)::jsonb;
  IF NOT(address ? 'source_view_id') THEN
   RAISE EXCEPTION 'native evidence requires an exact projected quote range' USING ERRCODE='23514'; END IF;
  first_offset:=(address->>'start')::bigint;last_offset:=(address->>'end')::bigint;
  SELECT EXISTS(SELECT FROM jsonb_array_elements(
    COALESCE(observation.payload->'claims','[]'::jsonb)||COALESCE(observation.payload->'unsupported','[]'::jsonb)||
    COALESCE(observation.payload->'identity_exclusions','[]'::jsonb)) item
   CROSS JOIN LATERAL jsonb_array_elements(item->'evidence') citation
   JOIN ops.native_source_frame_sentence supplied ON supplied.task_id=observation.task_id
    AND supplied.sentence_id=citation->>'sentence' AND supplied.locator=citation->>'locator'
   WHERE citation->>'outcome'='located' AND (citation->>'start')::bigint=first_offset
    AND (citation->>'end')::bigint=last_offset AND supplied.start_offset<=first_offset AND supplied.end_offset>=last_offset
    AND substring(native_view.projection->>'text' FROM first_offset::integer+1 FOR (last_offset-first_offset)::integer)
     =citation->>'quote'
    AND ev.locator::jsonb=jsonb_build_object('locator',citation->'locator','start',first_offset,'end',last_offset,'role',citation->'role'))
   INTO matched;
  IF NOT matched THEN RAISE EXCEPTION 'native evidence differs from a located supplied citation' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.native_address IS NOT NULL THEN
  RAISE EXCEPTION 'legacy evidence cannot carry a native source address' USING ERRCODE='23514'; END IF;
 IF observation.release_id<>NEW.release_id OR observation.rendition_id IS DISTINCT FROM NEW.rendition_id THEN
  RAISE EXCEPTION 'evidence source differs from bound observation'; END IF;
 SELECT m.name,m.version,d.source_uri,r.key INTO STRICT method_name,operation_version,uri,rendition_key
  FROM ops.task t JOIN ops.method_config c ON c.id=t.method_config_id
  JOIN ops.method m ON m.id=c.method_id JOIN kb.rendition r ON r.id=NEW.rendition_id
  JOIN kb.document d ON d.id=r.document_id WHERE t.id=observation.task_id;
 SELECT * INTO STRICT ev FROM data.evidence WHERE evidence_id=NEW.evidence_id
  AND release_id=NEW.release_id AND realization_id=NEW.realization_id;
 IF ev.source_uri<>uri OR ev.provider<>method_name OR ev.operation_version<>operation_version THEN
  RAISE EXCEPTION 'evidence provider/source differs from bound observation'; END IF;
 IF NEW.span_id IS NULL THEN
  IF observation.span_id IS NOT NULL THEN RAISE EXCEPTION 'evidence omitted bound source span'; END IF;
  IF ev.locator<>'observation:'||observation.observation_key THEN RAISE EXCEPTION 'evidence locator differs from bound observation'; END IF;
  RETURN NEW;
 END IF;
 IF observation.span_id IS NOT NULL THEN
  IF observation.span_id<>NEW.span_id THEN RAISE EXCEPTION 'evidence span differs from bound observation'; END IF;
  SELECT * INTO STRICT span FROM kb.span WHERE id=NEW.span_id;
  IF ev.locator<>'rendition:'||rendition_key||':span:'||span.start_offset||':'||span.end_offset THEN RAISE EXCEPTION 'evidence locator differs from bound span'; END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO STRICT span FROM kb.span WHERE id=NEW.span_id AND rendition_id=NEW.rendition_id;
 locator_matched:=ev.locator='rendition:'||rendition_key||':span:'||span.start_offset||':'||span.end_offset;
 matched:=false;
 IF observation.payload_definition='AgentStoredBatch' THEN
  SELECT EXISTS(SELECT FROM jsonb_array_elements(
      COALESCE(observation.payload->'claims','[]'::jsonb)||COALESCE(observation.payload->'unsupported','[]'::jsonb)||COALESCE(observation.payload->'identity_exclusions','[]'::jsonb)) item
      CROSS JOIN LATERAL jsonb_array_elements(item->'evidence') citation
      WHERE citation->>'outcome'='located' AND (citation->>'start')::bigint=span.start_offset
       AND (citation->>'end')::bigint=span.end_offset AND (CASE WHEN locator_matched THEN true ELSE ev.locator::jsonb=jsonb_build_object('locator',citation->'locator','start',span.start_offset,'end',span.end_offset,'role',citation->'role') END)) INTO matched;
 ELSIF observation.payload_definition='SourceObservation' AND observation.kind='author_markup' THEN
  synthesis:=data.report_field(observation.payload->'payload','synthesize');
  SELECT EXISTS(SELECT FROM jsonb_array_elements(data.report_field(synthesis,'evidence')->'items') citation
    WHERE (data.report_field(citation,'start')->>'integer')::bigint=span.start_offset
      AND (data.report_field(citation,'end')->>'integer')::bigint=span.end_offset AND locator_matched) INTO matched;
 END IF;
 IF NOT matched THEN RAISE EXCEPTION 'evidence span is not a located citation in bound source report'; END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION data.end_stage() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
BEGIN
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_entity' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['entity_id:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_entity'; END IF; DROP TABLE pg_temp.sp_entity;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_entity_source' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['entity_id:text','observation_id:bigint','local_id:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_entity_source'; END IF; DROP TABLE pg_temp.sp_entity_source;
IF to_regclass('pg_temp.sp_identity_exclusion') IS NOT NULL THEN IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_identity_exclusion' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['exclusion_id:text','observation_id:bigint','local_id:text','left_kind:text','left_ref:text','right_kind:text','right_ref:text','left_entity_id:text','right_entity_id:text','reason:text','operation_id:text','operation_version:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_identity_exclusion'; END IF; DROP TABLE pg_temp.sp_identity_exclusion; END IF;
IF to_regclass('pg_temp.sp_identity_exclusion_evidence') IS NOT NULL THEN IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_identity_exclusion_evidence' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['exclusion_id:text','evidence_id:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_identity_exclusion_evidence'; END IF; DROP TABLE pg_temp.sp_identity_exclusion_evidence; END IF;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_membership' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['entity_id:text','class_id:text','establishment:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_membership'; END IF; DROP TABLE pg_temp.sp_membership;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_typed_value' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['value_id:text','kind:text','text_value:text','integer_value:numeric','numeric_value:numeric','decimal_lexical:text','boolean_value:boolean','entity_id:text','language:text','datatype:text','opaque_payload:jsonb']) THEN RAISE EXCEPTION 'untrusted staging relation sp_typed_value'; END IF; DROP TABLE pg_temp.sp_typed_value;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_value_role' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['parent_value_id:text','role:text','position:bigint','child_value_id:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_value_role'; END IF; DROP TABLE pg_temp.sp_value_role;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_fact' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['fact_id:text','subject_id:text','property_id:text','object_value_id:text','qualification_value_id:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_fact'; END IF; DROP TABLE pg_temp.sp_fact;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_occurrence' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['occurrence_id:text','fact_id:text','source:text','item:text','report_object_value_id:text','report_qualification_value_id:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_occurrence'; END IF; DROP TABLE pg_temp.sp_occurrence;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_support' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['fact_id:text','occurrence_id:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_support'; END IF; DROP TABLE pg_temp.sp_support;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_selection' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['fact_id:text','selected:boolean']) THEN RAISE EXCEPTION 'untrusted staging relation sp_selection'; END IF; DROP TABLE pg_temp.sp_selection;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_evidence' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['evidence_id:text','source_uri:text','locator:text','provider:text','operation_version:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_evidence'; END IF; DROP TABLE pg_temp.sp_evidence;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_occurrence_evidence' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['occurrence_id:text','evidence_id:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_occurrence_evidence'; END IF; DROP TABLE pg_temp.sp_occurrence_evidence;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_occurrence_context' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['occurrence_id:text','statement_entity_id:text','statement_role:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_occurrence_context'; END IF; DROP TABLE pg_temp.sp_occurrence_context;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_occurrence_evidence_role' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['occurrence_id:text','evidence_id:text','role:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_occurrence_evidence_role'; END IF; DROP TABLE pg_temp.sp_occurrence_evidence_role;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_membership_support' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['entity_id:text','class_id:text','evidence_id:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_membership_support'; END IF; DROP TABLE pg_temp.sp_membership_support;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_derivation' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['derivation_id:text','conclusion_fact_id:text','rule:text','rule_version:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_derivation'; END IF; DROP TABLE pg_temp.sp_derivation;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_derivation_premise' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['derivation_id:text','position:bigint','premise_fact_id:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_derivation_premise'; END IF; DROP TABLE pg_temp.sp_derivation_premise;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_coverage' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['coverage_id:text','family:text','scope:text','outcome:text','reason:text','source_outcome:text','required_capability:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_coverage'; END IF; DROP TABLE pg_temp.sp_coverage;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_occurrence_establishment' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['occurrence_id:text','establishment:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_occurrence_establishment'; END IF; DROP TABLE pg_temp.sp_occurrence_establishment;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_evidence_source' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['evidence_id:text','observation_id:bigint','rendition_id:bigint','span_id:bigint','source_view_id:bigint','native_address:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_evidence_source'; END IF; DROP TABLE pg_temp.sp_evidence_source;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_assessment' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['assessment_id:text','operation_id:text','operation_version:text','outcome:text','fact_id:text','occurrence_id:text','confidence:numeric','reason:text','uncertainty:text','counterpart_fact_id:text','counterpart_occurrence_id:text','context_value_id:text','comparison_tier:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_assessment'; END IF; DROP TABLE pg_temp.sp_assessment;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_entity_input' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['entity_id:text','input_realization_id:text','input_data_revision:bigint','input_entity_id:text','run_id:bigint']) THEN RAISE EXCEPTION 'untrusted staging relation sp_entity_input'; END IF; DROP TABLE pg_temp.sp_entity_input;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_fact_input' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['fact_id:text','input_realization_id:text','input_data_revision:bigint','input_fact_id:text','run_id:bigint']) THEN RAISE EXCEPTION 'untrusted staging relation sp_fact_input'; END IF; DROP TABLE pg_temp.sp_fact_input;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_alternative_group' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['group_id:text','reason:text','operation_id:text','operation_version:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_alternative_group'; END IF; DROP TABLE pg_temp.sp_alternative_group;
IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_alternative_member' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)=ARRAY['group_id:text','fact_id:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_alternative_member'; END IF; DROP TABLE pg_temp.sp_alternative_member;
END
$$;
CREATE OR REPLACE FUNCTION data.validate_occurrence_context(r text, z text) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE o data.occurrence; context data.occurrence_context; observation kb.observation;
 edge data.occurrence_evidence; citation_role data.occurrence_evidence_role;
 source data.evidence_source; claim jsonb; statement jsonb; expected_statement text;
 expected_role text; source_rendition_key text; synthesis jsonb;
BEGIN
 IF EXISTS(SELECT FROM data.occurrence_context c WHERE c.release_id=r AND c.realization_id=z
   AND c.statement_role IS NOT NULL AND NOT EXISTS(SELECT FROM sem.vocabulary_member v
     WHERE v.release_id=r AND v.vocabulary_id='StatementRole' AND v.value=c.statement_role)) THEN
  RAISE EXCEPTION 'undeclared occurrence statement role' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM data.occurrence_evidence_role c WHERE c.release_id=r AND c.realization_id=z
   AND NOT EXISTS(SELECT FROM sem.vocabulary_member v WHERE v.release_id=r
    AND v.vocabulary_id='EvidenceRole' AND v.value=c.role)) THEN
  RAISE EXCEPTION 'undeclared occurrence evidence role' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM data.occurrence_context ctx WHERE ctx.release_id=r AND ctx.realization_id=z
   AND ctx.statement_entity_id IS NOT NULL AND NOT EXISTS(
    SELECT FROM data.membership m JOIN sem.class_definition c
     ON c.release_id=m.release_id AND c.class_id=m.class_id
    WHERE m.release_id=r AND m.realization_id=z AND m.entity_id=ctx.statement_entity_id
     AND data.is_bound_statement(r,c.class_id))) THEN
  RAISE EXCEPTION 'occurrence statement lacks SourceStatement membership' USING ERRCODE='23514'; END IF;
 FOR o IN SELECT * FROM data.occurrence WHERE release_id=r AND realization_id=z LOOP
  SELECT * INTO context FROM data.occurrence_context c WHERE c.release_id=r AND c.realization_id=z
    AND c.occurrence_id=o.occurrence_id;
  SELECT * INTO observation FROM kb.observation ob WHERE ob.release_id=r AND ob.observation_key=o.source;
  IF NOT FOUND THEN CONTINUE; END IF;
  IF observation.payload_definition='AgentStoredBatch' AND o.item ~ '^claims/[0-9]+$' THEN
   claim:=observation.payload->'claims'->(split_part(o.item,'/',2)::integer);
   IF claim IS NULL THEN RAISE EXCEPTION 'occurrence claim is outside bound source report'; END IF;
   expected_statement:=NULL;
   expected_role:=claim->>'statement_role';
   IF claim->>'statement' IS NOT NULL THEN
    SELECT value INTO STRICT statement FROM jsonb_array_elements(observation.payload->'statements')
     WHERE value->>'id'=claim->>'statement';
    IF statement->>'kind'<>'outside' THEN
    IF EXISTS(SELECT FROM ops.source_frame WHERE task_id=observation.task_id) AND NOT EXISTS(
       SELECT FROM ops.source_frame f JOIN ops.task t ON t.id=f.task_id WHERE f.task_id=observation.task_id AND f.packet_hash=t.packet_hash
        AND f.unit_ref=observation.payload->>'unit_ref' AND f.rendition_id=observation.rendition_id) THEN
     RAISE EXCEPTION 'statement report differs from its immutable source frame' USING ERRCODE='23514'; END IF;
    IF observation.source_view_id IS NOT NULL THEN
     SELECT v.key INTO STRICT source_rendition_key FROM kb.source_view v JOIN ops.native_source_frame f
      ON f.source_view_id=v.id WHERE f.task_id=observation.task_id AND f.source_view_id=observation.source_view_id
       AND f.unit_ref=observation.payload->>'unit_ref';
     expected_statement:='entity:'||encode(sha256(convert_to(data.canonical_json(
      jsonb_build_array(r,z,'source-statement',source_rendition_key,
                       ops.native_source_statement_locator(observation.task_id,statement->>'anchor'))),'UTF8')),'hex');
    ELSE
     SELECT key INTO STRICT source_rendition_key FROM kb.rendition WHERE id=observation.rendition_id;
     expected_statement:='entity:'||encode(sha256(convert_to(data.canonical_json(
      jsonb_build_array(r,z,'source-statement',source_rendition_key,ops.source_statement_locator(observation.task_id,statement->>'anchor'))),'UTF8')),'hex');
    END IF;
    END IF;
   END IF;
   IF (context.statement_entity_id,context.statement_role) IS DISTINCT FROM
      (expected_statement,expected_role) THEN
    RAISE EXCEPTION 'occurrence statement context differs from bound source claim' USING ERRCODE='23514'; END IF;
   IF EXISTS(SELECT FROM jsonb_array_elements(claim->'evidence') WITH ORDINALITY citation(value,position)
     WHERE citation.value->>'outcome'='located' AND citation.value->>'role' IS NOT NULL
      AND NOT EXISTS(SELECT FROM data.occurrence_evidence_role role
       WHERE role.release_id=r AND role.realization_id=z AND role.occurrence_id=o.occurrence_id
        AND role.role=citation.value->>'role'
        AND role.evidence_id='evidence:'||encode(sha256(convert_to(data.canonical_json(jsonb_build_array(
          o.source,'claims',split_part(o.item,'/',2)::bigint,citation.position-1,citation.value)),'UTF8')),'hex'))) THEN
    RAISE EXCEPTION 'occurrence citation role differs from bound source citation' USING ERRCODE='23514'; END IF;
  ELSIF context.occurrence_id IS NOT NULL THEN
   RAISE EXCEPTION 'occurrence context has no declared source claim' USING ERRCODE='23514';
  END IF;
 END LOOP;
 FOR edge IN SELECT * FROM data.occurrence_evidence WHERE release_id=r AND realization_id=z LOOP
  SELECT * INTO citation_role FROM data.occurrence_evidence_role c
   WHERE c.release_id=r AND c.realization_id=z AND c.occurrence_id=edge.occurrence_id
    AND c.evidence_id=edge.evidence_id;
  SELECT * INTO source FROM data.evidence_source es
   WHERE es.release_id=r AND es.realization_id=z AND es.evidence_id=edge.evidence_id;
  SELECT * INTO STRICT o FROM data.occurrence occurrence WHERE occurrence.release_id=r AND occurrence.realization_id=z
   AND occurrence.occurrence_id=edge.occurrence_id;
  SELECT * INTO observation FROM kb.observation ob WHERE ob.release_id=r AND ob.observation_key=o.source;
  IF NOT FOUND THEN CONTINUE; END IF;
  IF source.observation_id IS NOT NULL AND source.observation_id<>observation.id THEN
   RAISE EXCEPTION 'occurrence citation belongs to another source report' USING ERRCODE='23514'; END IF;
  expected_role:=NULL;
  IF observation.payload_definition='AgentStoredBatch' THEN
   SELECT citation.value->>'role' INTO expected_role
    FROM jsonb_array_elements(observation.payload->'claims') WITH ORDINALITY candidate(value,position)
    CROSS JOIN LATERAL jsonb_array_elements(candidate.value->'evidence') WITH ORDINALITY citation(value,position)
    WHERE citation.value->>'outcome'='located'
     AND (o.item !~ '^claims/[0-9]+$' OR candidate.position-1=split_part(o.item,'/',2)::integer)
     AND edge.evidence_id='evidence:'||encode(sha256(convert_to(data.canonical_json(jsonb_build_array(
       o.source,'claims',candidate.position-1,citation.position-1,citation.value)),'UTF8')),'hex');
   IF NOT FOUND AND o.item LIKE 'entities/%/attributes/%' THEN
    SELECT citation.value->>'role' INTO expected_role
    FROM jsonb_array_elements(coalesce(observation.payload->'identity_exclusions','[]')) candidate
    CROSS JOIN LATERAL jsonb_array_elements(candidate->'evidence') WITH ORDINALITY citation(value,position)
    JOIN data.fact f ON f.release_id=r AND f.realization_id=z AND f.fact_id=o.fact_id
    JOIN data.entity_source src ON src.release_id=r AND src.realization_id=z AND src.observation_id=observation.id AND src.entity_id=f.subject_id
    WHERE starts_with(o.item,'entities/'||src.local_id||'/attributes/')
     AND substring(o.item FROM length('entities/'||src.local_id||'/attributes/')+1) ~ '^[0-9]+$'
     AND ((candidate->'left'->>'kind'='local' AND candidate->'left'->>'target'=src.local_id)
       OR (candidate->'right'->>'kind'='local' AND candidate->'right'->>'target'=src.local_id))
     AND citation.value->>'outcome'='located'
     AND EXISTS(SELECT FROM jsonb_array_elements(candidate->'evidence') primary_citation WHERE primary_citation->>'outcome'='located' AND primary_citation->>'role'='primary')
     AND edge.evidence_id='evidence:'||encode(sha256(convert_to(data.canonical_json(jsonb_build_array(
       o.source,'identity_exclusions',candidate->>'id',citation.position-1,citation.value)),'UTF8')),'hex');
   END IF;
   IF expected_role IS NULL THEN RAISE EXCEPTION 'occurrence citation is outside bound source claim' USING ERRCODE='23514'; END IF;
  ELSIF observation.payload_definition='SourceObservation' AND observation.kind='author_markup' THEN
   synthesis:=data.report_field(observation.payload->'payload','synthesize');
   SELECT data.report_field(citation.value,'role')->>'text' INTO expected_role
    FROM jsonb_array_elements(data.report_field(synthesis,'evidence')->'items') WITH ORDINALITY citation(value,position)
    WHERE edge.evidence_id='evidence:'||encode(sha256(convert_to(data.canonical_json(jsonb_build_array(
       o.source,citation.position-1,
       (data.report_field(citation.value,'start')->>'integer')::bigint,
       (data.report_field(citation.value,'end')->>'integer')::bigint)),'UTF8')),'hex');
   IF NOT FOUND THEN RAISE EXCEPTION 'occurrence citation is outside bound source synthesis' USING ERRCODE='23514'; END IF;
  END IF;
  IF citation_role.role IS DISTINCT FROM expected_role THEN
   RAISE EXCEPTION 'occurrence citation role differs from bound source citation' USING ERRCODE='23514'; END IF;
 END LOOP;
END $$;
CREATE OR REPLACE FUNCTION sem.select_completed_result(p text, r bigint, g bigint) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
BEGIN
 PERFORM sem.require_admission_caller(); RETURN data.select_project_result(p,r,g); END
$$;
REVOKE ALL PRIVILEGES ON FUNCTION sem.refuse_immutable_mutation (), sem.guard_finalized_insert () FROM PUBLIC;
REVOKE ALL PRIVILEGES ON FUNCTION sem.publish_release_archive (jsonb), sem.record_deployment_admission (text, text, text, text, bytea), sem.record_sql_admission (text, text, text, text, bytea), sem.activate_release (text, text, text, bigint), sem.select_completed_result (text, bigint, bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION sem.publish_release_archive (jsonb), sem.record_deployment_admission (text, text, text, text, bytea), sem.record_sql_admission (text, text, text, text, bytea), sem.activate_release (text, text, text, bigint), sem.select_completed_result (text, bigint, bigint) TO corpus_sem_admitter;
REVOKE ALL PRIVILEGES ON FUNCTION data.begin_inference_workspace (text, text, bigint, text), data.end_inference_workspace (text, text, bigint, text), data.is_bound_statement (text, text), data.require_runtime_principal (text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION data.begin_inference_workspace (text, text, bigint, text), data.end_inference_workspace (text, text, bigint, text) TO corpus_sem_writer;
GRANT EXECUTE ON FUNCTION data.require_runtime_principal (text) TO corpus_sem_writer, corpus_sem_reader, corpus_sem_evaluator, corpus_sem_admitter;
GRANT EXECUTE ON FUNCTION data.is_bound_statement (text, text) TO corpus_sem_writer, corpus_sem_reader;
GRANT USAGE ON SCHEMA sem, data, ops TO corpus_sem_admitter;
GRANT SELECT ON ALL TABLES IN SCHEMA sem TO corpus_sem_admitter;
GRANT SELECT ON TABLE data.project, data.realization TO corpus_sem_admitter;
GRANT SELECT ON ALL TABLES IN SCHEMA ops TO corpus_sem_admitter;
GRANT SELECT, INSERT ON ALL TABLES IN SCHEMA sem TO corpus_sem_publisher;
GRANT SELECT ON TABLE sem.release_finalization, sem.deployment_admission, sem.physical_contract TO corpus_sem_writer, corpus_sem_reader, corpus_sem_evaluator;
CREATE OR REPLACE FUNCTION sem.require_archive_bytes(r text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE archived sem.release; document jsonb; manifest jsonb; expected jsonb; actual jsonb; kind text;
BEGIN
 SELECT * INTO STRICT archived FROM sem.release WHERE release_id=r;
 document:=convert_from(archived.prepared_bytes,'UTF8')::jsonb;
 manifest:=convert_from(archived.manifest_bytes,'UTF8')::jsonb;
 IF archived.profile NOT IN ('semantic-1','semantic-2') OR document->>'format' NOT IN ('semantic-release-archive-1','semantic-release-archive-2','semantic-release-archive-3')
 OR archived.release_id<>'release:'||encode(sha256(archived.manifest_bytes),'hex')
 OR archived.content_digest<>encode(sha256(archived.prepared_bytes),'hex')
 OR document->'products'->>'release_id' IS DISTINCT FROM r
 OR manifest->'profile'->>'version' IS DISTINCT FROM archived.profile THEN
  RAISE EXCEPTION 'archive manifest identity differs' USING ERRCODE='23514'; END IF;
 FOREACH kind IN ARRAY ARRAY['source','dependency'] LOOP
  expected:=manifest->CASE kind WHEN 'source' THEN 'sources' ELSE 'dependencies' END;
  SELECT COALESCE(jsonb_agg(jsonb_build_array(input_name,content_digest) ORDER BY input_name),'[]'::jsonb) INTO actual
  FROM sem.input WHERE release_id=r AND input_kind=kind;
  IF expected IS DISTINCT FROM actual THEN RAISE EXCEPTION 'archive input manifest differs: %',kind USING ERRCODE='23514'; END IF;
 END LOOP;
 SELECT COALESCE(jsonb_agg(jsonb_build_array(artifact_name,content_digest) ORDER BY artifact_name),'[]'::jsonb) INTO actual FROM sem.artifact WHERE release_id=r;
 SELECT COALESCE(jsonb_agg(jsonb_build_array(value->>'kind',value->>'digest') ORDER BY value->>'kind'),'[]'::jsonb) INTO expected
 FROM jsonb_array_elements(document->'products'->'artifacts');
 IF actual IS DISTINCT FROM expected
 OR EXISTS(SELECT FROM sem.input WHERE release_id=r AND content_digest<>encode(sha256(content),'hex'))
 OR EXISTS(SELECT FROM sem.artifact WHERE release_id=r AND content_digest<>encode(sha256(content),'hex'))
 OR (SELECT count(*) FROM sem.input WHERE release_id=r)<>jsonb_array_length(manifest->'sources')+jsonb_array_length(manifest->'dependencies')+3
 OR (SELECT count(*) FROM sem.input WHERE release_id=r AND (input_kind,input_name) IN (('profile','profile'),('vocabulary','vocabulary'),('ontology_sources','ontology_sources')))<>3 THEN
  RAISE EXCEPTION 'archive product or input closure differs' USING ERRCODE='23514'; END IF;
END
$$;
REVOKE ALL PRIVILEGES ON FUNCTION sem.require_archive_bytes (text) FROM PUBLIC;
DO $$ DECLARE r text; BEGIN
 FOR r IN SELECT release_id FROM sem.release LOOP PERFORM sem.require_archive_bytes(r);
 PERFORM sem.require_execution_projection(r); END LOOP;
 INSERT INTO sem.release_finalization SELECT release_id,content_digest FROM sem.release
 ON CONFLICT(release_id) DO NOTHING;
 IF EXISTS(SELECT FROM sem.release_finalization f JOIN sem.release s USING(release_id)
           WHERE f.content_digest IS DISTINCT FROM s.content_digest) THEN
  RAISE EXCEPTION 'finalized release digest differs from archive' USING ERRCODE='23514';
 END IF;
END $$;
CREATE OR REPLACE FUNCTION data.require_float_lexical(value text) RETURNS text LANGUAGE plpgsql IMMUTABLE RETURNS NULL ON NULL INPUT SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE exponent integer;
BEGIN
 IF value IN ('0x0.0p+0','-0x0.0p+0') THEN RETURN value; END IF;
 IF value ~ '^-?0x0\.[0-9a-f]{13}p-1022$' AND split_part(value,'.',2) NOT LIKE '0000000000000p%' THEN RETURN value; END IF;
 IF value ~ '^-?0x1\.[0-9a-f]{13}p[+-](0|[1-9][0-9]{0,3})$' THEN
  exponent:=split_part(value,'p',2)::integer;
  IF exponent BETWEEN -1022 AND 1023 AND value NOT LIKE '%p-0' THEN RETURN value; END IF;
 END IF;
 RAISE EXCEPTION 'invalid finite float hexadecimal representation' USING ERRCODE='23514';
END
$$;
CREATE OR REPLACE FUNCTION data.guard_float_codec() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
BEGIN
 IF NEW.kind='float' THEN PERFORM data.require_float_lexical(NEW.text_value); END IF;
 RETURN NEW;
END
$$;
REVOKE ALL PRIVILEGES ON FUNCTION data.require_float_lexical (text), data.guard_float_codec () FROM PUBLIC;
GRANT EXECUTE ON FUNCTION data.require_float_lexical (text) TO corpus_sem_reader, corpus_sem_writer;
CREATE OR REPLACE FUNCTION sem.require_admission_caller() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE principal name:=session_user; owner_oid oid;
BEGIN
 SELECT nspowner INTO owner_oid FROM pg_namespace WHERE nspname='sem';
 IF pg_has_role(principal,owner_oid,'MEMBER') THEN RETURN; END IF;
 IF NOT pg_has_role(principal,'corpus_sem_admitter','USAGE')
 OR pg_has_role(principal,'corpus_sem_publisher','MEMBER')
 OR EXISTS(SELECT FROM pg_roles WHERE oid=principal::regrole AND (rolsuper OR rolcreaterole OR rolcreatedb OR rolbypassrls OR rolreplication))
 OR has_database_privilege(principal,current_database(),'TEMP')
 OR EXISTS(SELECT FROM pg_namespace WHERE nspname IN ('sem','data','ops','kb','eval') AND has_schema_privilege(principal,oid,'CREATE'))
 OR EXISTS(SELECT FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('sem','data') AND c.relkind IN ('r','p') AND (has_table_privilege(principal,c.oid,'INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER') OR has_any_column_privilege(principal,c.oid,'INSERT,UPDATE')))
 OR EXISTS(SELECT FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='eval' AND c.relkind IN ('r','p') AND has_table_privilege(principal,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')) OR EXISTS(SELECT FROM jsonb_array_elements(data.execution_contract_descriptor()->'functions') contract
 JOIN pg_proc p ON p.oid=to_regprocedure(contract->>'signature')
 WHERE has_function_privilege(principal,p.oid,'EXECUTE') IS DISTINCT FROM ((contract->'execute_roles') ? 'corpus_sem_admitter')) THEN
  RAISE EXCEPTION 'unrestricted admission caller' USING ERRCODE='42501'; END IF;
END
$$;
REVOKE ALL PRIVILEGES ON FUNCTION sem.require_admission_caller () FROM PUBLIC;
CREATE OR REPLACE FUNCTION data.validate_pre_inference_state(r text, z text) RETURNS void LANGUAGE plpgsql STABLE SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE a record; x record; n bigint; primitive text; lexical text; value_count bigint; accepted_values text[]; enforce boolean;
BEGIN

 -- Meaning of unstaged admitted graphs is established once: value rows/child closure and
 -- release definitions are immutable. Cumulative state checks below remain unchanged.
 IF to_regclass('pg_temp.sp_typed_value') IS NULL THEN
  FOR primitive IN SELECT value_id FROM data.typed_value WHERE release_id=r AND realization_id=z LOOP
   PERFORM data.value_meaning(r,z,primitive);
  END LOOP;
 ELSE
  IF NOT EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='sp_typed_value' AND c.relkind='r' AND c.relpersistence='t' AND c.relowner=current_user::regrole AND (SELECT array_agg(stage_attr.attname||':'||format_type(stage_attr.atttypid,stage_attr.atttypmod) ORDER BY stage_attr.attnum) FROM pg_attribute stage_attr WHERE stage_attr.attrelid=c.oid AND stage_attr.attnum>0 AND NOT stage_attr.attisdropped)=ARRAY['value_id:text','kind:text','text_value:text','integer_value:numeric','numeric_value:numeric','decimal_lexical:text','boolean_value:boolean','entity_id:text','language:text','datatype:text','opaque_payload:jsonb']) THEN RAISE EXCEPTION 'untrusted typed-value staging'; END IF;
  FOR primitive IN SELECT DISTINCT value_id FROM pg_temp.sp_typed_value LOOP
   PERFORM data.value_meaning(r,z,primitive);
  END LOOP;
 END IF;
 IF EXISTS(SELECT FROM data.membership m WHERE m.release_id=r AND m.realization_id=z AND (m.establishment='' OR NOT EXISTS(SELECT FROM data.membership_support ms WHERE (ms.release_id,ms.realization_id,ms.entity_id,ms.class_id)=(m.release_id,m.realization_id,m.entity_id,m.class_id)))) THEN RAISE EXCEPTION 'membership requires establishment and support' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM data.derivation d LEFT JOIN data.derivation_premise dp ON (dp.release_id,dp.realization_id,dp.derivation_id)=(d.release_id,d.realization_id,d.derivation_id) WHERE d.release_id=r AND d.realization_id=z GROUP BY d.derivation_id HAVING count(dp.position)=0 OR min(dp.position)<>0 OR max(dp.position)<>count(dp.position)-1) THEN RAISE EXCEPTION 'derivation requires ordered premises' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM data.fact f WHERE f.release_id=r AND f.realization_id=z AND EXISTS(SELECT FROM sem.class_definition WHERE release_id=r AND name='Qualification') AND NOT EXISTS(SELECT FROM data.typed_value v JOIN sem.class_definition c ON c.release_id=r AND c.class_id=v.datatype AND (c.name='Qualification' OR EXISTS(SELECT FROM sem.class_hierarchy h JOIN sem.class_definition root ON root.release_id=h.release_id AND root.class_id=h.ancestor_id AND root.name='Qualification' WHERE h.release_id=r AND h.class_id=c.class_id)) WHERE v.release_id=r AND v.realization_id=z AND v.value_id=f.qualification_value_id)) THEN RAISE EXCEPTION 'fact requires typed qualification' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM data.membership m JOIN sem.class_definition c ON c.release_id=m.release_id AND c.class_id=m.class_id WHERE m.release_id=r AND m.realization_id=z AND c.abstract) THEN RAISE EXCEPTION 'direct membership of abstract class' USING ERRCODE='23514'; END IF;
 WITH RECURSIVE accepted(v) AS (SELECT root.v FROM data.fact f JOIN data.selection s ON (s.release_id,s.realization_id,s.fact_id)=(f.release_id,f.realization_id,f.fact_id) CROSS JOIN LATERAL(VALUES (f.object_value_id),(f.qualification_value_id)) root(v) WHERE f.release_id=r AND f.realization_id=z AND root.v IS NOT NULL UNION SELECT vr.child_value_id FROM data.value_role vr JOIN accepted ac ON ac.v=vr.parent_value_id WHERE vr.release_id=r AND vr.realization_id=z) SELECT array_agg(v) INTO accepted_values FROM accepted;
 -- Every value is interpreted, including disconnected nested nodes. No caller digest is trusted.
 FOR x IN SELECT * FROM data.typed_value WHERE release_id=r AND realization_id=z LOOP
 IF x.kind IN ('interval','expression','missing') THEN RAISE EXCEPTION 'unsupported physical value alias; use a typed record' USING ERRCODE='23514'; END IF;
 IF x.datatype IS NOT NULL AND x.kind NOT IN ('record','mapping') THEN RAISE EXCEPTION 'datatype is supported only on typed records or mappings' USING ERRCODE='23514'; END IF;
 IF x.opaque_payload IS NOT NULL OR x.language IS NOT NULL THEN RAISE EXCEPTION 'unsupported opaque/language value' USING ERRCODE='23514'; END IF;
 IF x.kind IN ('string','date','datetime','float') AND x.text_value IS NULL THEN RAISE EXCEPTION 'missing scalar text' USING ERRCODE='23514'; END IF;
 IF x.kind='integer' THEN
 lexical:=COALESCE(x.text_value,x.integer_value::text);
 IF lexical IS NULL OR lexical !~ '^[+-]?[0-9]+$' OR (x.integer_value IS NOT NULL AND data.decimal_canonical(lexical)<>data.decimal_canonical(x.integer_value::text)) THEN RAISE EXCEPTION 'invalid exact integer' USING ERRCODE='23514'; END IF;
 END IF;
 IF x.kind IN ('decimal','number') THEN
 lexical:=x.decimal_lexical;
 IF lexical IS NULL OR lexical !~ '^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]+)?$' OR (x.numeric_value IS NOT NULL AND lexical::numeric<>x.numeric_value) THEN RAISE EXCEPTION 'invalid exact decimal' USING ERRCODE='23514'; END IF;
 END IF;
 IF x.kind='boolean' AND x.boolean_value IS NULL THEN RAISE EXCEPTION 'missing boolean' USING ERRCODE='23514'; END IF;
 IF x.kind='float' AND (x.text_value !~ '^-?0x(0\.0p\+0|1\.[0-9a-f]{13}p([+]0|[+][1-9][0-9]*|-[1-9][0-9]*)|0\.[0-9a-f]{13}p-1022)$' OR (x.text_value ~ '0x1\.' AND split_part(x.text_value,'p',2)::integer NOT BETWEEN -1022 AND 1023) OR x.text_value ~ '0x0\.0000000000000p-1022') THEN RAISE EXCEPTION 'invalid finite float hex' USING ERRCODE='23514'; END IF;
 IF x.kind='date' AND (x.text_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR to_char(x.text_value::date,'YYYY-MM-DD')<>x.text_value) THEN RAISE EXCEPTION 'invalid canonical date' USING ERRCODE='23514'; END IF;
 IF x.kind='datetime' AND (x.text_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{6})?\+00:00$' OR extract(year FROM x.text_value::timestamptz) NOT BETWEEN 1 AND 9999 OR to_char(x.text_value::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||CASE WHEN extract(microseconds FROM x.text_value::timestamptz)::bigint % 1000000=0 THEN '' ELSE to_char(x.text_value::timestamptz AT TIME ZONE 'UTC','.US') END||'+00:00' <> x.text_value) THEN RAISE EXCEPTION 'invalid canonical UTC datetime' USING ERRCODE='23514'; END IF;
 IF x.kind NOT IN ('sequence','mapping','record','interval','expression','missing') AND EXISTS(SELECT FROM data.value_role WHERE release_id=r AND realization_id=z AND parent_value_id=x.value_id) THEN RAISE EXCEPTION 'scalar has child roles' USING ERRCODE='23514'; END IF;
 IF x.kind='sequence' AND EXISTS(SELECT FROM data.value_role WHERE release_id=r AND realization_id=z AND parent_value_id=x.value_id GROUP BY parent_value_id HAVING min(position)<>0 OR max(position)<>count(*)-1 OR count(DISTINCT position)<>count(*) OR bool_or(role<>'item')) THEN RAISE EXCEPTION 'invalid ordered sequence' USING ERRCODE='23514'; END IF;
 IF x.kind IN ('mapping','record','interval','expression','missing') AND EXISTS(SELECT FROM data.value_role WHERE release_id=r AND realization_id=z AND parent_value_id=x.value_id GROUP BY role HAVING count(*)<>1 OR min(position)<>0) THEN RAISE EXCEPTION 'duplicate mapping role' USING ERRCODE='23514'; END IF;
 IF x.kind IN ('record','interval','expression','missing') OR (x.kind='mapping' AND x.datatype IS NOT NULL) THEN
 IF x.datatype IS NULL OR NOT EXISTS(SELECT FROM sem.class_definition WHERE release_id=r AND class_id=x.datatype AND NOT abstract) THEN RAISE EXCEPTION 'undeclared record class' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM data.value_role vr WHERE vr.release_id=r AND vr.realization_id=z AND vr.parent_value_id=x.value_id AND NOT EXISTS(SELECT FROM sem.property_applicability pa WHERE pa.release_id=r AND pa.class_id=x.datatype AND pa.constraints->>'name'=vr.role)) THEN RAISE EXCEPTION 'undeclared record property' USING ERRCODE='23514'; END IF;
 FOR a IN SELECT * FROM sem.property_applicability WHERE release_id=r AND class_id=x.datatype LOOP
 enforce:=a.constraint_scope='shape' OR COALESCE(x.value_id=ANY(accepted_values),false);
 SELECT count(*) INTO n FROM data.value_role WHERE release_id=r AND realization_id=z AND parent_value_id=x.value_id AND role=a.constraints->>'name';
 IF enforce AND n=0 AND (a.required OR COALESCE(a.minimum_cardinality,0)>0) THEN RAISE EXCEPTION 'missing required record property %',a.property_id USING ERRCODE='23514'; END IF;
 FOR primitive IN SELECT child_value_id FROM data.value_role WHERE release_id=r AND realization_id=z AND parent_value_id=x.value_id AND role=a.constraints->>'name' LOOP
 IF a.multivalued THEN
 IF NOT EXISTS(SELECT FROM data.typed_value WHERE release_id=r AND realization_id=z AND value_id=primitive AND kind=CASE WHEN a.constraints->>'collection_key' IS NULL THEN 'sequence' ELSE 'mapping' END) THEN RAISE EXCEPTION 'multivalue collection representation differs for %/% (key %)',x.datatype,a.property_id,a.constraints->>'collection_key' USING ERRCODE='23514'; END IF;
 IF a.constraints->>'collection_key' IS NOT NULL AND EXISTS(SELECT FROM data.value_role member WHERE member.release_id=r AND member.realization_id=z AND member.parent_value_id=primitive AND NOT EXISTS(SELECT FROM data.value_role kr JOIN data.typed_value kv ON (kv.release_id,kv.realization_id,kv.value_id)=(kr.release_id,kr.realization_id,kr.child_value_id) WHERE kr.release_id=r AND kr.realization_id=z AND kr.parent_value_id=member.child_value_id AND kr.role=a.constraints->>'collection_key' AND kv.kind='string' AND kv.text_value=member.role)) THEN RAISE EXCEPTION 'inlined map key differs from member identifier for %/%',x.datatype,a.property_id USING ERRCODE='23514'; END IF;
 SELECT count(*) INTO value_count FROM data.value_role WHERE release_id=r AND realization_id=z AND parent_value_id=primitive;
 IF enforce AND (value_count<COALESCE(a.minimum_cardinality,CASE WHEN a.required THEN 1 ELSE 0 END) OR (a.maximum_cardinality IS NOT NULL AND value_count>a.maximum_cardinality)) THEN RAISE EXCEPTION 'record cardinality' USING ERRCODE='23514'; END IF;
 FOR lexical IN SELECT child_value_id FROM data.value_role WHERE release_id=r AND realization_id=z AND parent_value_id=primitive LOOP
 PERFORM data.validate_property(r,z,lexical,COALESCE(a.constraints->>'native_range',a.range_name),CASE WHEN enforce THEN a.constraints ELSE a.constraints-'minimum'-'maximum'-'native_minimum'-'native_maximum' END);
 END LOOP;
 ELSE PERFORM data.validate_property(r,z,primitive,COALESCE(a.constraints->>'native_range',a.range_name),CASE WHEN enforce THEN a.constraints ELSE a.constraints-'minimum'-'maximum'-'native_minimum'-'native_maximum' END);
 END IF;
 END LOOP;
 END LOOP;
 END IF;
 END LOOP;
 -- Range/applicability reads include the complete admitted state plus this candidate.
 IF EXISTS(SELECT FROM data.fact f WHERE f.release_id=r AND f.realization_id=z AND NOT EXISTS(SELECT FROM data.membership m JOIN sem.property_applicability pa ON pa.release_id=m.release_id AND pa.class_id=m.class_id WHERE m.release_id=r AND m.realization_id=z AND m.entity_id=f.subject_id AND pa.property_id=f.property_id)) THEN RAISE EXCEPTION 'fact property is not applicable to subject class' USING ERRCODE='23514'; END IF;
 FOR a IN SELECT f.object_value_id,COALESCE(pa.constraints->>'native_range',pa.range_name) AS range_name,CASE WHEN pa.constraint_scope='shape' OR EXISTS(SELECT FROM data.selection s WHERE (s.release_id,s.realization_id,s.fact_id)=(f.release_id,f.realization_id,f.fact_id)) THEN pa.constraints ELSE pa.constraints-'minimum'-'maximum'-'native_minimum'-'native_maximum'-'native_minimum'-'native_maximum' END AS constraints FROM data.fact f JOIN data.membership m ON (m.release_id,m.realization_id,m.entity_id)=(f.release_id,f.realization_id,f.subject_id) JOIN sem.property_applicability pa ON pa.release_id=r AND pa.class_id=m.class_id AND pa.property_id=f.property_id WHERE f.release_id=r AND f.realization_id=z LOOP
 PERFORM data.validate_property(r,z,a.object_value_id,a.range_name,a.constraints);
 END LOOP;
 -- Cardinality counts semantic values, never evidence occurrences.
 FOR a IN SELECT m.entity_id,pa.* FROM data.membership m JOIN sem.property_applicability pa ON pa.release_id=m.release_id AND pa.class_id=m.class_id WHERE m.release_id=r AND m.realization_id=z LOOP
 SELECT count(DISTINCT data.canonical_json(data.value_meaning(r,z,f.object_value_id))) INTO n FROM data.fact f
 WHERE f.release_id=r AND f.realization_id=z AND f.subject_id=a.entity_id AND f.property_id=a.property_id
 AND (a.constraint_scope='shape' OR EXISTS(SELECT FROM data.selection s WHERE (s.release_id,s.realization_id,s.fact_id)=(f.release_id,f.realization_id,f.fact_id)));
 IF n<COALESCE(a.minimum_cardinality,CASE WHEN a.required THEN 1 ELSE 0 END) OR n>COALESCE(a.maximum_cardinality,CASE WHEN a.multivalued THEN 9223372036854775807 ELSE 1 END) THEN RAISE EXCEPTION 'property cardinality %/%',a.entity_id,a.property_id USING ERRCODE='23514'; END IF;
 END LOOP;
 -- Identity groups use each declared member, with admitted case policy and complete scope.
 IF EXISTS(
 WITH key_parts AS (
 SELECT m.entity_id,m.class_id,i.group_id,i.position,
 count(DISTINCT data.canonical_json(CASE WHEN pa.constraints->>'case_policy'='casefold' AND tv.kind='string' THEN jsonb_build_array('string',casefold(tv.text_value COLLATE pg_catalog.pg_unicode_fast)) ELSE data.value_meaning(r,z,f.object_value_id) END)) AS count_values,
 min(data.canonical_json(CASE WHEN pa.constraints->>'case_policy'='casefold' AND tv.kind='string' THEN jsonb_build_array('string',casefold(tv.text_value COLLATE pg_catalog.pg_unicode_fast)) ELSE data.value_meaning(r,z,f.object_value_id) END)) AS part
 FROM data.membership m JOIN sem.identity_slot i ON i.release_id=r AND i.class_id=m.class_id
 JOIN sem.property_applicability pa ON pa.release_id=r AND pa.class_id=i.class_id AND pa.property_id=i.property_id
 LEFT JOIN data.fact f ON f.release_id=r AND f.realization_id=z AND f.subject_id=m.entity_id AND f.property_id=i.property_id AND (pa.constraint_scope='shape' OR EXISTS(SELECT FROM data.selection sel WHERE (sel.release_id,sel.realization_id,sel.fact_id)=(f.release_id,f.realization_id,f.fact_id)))
 LEFT JOIN data.typed_value tv ON (tv.release_id,tv.realization_id,tv.value_id)=(f.release_id,f.realization_id,f.object_value_id)
 WHERE m.release_id=r AND m.realization_id=z GROUP BY m.entity_id,m.class_id,i.group_id,i.position),
 keys AS(SELECT entity_id,class_id,group_id,string_agg(part,',' ORDER BY position) AS value,bool_and(count_values=1) AS complete FROM key_parts GROUP BY entity_id,class_id,group_id)
 SELECT FROM keys GROUP BY class_id,group_id,value HAVING count(*)>1 OR NOT bool_and(complete)
 ) THEN RAISE EXCEPTION 'missing, multivalued or nonunique entity identity' USING ERRCODE='23514'; END IF;
END $$;
