INSERT INTO data.assessment(release_id,realization_id,"assessment_id","operation_id","operation_version","outcome","fact_id","occurrence_id","confidence","reason","uncertainty","counterpart_fact_id","counterpart_occurrence_id","context_value_id","comparison_tier") SELECT r,z,"assessment_id","operation_id","operation_version","outcome","fact_id","occurrence_id","confidence","reason","uncertainty","counterpart_fact_id","counterpart_occurrence_id","context_value_id","comparison_tier" FROM pg_temp.sp_assessment ON CONFLICT DO NOTHING; IF EXISTS(SELECT "assessment_id","operation_id","operation_version","outcome","fact_id","occurrence_id","confidence","reason","uncertainty","counterpart_fact_id","counterpart_occurrence_id","context_value_id","comparison_tier" FROM pg_temp.sp_assessment EXCEPT SELECT "assessment_id","operation_id","operation_version","outcome","fact_id","occurrence_id","confidence","reason","uncertainty","counterpart_fact_id","counterpart_occurrence_id","context_value_id","comparison_tier" FROM data.assessment WHERE release_id=r AND realization_id=z) THEN RAISE EXCEPTION 'conflicting existing assessment' USING ERRCODE='23505'; END IF;
INSERT INTO data.derivation_premise(release_id,realization_id,"derivation_id","position","premise_fact_id") SELECT r,z,"derivation_id","position","premise_fact_id" FROM pg_temp.sp_derivation_premise ON CONFLICT DO NOTHING; IF EXISTS(SELECT "derivation_id","position","premise_fact_id" FROM pg_temp.sp_derivation_premise EXCEPT SELECT "derivation_id","position","premise_fact_id" FROM data.derivation_premise WHERE release_id=r AND realization_id=z) THEN RAISE EXCEPTION 'conflicting existing derivation_premise' USING ERRCODE='23505'; END IF;
INSERT INTO data.occurrence_context(release_id,realization_id,"occurrence_id","statement_entity_id","statement_role") SELECT r,z,"occurrence_id","statement_entity_id","statement_role" FROM pg_temp.sp_occurrence_context ON CONFLICT DO NOTHING; IF EXISTS(SELECT "occurrence_id","statement_entity_id","statement_role" FROM pg_temp.sp_occurrence_context EXCEPT SELECT "occurrence_id","statement_entity_id","statement_role" FROM data.occurrence_context WHERE release_id=r AND realization_id=z) THEN RAISE EXCEPTION 'conflicting existing occurrence_context' USING ERRCODE='23505'; END IF;
INSERT INTO data.occurrence_establishment(release_id,realization_id,"occurrence_id","establishment") SELECT r,z,"occurrence_id","establishment" FROM pg_temp.sp_occurrence_establishment ON CONFLICT DO NOTHING; IF EXISTS(SELECT "occurrence_id","establishment" FROM pg_temp.sp_occurrence_establishment EXCEPT SELECT "occurrence_id","establishment" FROM data.occurrence_establishment WHERE release_id=r AND realization_id=z) THEN RAISE EXCEPTION 'conflicting existing occurrence_establishment' USING ERRCODE='23505'; END IF;
INSERT INTO data.occurrence_evidence(release_id,realization_id,"occurrence_id","evidence_id") SELECT r,z,"occurrence_id","evidence_id" FROM pg_temp.sp_occurrence_evidence ON CONFLICT DO NOTHING; IF EXISTS(SELECT "occurrence_id","evidence_id" FROM pg_temp.sp_occurrence_evidence EXCEPT SELECT "occurrence_id","evidence_id" FROM data.occurrence_evidence WHERE release_id=r AND realization_id=z) THEN RAISE EXCEPTION 'conflicting existing occurrence_evidence' USING ERRCODE='23505'; END IF;
INSERT INTO data.support(release_id,realization_id,"fact_id","occurrence_id") SELECT r,z,"fact_id","occurrence_id" FROM pg_temp.sp_support ON CONFLICT DO NOTHING; IF EXISTS(SELECT "fact_id","occurrence_id" FROM pg_temp.sp_support EXCEPT SELECT "fact_id","occurrence_id" FROM data.support WHERE release_id=r AND realization_id=z) THEN RAISE EXCEPTION 'conflicting existing support' USING ERRCODE='23505'; END IF;
INSERT INTO data.occurrence_evidence_role(release_id,realization_id,"occurrence_id","evidence_id","role") SELECT r,z,"occurrence_id","evidence_id","role" FROM pg_temp.sp_occurrence_evidence_role ON CONFLICT DO NOTHING; IF EXISTS(SELECT "occurrence_id","evidence_id","role" FROM pg_temp.sp_occurrence_evidence_role EXCEPT SELECT "occurrence_id","evidence_id","role" FROM data.occurrence_evidence_role WHERE release_id=r AND realization_id=z) THEN RAISE EXCEPTION 'conflicting existing occurrence_evidence_role' USING ERRCODE='23505'; END IF;
 PERFORM data.validate_state(r,z);
 PERFORM data.validate_occurrence_context(r,z);
 PERFORM data.validate_entity_source(r,z);
 PERFORM data.validate_alternatives(r,z);
 FOR f IN SELECT * FROM pg_temp.sp_occurrence LOOP
 expected:='occ:'||encode(sha256(convert_to(data.canonical_json(jsonb_build_array(r,z,f.source,f.item)),'UTF8')),'hex');
 IF expected<>f.occurrence_id THEN RAISE EXCEPTION 'invalid occurrence identity' USING ERRCODE='23514'; END IF;
 END LOOP;
 FOR f IN SELECT * FROM pg_temp.sp_fact LOOP
 IF data.fact_identity(r,z,f.subject_id,f.property_id,f.object_value_id,f.qualification_value_id)<>f.fact_id THEN RAISE EXCEPTION 'invalid fact identity' USING ERRCODE='23514'; END IF;
 END LOOP;

 FOR f IN SELECT o.*,df.subject_id,df.property_id FROM data.occurrence o JOIN data.fact df ON (df.release_id,df.realization_id,df.fact_id)=(o.release_id,o.realization_id,o.fact_id) WHERE o.release_id=r AND o.realization_id=z LOOP
 IF NOT EXISTS(SELECT FROM data.membership m JOIN sem.property_applicability pa ON pa.release_id=m.release_id AND pa.class_id=m.class_id WHERE m.release_id=r AND m.realization_id=z AND m.entity_id=f.subject_id AND pa.property_id=f.property_id) THEN RAISE EXCEPTION 'report property is not applicable to subject class' USING ERRCODE='23514'; END IF;
 FOR application IN SELECT pa.* FROM data.membership m JOIN sem.property_applicability pa ON pa.release_id=m.release_id AND pa.class_id=m.class_id WHERE m.release_id=r AND m.realization_id=z AND m.entity_id=f.subject_id AND pa.property_id=f.property_id LOOP
 PERFORM data.validate_property(r,z,f.report_object_value_id,COALESCE(application.constraints->>'native_range',application.range_name),CASE WHEN application.constraint_scope='shape' THEN application.constraints ELSE application.constraints-'minimum'-'maximum'-'native_minimum'-'native_maximum' END);
 END LOOP;
 IF data.fact_identity(r,z,f.subject_id,f.property_id,f.report_object_value_id,f.report_qualification_value_id)<>f.fact_id THEN RAISE EXCEPTION 'report meaning differs from fact' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM sem.class_definition WHERE release_id=r AND name='Qualification') AND NOT EXISTS(SELECT FROM data.typed_value v JOIN sem.class_definition c ON c.release_id=r AND c.class_id=v.datatype AND (c.name='Qualification' OR EXISTS(SELECT FROM sem.class_hierarchy h JOIN sem.class_definition root ON root.release_id=h.release_id AND root.class_id=h.ancestor_id AND root.name='Qualification' WHERE h.release_id=r AND h.class_id=c.class_id)) WHERE v.release_id=r AND v.realization_id=z AND v.value_id=f.report_qualification_value_id) THEN RAISE EXCEPTION 'report requires typed qualification' USING ERRCODE='23514'; END IF;
 END LOOP;
 RETURN rev;
END 
$$;
REVOKE ALL PRIVILEGES ON FUNCTION data.publish_contract_batch (text, text, text, bytea) FROM PUBLIC, corpus_sem_writer, corpus_sem_reader;
GRANT EXECUTE ON FUNCTION data.begin_stage () TO corpus_sem_writer;
CREATE OR REPLACE FUNCTION sem.require_execution_operation(r text, operation text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE supported jsonb; actual jsonb; expected jsonb; archived_abi text;
BEGIN
 IF NOT EXISTS(SELECT FROM sem.release WHERE release_id=r AND profile='semantic-2') THEN RETURN; END IF;
 SELECT convert_from(body,'UTF8')::jsonb->'inputs'->>'compiler_version' INTO archived_abi
 FROM sem.registry_row WHERE release_id=r AND kind='execution_model';
 IF archived_abi IS DISTINCT FROM data.execution_contract_descriptor()->>'execution_abi'
 AND operation NOT IN ('reload','open_read','query','explain','compile_projection',
  'capture_analytics','open_analysis','close_analysis','graph_project','graph_validate',
  'read_original','read_rendition','read_parsing_product') THEN
  RAISE EXCEPTION 'historical execution ABI is read-only: %',archived_abi USING ERRCODE='23514'; END IF;
 supported:=data.execution_contract_descriptor()->'supported_effects'->operation;
 IF supported IS NULL OR NOT EXISTS(SELECT FROM sem.execution_operation o WHERE o.release_id=r AND o.operation_id=operation
  AND o.implementation_id=supported->>'implementation' AND o.implementation_version=supported->>'version') THEN
  RAISE EXCEPTION 'unsupported execution operation % in release %',operation,r USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM sem.operation_effect e WHERE e.release_id=r AND e.operation_id=operation
  AND e.effect_version IS DISTINCT FROM data.execution_contract_descriptor()->'supported_effect_versions'->>e.effect_id)
 OR EXISTS(SELECT FROM sem.transition_effect e JOIN sem.execution_transition t USING(release_id,transition_id)
  WHERE e.release_id=r AND t.operation_id=operation
  AND e.effect_version IS DISTINCT FROM data.execution_contract_descriptor()->'supported_effect_versions'->>e.effect_id) THEN
  RAISE EXCEPTION 'unsupported execution effect version for %',operation USING ERRCODE='23514'; END IF;
 SELECT COALESCE(jsonb_agg(effect_id ORDER BY effect_id),'[]'::jsonb) INTO actual
 FROM sem.operation_effect WHERE release_id=r AND operation_id=operation;
 IF actual IS DISTINCT FROM supported->'effects' THEN
  RAISE EXCEPTION 'unsupported execution effects for %',operation USING ERRCODE='23514'; END IF;
 SELECT COALESCE(jsonb_object_agg(t.transition_id,COALESCE((SELECT jsonb_agg(e.effect_id ORDER BY e.effect_id)
  FROM sem.transition_effect e WHERE e.release_id=r AND e.transition_id=t.transition_id),'[]'::jsonb)),'{}'::jsonb) INTO actual
 FROM sem.execution_transition t WHERE t.release_id=r AND t.operation_id=operation;
 IF actual IS DISTINCT FROM supported->'transitions' THEN
  RAISE EXCEPTION 'unsupported transition effects for %',operation USING ERRCODE='23514'; END IF;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION sem.require_execution_operation (text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION sem.require_execution_operation (text, text) TO corpus_sem_writer, corpus_sem_reader, corpus_sem_admitter, corpus_sem_evaluator;
CREATE OR REPLACE FUNCTION ops.execution_edge(r text, lifecycle text, prior text, result text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
 SELECT EXISTS(SELECT FROM sem.execution_edge e JOIN sem.execution_transition t USING(release_id,transition_id)
 WHERE e.release_id=$1 AND t.lifecycle=$2 AND e.prior_state=$3 AND e.result_state=$4)
$$;
REVOKE ALL PRIVILEGES ON FUNCTION ops.execution_edge (text, text, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.execution_edge (text, text, text, text) TO corpus_sem_writer, corpus_sem_reader;
CREATE OR REPLACE FUNCTION ops.require_transition(r text, operation text, prior text, result text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
BEGIN
 PERFORM sem.require_execution_operation(r,operation);
 IF EXISTS(SELECT FROM sem.release WHERE release_id=r AND profile='semantic-2') AND NOT EXISTS(
  SELECT FROM sem.execution_edge e JOIN sem.execution_transition t USING(release_id,transition_id)
  WHERE e.release_id=r AND t.operation_id=operation AND e.prior_state=prior AND e.result_state=result) THEN
  RAISE EXCEPTION 'undeclared operation transition %: % -> %',operation,prior,result USING ERRCODE='23514'; END IF;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION ops.require_transition (text, text, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.require_transition (text, text, text, text) TO corpus_sem_writer;
CREATE OR REPLACE FUNCTION ops.start_source_run(p_run bigint) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE job ops.run;
BEGIN
 SELECT * INTO STRICT job FROM ops.run WHERE id=p_run FOR UPDATE;
 PERFORM sem.require_execution_operation(job.release_id,'execute_source');
 IF job.status='running' AND NOT job.sealed THEN RETURN job.id; END IF;
 IF job.status<>'created' OR job.sealed THEN RAISE EXCEPTION 'run no longer accepts source execution' USING ERRCODE='P0004'; END IF;
 PERFORM ops.require_transition(job.release_id,'execute_source','created','running');
 UPDATE ops.run SET status='running' WHERE id=job.id;
 RETURN job.id;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION ops.start_source_run (bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.start_source_run (bigint) TO corpus_sem_writer;
CREATE OR REPLACE FUNCTION ops.claim_tasks(p_run bigint, p_config bigint, p_holder text, p_limit bigint, p_agent boolean) RETURNS SETOF ops.task LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE job ops.run;
BEGIN
 IF p_limit<1 OR nullif(p_holder,'') IS NULL THEN RAISE EXCEPTION 'positive claim limit and nonempty holder required'; END IF;
 SELECT * INTO STRICT job FROM ops.run WHERE id=p_run FOR SHARE;
 PERFORM sem.require_execution_operation(job.release_id,'claim');
 IF job.sealed OR job.status NOT IN ('created','running') THEN RETURN; END IF;
 RETURN QUERY WITH candidates AS MATERIALIZED (
  SELECT id FROM ops.task WHERE run_id=p_run AND method_config_id=p_config
   AND (status=CASE WHEN p_agent THEN 'awaiting_agent' ELSE 'pending' END OR (status='running' AND lease_until<clock_timestamp()))
  AND NOT EXISTS(SELECT FROM ops.task_dependency d JOIN ops.task prerequisite ON prerequisite.id=d.dependency_task_id WHERE d.task_id=ops.task.id AND prerequisite.status NOT IN ('done','empty','reused'))
  ORDER BY priority DESC,id LIMIT p_limit FOR UPDATE SKIP LOCKED
 ) UPDATE ops.task t SET status='running',attempt=t.attempt+1,claimed_by=p_holder,
  lease_until=clock_timestamp()+interval '5 minutes',started_at=COALESCE(t.started_at,clock_timestamp())
 FROM candidates c WHERE t.id=c.id RETURNING t.*;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION ops.claim_tasks (bigint, bigint, text, bigint, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.claim_tasks (bigint, bigint, text, bigint, boolean) TO corpus_sem_writer;
CREATE OR REPLACE FUNCTION ops.lock_execution_run(p_run bigint, operation text) RETURNS ops.run LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE job ops.run;
BEGIN
 SELECT * INTO STRICT job FROM ops.run WHERE id=p_run FOR SHARE;
 PERFORM sem.require_execution_operation(job.release_id,operation);
 RETURN job;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION ops.lock_execution_run (bigint, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.lock_execution_run (bigint, text) TO corpus_sem_writer;
CREATE OR REPLACE FUNCTION sem.require_scientific_layout(r text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE recipe jsonb; supported jsonb;
BEGIN
 SELECT convert_from(content,'UTF8')::jsonb INTO recipe FROM sem.artifact
 WHERE release_id=r AND artifact_name='operation/scientific-policy.json';
 supported:=data.execution_contract_descriptor()->'scientific_report_layout';
 IF recipe IS NULL OR supported IS NULL
  OR jsonb_build_object('comparison_paths',recipe->'comparison_paths','array_rules',recipe->'array_rules')
     IS DISTINCT FROM supported THEN
  RAISE EXCEPTION 'unsupported scientific report layout in release %',r USING ERRCODE='23514'; END IF;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION sem.require_scientific_layout (text) FROM PUBLIC;
CREATE OR REPLACE FUNCTION eval.guard_scientific_decisions() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE r text; recipe jsonb; rule jsonb; parent jsonb;
BEGIN
 SELECT release_id INTO STRICT r FROM eval.reference_set WHERE id=NEW.set_id;
 PERFORM sem.require_execution_operation(r,'reference_grade');
 IF NOT EXISTS(SELECT FROM sem.release WHERE release_id=r AND profile='semantic-2') THEN RETURN NEW; END IF;
 PERFORM sem.require_scientific_layout(r);
 SELECT convert_from(content,'UTF8')::jsonb INTO STRICT recipe FROM sem.artifact
 WHERE release_id=r AND artifact_name='operation/scientific-policy.json';
 IF jsonb_typeof(recipe->'comparison_paths') IS DISTINCT FROM 'array'
  OR jsonb_typeof(recipe->'array_rules') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'scientific report recipe lacks supported paths and array rules' USING ERRCODE='23514'; END IF;
 BEGIN
  FOR rule IN SELECT value FROM jsonb_array_elements(recipe->'array_rules') LOOP
   FOR parent IN SELECT jsonb_path_query(NEW.result,('strict '||(rule->>'parent_path'))::jsonpath) LOOP
    IF jsonb_typeof(parent) IS DISTINCT FROM 'object'
     OR (((rule->>'required')::boolean OR parent ? (rule->>'field'))
         AND jsonb_typeof(parent->(rule->>'field')) IS DISTINCT FROM 'array') THEN
     RAISE EXCEPTION 'scientific report array differs at %.%',rule->>'parent_path',rule->>'field'
      USING ERRCODE='23514'; END IF;
   END LOOP;
  END LOOP;
 EXCEPTION WHEN data_exception THEN
  RAISE EXCEPTION 'scientific report structure differs from bound model' USING ERRCODE='23514';
 END;
 -- Container shape is established above; lax missing-member handling preserves optional leaves.
 IF EXISTS(
  SELECT FROM (
   SELECT comparison FROM jsonb_array_elements_text(recipe->'comparison_paths') path
   CROSS JOIN LATERAL jsonb_path_query(NEW.result,path.value::jsonpath) comparison
  ) reported LEFT JOIN sem.scientific_decision_rule decision
   ON decision.release_id=r AND decision.policy_id=reported.comparison->>'policy_id'
   AND decision.evidence_tier=reported.comparison->>'evidence_tier'
   AND decision.agreement=reported.comparison->>'agreement'
  WHERE decision.policy_id IS NULL OR decision.decision IS DISTINCT FROM reported.comparison->>'outcome'
   OR decision.decision_tier IS DISTINCT FROM reported.comparison->>'decision_tier'
 ) THEN RAISE EXCEPTION 'scientific decision differs from bound evidence policy' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION eval.guard_scientific_decisions () FROM PUBLIC;
SET LOCAL role TO 'corpus_sem_publisher';
CREATE OR REPLACE FUNCTION ops.lock_finalization_run(p_run bigint) RETURNS ops.run LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE job ops.run;
BEGIN
 SELECT * INTO STRICT job FROM ops.run WHERE id=p_run FOR UPDATE;
 PERFORM sem.require_execution_operation(job.release_id,'evaluate');
 RETURN job;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION ops.lock_finalization_run (bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.lock_finalization_run (bigint) TO corpus_sem_writer;
CREATE OR REPLACE FUNCTION ops.register_parsing_source(p_task bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE source ops.parsing_product; value jsonb;
BEGIN
 SELECT * INTO STRICT source FROM ops.parsing_product WHERE task_id=p_task;
 IF EXISTS(SELECT FROM ops.parsing_layer_product WHERE task_id=p_task AND product_key='source') THEN
  IF NOT EXISTS(SELECT FROM ops.parsing_layer_product WHERE task_id=p_task AND product_key='source' AND content_digest=source.product_digest AND payload=source.payload) THEN RAISE EXCEPTION 'source registry identity differs' USING ERRCODE='23514'; END IF;
  RETURN;
 END IF;
 value:=convert_from(source.payload,'UTF8')::jsonb;
 INSERT INTO ops.parsing_layer_product(task_id,product_key,content_digest,release_id,kind,root_task_id,root_product_key,root_content_digest,contract_digest,operation,adapter_id,lifecycle,semantic_state,coverage,payload)
 VALUES(p_task,'source',source.product_digest,source.release_id,'source',p_task,'source',source.product_digest,source.contract_digest,'project_canonical',COALESCE(value->>'adapter_id','legacy-source'),source.lifecycle,source.semantic_state,source.provenance_state,source.payload);
 INSERT INTO kb.parsing_layer_representation(task_id,representation_id,kind,unit,extent_length,text_content,partition_state,recognition_state,encoding,decoder,newline_policy,text_content_utf8_base64,product_key) SELECT item.task_id,item.representation_id,item.kind,item.unit,item.extent_length,item.text_content,item.partition_state,item.recognition_state,item.encoding,item.decoder,item.newline_policy,item.text_content_utf8_base64,'source' FROM kb.parsing_representation item WHERE item.task_id=p_task;
INSERT INTO kb.parsing_layer_component(task_id,component_id,ordinal,category,representation_id,unit,start_offset,end_offset,product_key) SELECT item.task_id,item.component_id,item.ordinal,item.category,item.representation_id,item.unit,item.start_offset,item.end_offset,'source' FROM kb.parsing_component item WHERE item.task_id=p_task;
INSERT INTO kb.parsing_layer_node(task_id,node_id,kind,representation_id,unit,start_offset,end_offset,origin,origin_reason,name,value,ordinal,attribute_outcome,name_start_offset,name_end_offset,value_start_offset,value_end_offset,product_key,macro_event) SELECT item.task_id,item.node_id,item.kind,item.representation_id,item.unit,item.start_offset,item.end_offset,item.origin,item.origin_reason,item.name,item.value,item.ordinal,item.attribute_outcome,item.name_start_offset,item.name_end_offset,item.value_start_offset,item.value_end_offset,'source',NULL::jsonb FROM kb.parsing_node item WHERE item.task_id=p_task;
INSERT INTO kb.parsing_layer_relationship(task_id,relationship_id,kind,ordinal,product_key) SELECT item.task_id,item.relationship_id,item.kind,item.ordinal,'source' FROM kb.parsing_relationship item WHERE item.task_id=p_task;
INSERT INTO kb.parsing_layer_endpoint(task_id,relationship_id,ordinal,role,target_task_id,component_id,node_id,dependency_name,product_key,target_product_key,target_content_digest) SELECT item.task_id,item.relationship_id,item.ordinal,item.role,item.target_task_id,item.component_id,item.node_id,item.dependency_name,'source','source',(SELECT product_digest FROM ops.parsing_product target WHERE target.task_id=item.target_task_id) FROM kb.parsing_endpoint item WHERE item.task_id=p_task;
INSERT INTO kb.parsing_layer_mapping(task_id,mapping_id,operation,reason,fidelity,product_key) SELECT item.task_id,item.mapping_id,item.operation,item.reason,item.fidelity,'source' FROM kb.parsing_mapping item WHERE item.task_id=p_task;
INSERT INTO kb.parsing_layer_mapping_endpoint(task_id,mapping_id,side,ordinal,target_task_id,dependency_name,representation_id,unit,start_offset,end_offset,product_key,target_product_key,target_content_digest) SELECT item.task_id,item.mapping_id,item.side,item.ordinal,item.target_task_id,item.dependency_name,item.representation_id,item.unit,item.start_offset,item.end_offset,'source','source',(SELECT product_digest FROM ops.parsing_product target WHERE target.task_id=item.target_task_id) FROM kb.parsing_mapping_endpoint item WHERE item.task_id=p_task;
INSERT INTO kb.parsing_layer_dependency(task_id,product_key,name,kind,target_task_id,target_product_key,target_content_digest,artifact_digest) SELECT item.task_id,'source',item.name,'product',item.target_task_id,'source',(SELECT product_digest FROM ops.parsing_product target WHERE target.task_id=item.target_task_id),NULL FROM kb.parsing_dependency item WHERE item.task_id=p_task;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION ops.register_parsing_source (bigint) FROM PUBLIC;
CREATE OR REPLACE FUNCTION ops.publish_layered_parsing_product(p_task bigint, p_attempt bigint, p_holder text, p_contract text, p_payload bytea, p_artifacts bytea[] = CAST(ARRAY[] AS bytea[])) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE job ops.task; run ops.run; root ops.parsing_layer_product; previous ops.parsing_layer_product;
 product jsonb; parsing_item jsonb; adapter jsonb; digest text; layer_key text; operation text;
BEGIN
 -- Completion and direct publication share the same run-before-task lock order.
 SELECT r.* INTO STRICT run FROM ops.run r JOIN ops.task t ON t.run_id=r.id WHERE t.id=p_task FOR SHARE OF r;
 SELECT * INTO STRICT job FROM ops.task WHERE id=p_task AND run_id=run.id FOR UPDATE;
 IF job.attempt<>p_attempt OR job.claimed_by IS DISTINCT FROM p_holder THEN RAISE EXCEPTION 'stale layered product attempt' USING ERRCODE='P0004'; END IF;
