fset' AND (parsing_item->>'start_offset')::numeric < 0) OR NOT (parsing_item ? 'end_offset') OR (parsing_item ? 'end_offset' AND (jsonb_typeof(parsing_item->'end_offset') IS DISTINCT FROM 'number' OR parsing_item->>'end_offset' !~ '^[0-9]+$')) OR (parsing_item ? 'end_offset' AND (parsing_item->>'end_offset')::numeric < 0) THEN RAISE EXCEPTION 'parsing record shape differs: LayeredParsingMappingEndpoint' USING ERRCODE='23514'; END IF;
END LOOP;
FOR parsing_item IN SELECT value FROM jsonb_array_elements(COALESCE(product->'dependencies','[]'::jsonb)) LOOP
IF jsonb_typeof(parsing_item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: LayeredParsingDependency' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(parsing_item) key WHERE key<>ALL(ARRAY['name','kind','target_task_id','target_product_key','target_content_digest','artifact_digest'])) OR NOT (parsing_item ? 'name') OR (parsing_item ? 'name' AND (jsonb_typeof(parsing_item->'name') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'kind') OR (parsing_item ? 'kind' AND (jsonb_typeof(parsing_item->'kind') IS DISTINCT FROM 'string' OR parsing_item->>'kind' NOT IN ('artifact','product'))) OR (parsing_item ? 'target_task_id' AND (jsonb_typeof(parsing_item->'target_task_id') IS DISTINCT FROM 'number' OR parsing_item->>'target_task_id' !~ '^[0-9]+$')) OR (parsing_item ? 'target_task_id' AND (parsing_item->>'target_task_id')::numeric < 1) OR (parsing_item ? 'target_product_key' AND (jsonb_typeof(parsing_item->'target_product_key') IS DISTINCT FROM 'string')) OR (parsing_item ? 'target_content_digest' AND (jsonb_typeof(parsing_item->'target_content_digest') IS DISTINCT FROM 'string')) OR (parsing_item ? 'artifact_digest' AND (jsonb_typeof(parsing_item->'artifact_digest') IS DISTINCT FROM 'string')) THEN RAISE EXCEPTION 'parsing record shape differs: LayeredParsingDependency' USING ERRCODE='23514'; END IF;
END LOOP;
FOR parsing_item IN SELECT value FROM jsonb_array_elements(COALESCE(product->'interpretations','[]'::jsonb)) LOOP
IF jsonb_typeof(parsing_item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: ParsingInterpretation' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(parsing_item) key WHERE key<>ALL(ARRAY['declaration_basis','interpretation_id','product_id','occurrence_ids','context_digest','declaration_digest','assumption_digest','adapter_id','semantic_state','coverage','alternative_group'])) OR (parsing_item ? 'declaration_basis' AND (jsonb_typeof(parsing_item->'declaration_basis') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(parsing_item->'declaration_basis') nested_record WHERE jsonb_typeof(nested_record) IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(nested_record) key WHERE key<>ALL(ARRAY['declaration','rule_id','declaration_start','declaration_end','head_start','head_end','scope_start','scope_end','source_view_start','source_view_end','scope_key','source_view_node_id','relationship_id'])) OR NOT (nested_record ? 'declaration') OR (nested_record ? 'declaration' AND (jsonb_typeof(nested_record->'declaration') IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(nested_record->'declaration') key WHERE key<>ALL(ARRAY['role','authority','source_id','scope','start','end','symbol','evidence'])) OR NOT (nested_record->'declaration' ? 'role') OR (nested_record->'declaration' ? 'role' AND (jsonb_typeof(nested_record->'declaration'->'role') IS DISTINCT FROM 'string')) OR nested_record->'declaration'->>'role' IS DISTINCT FROM 'function' OR NOT (nested_record->'declaration' ? 'authority') OR (nested_record->'declaration' ? 'authority' AND (jsonb_typeof(nested_record->'declaration'->'authority') IS DISTINCT FROM 'string')) OR nested_record->'declaration'->>'authority' IS DISTINCT FROM 'source' OR NOT (nested_record->'declaration' ? 'source_id') OR (nested_record->'declaration' ? 'source_id' AND (jsonb_typeof(nested_record->'declaration'->'source_id') IS DISTINCT FROM 'string')) OR NOT (nested_record->'declaration' ? 'scope') OR (nested_record->'declaration' ? 'scope' AND (jsonb_typeof(nested_record->'declaration'->'scope') IS DISTINCT FROM 'string')) OR NOT (nested_record->'declaration' ? 'start') OR (nested_record->'declaration' ? 'start' AND (jsonb_typeof(nested_record->'declaration'->'start') IS DISTINCT FROM 'number' OR nested_record->'declaration'->>'start' !~ '^[0-9]+$')) OR (nested_record->'declaration' ? 'start' AND (nested_record->'declaration'->>'start')::numeric < 0) OR NOT (nested_record->'declaration' ? 'end') OR (nested_record->'declaration' ? 'end' AND (jsonb_typeof(nested_record->'declaration'->'end') IS DISTINCT FROM 'number' OR nested_record->'declaration'->>'end' !~ '^[0-9]+$')) OR (nested_record->'declaration' ? 'end' AND (nested_record->'declaration'->>'end')::numeric < 0) OR NOT (nested_record->'declaration' ? 'symbol') OR (nested_record->'declaration' ? 'symbol' AND (jsonb_typeof(nested_record->'declaration'->'symbol') IS DISTINCT FROM 'string')) OR NOT (nested_record->'declaration' ? 'evidence') OR (nested_record->'declaration' ? 'evidence' AND (jsonb_typeof(nested_record->'declaration'->'evidence') IS DISTINCT FROM 'string'))))) OR NOT (nested_record ? 'rule_id') OR (nested_record ? 'rule_id' AND (jsonb_typeof(nested_record->'rule_id') IS DISTINCT FROM 'string')) OR nested_record->>'rule_id' IS DISTINCT FROM 'function-definition-1' OR NOT (nested_record ? 'declaration_start') OR (nested_record ? 'declaration_start' AND (jsonb_typeof(nested_record->'declaration_start') IS DISTINCT FROM 'number' OR nested_record->>'declaration_start' !~ '^[0-9]+$')) OR (nested_record ? 'declaration_start' AND (nested_record->>'declaration_start')::numeric < 0) OR NOT (nested_record ? 'declaration_end') OR (nested_record ? 'declaration_end' AND (jsonb_typeof(nested_record->'declaration_end') IS DISTINCT FROM 'number' OR nested_record->>'declaration_end' !~ '^[0-9]+$')) OR (nested_record ? 'declaration_end' AND (nested_record->>'declaration_end')::numeric < 0) OR NOT (nested_record ? 'head_start') OR (nested_record ? 'head_start' AND (jsonb_typeof(nested_record->'head_start') IS DISTINCT FROM 'number' OR nested_record->>'head_start' !~ '^[0-9]+$')) OR (nested_record ? 'head_start' AND (nested_record->>'head_start')::numeric < 0) OR NOT (nested_record ? 'head_end') OR (nested_record ? 'head_end' AND (jsonb_typeof(nested_record->'head_end') IS DISTINCT FROM 'number' OR nested_record->>'head_end' !~ '^[0-9]+$')) OR (nested_record ? 'head_end' AND (nested_record->>'head_end')::numeric < 0) OR NOT (nested_record ? 'scope_start') OR (nested_record ? 'scope_start' AND (jsonb_typeof(nested_record->'scope_start') IS DISTINCT FROM 'number' OR nested_record->>'scope_start' !~ '^[0-9]+$')) OR (nested_record ? 'scope_start' AND (nested_record->>'scope_start')::numeric < 0) OR NOT (nested_record ? 'scope_end') OR (nested_record ? 'scope_end' AND (jsonb_typeof(nested_record->'scope_end') IS DISTINCT FROM 'number' OR nested_record->>'scope_end' !~ '^[0-9]+$')) OR (nested_record ? 'scope_end' AND (nested_record->>'scope_end')::numeric < 0) OR NOT (nested_record ? 'source_view_start') OR (nested_record ? 'source_view_start' AND (jsonb_typeof(nested_record->'source_view_start') IS DISTINCT FROM 'number' OR nested_record->>'source_view_start' !~ '^[0-9]+$')) OR (nested_record ? 'source_view_start' AND (nested_record->>'source_view_start')::numeric < 0) OR NOT (nested_record ? 'source_view_end') OR (nested_record ? 'source_view_end' AND (jsonb_typeof(nested_record->'source_view_end') IS DISTINCT FROM 'number' OR nested_record->>'source_view_end' !~ '^[0-9]+$')) OR (nested_record ? 'source_view_end' AND (nested_record->>'source_view_end')::numeric < 0) OR NOT (nested_record ? 'scope_key') OR (nested_record ? 'scope_key' AND (jsonb_typeof(nested_record->'scope_key') IS DISTINCT FROM 'string')) OR NOT (nested_record ? 'source_view_node_id') OR (nested_record ? 'source_view_node_id' AND (jsonb_typeof(nested_record->'source_view_node_id') IS DISTINCT FROM 'string')) OR NOT (nested_record ? 'relationship_id') OR (nested_record ? 'relationship_id' AND (jsonb_typeof(nested_record->'relationship_id') IS DISTINCT FROM 'string')))))) OR NOT (parsing_item ? 'interpretation_id') OR (parsing_item ? 'interpretation_id' AND (jsonb_typeof(parsing_item->'interpretation_id') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'product_id') OR (parsing_item ? 'product_id' AND (jsonb_typeof(parsing_item->'product_id') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'occurrence_ids') OR (parsing_item ? 'occurrence_ids' AND (jsonb_typeof(parsing_item->'occurrence_ids') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(parsing_item->'occurrence_ids') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string') OR jsonb_array_length(parsing_item->'occurrence_ids') < 1)) OR NOT (parsing_item ? 'context_digest') OR (parsing_item ? 'context_digest' AND (jsonb_typeof(parsing_item->'context_digest') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'declaration_digest') OR (parsing_item ? 'declaration_digest' AND (jsonb_typeof(parsing_item->'declaration_digest') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'assumption_digest') OR (parsing_item ? 'assumption_digest' AND (jsonb_typeof(parsing_item->'assumption_digest') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'adapter_id') OR (parsing_item ? 'adapter_id' AND (jsonb_typeof(parsing_item->'adapter_id') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'semantic_state') OR (parsing_item ? 'semantic_state' AND (jsonb_typeof(parsing_item->'semantic_state') IS DISTINCT FROM 'string' OR parsing_item->>'semantic_state' NOT IN ('ambiguous','invalid','ok','unknown','unsupported'))) OR NOT (parsing_item ? 'coverage') OR (parsing_item ? 'coverage' AND (jsonb_typeof(parsing_item->'coverage') IS DISTINCT FROM 'string' OR parsing_item->>'coverage' NOT IN ('complete','partial','unknown','unsupported'))) OR (parsing_item ? 'alternative_group' AND (jsonb_typeof(parsing_item->'alternative_group') IS DISTINCT FROM 'string')) THEN RAISE EXCEPTION 'parsing record shape differs: ParsingInterpretation' USING ERRCODE='23514'; END IF;
END LOOP;
FOR parsing_item IN SELECT value FROM jsonb_array_elements(COALESCE(product->'assessments','[]'::jsonb)) LOOP
IF jsonb_typeof(parsing_item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: ParsingAssessment' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(parsing_item) key WHERE key<>ALL(ARRAY['assessment_id','product_id','interpretation_ids','question','conditions_digest','algorithm_revision','policy_id','outcome','coverage','evidence_ids'])) OR NOT (parsing_item ? 'assessment_id') OR (parsing_item ? 'assessment_id' AND (jsonb_typeof(parsing_item->'assessment_id') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'product_id') OR (parsing_item ? 'product_id' AND (jsonb_typeof(parsing_item->'product_id') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'interpretation_ids') OR (parsing_item ? 'interpretation_ids' AND (jsonb_typeof(parsing_item->'interpretation_ids') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(parsing_item->'interpretation_ids') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string') OR jsonb_array_length(parsing_item->'interpretation_ids') < 1)) OR NOT (parsing_item ? 'question') OR (parsing_item ? 'question' AND (jsonb_typeof(parsing_item->'question') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'conditions_digest') OR (parsing_item ? 'conditions_digest' AND (jsonb_typeof(parsing_item->'conditions_digest') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'algorithm_revision') OR (parsing_item ? 'algorithm_revision' AND (jsonb_typeof(parsing_item->'algorithm_revision') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'policy_id') OR (parsing_item ? 'policy_id' AND (jsonb_typeof(parsing_item->'policy_id') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'outcome') OR (parsing_item ? 'outcome' AND (jsonb_typeof(parsing_item->'outcome') IS DISTINCT FROM 'string' OR parsing_item->>'outcome' NOT IN ('ambiguous','invalid','ok','unknown','unsupported'))) OR NOT (parsing_item ? 'coverage') OR (parsing_item ? 'coverage' AND (jsonb_typeof(parsing_item->'coverage') IS DISTINCT FROM 'string' OR parsing_item->>'coverage' NOT IN ('complete','partial','unknown','unsupported'))) OR NOT (parsing_item ? 'evidence_ids') OR (parsing_item ? 'evidence_ids' AND (jsonb_typeof(parsing_item->'evidence_ids') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(parsing_item->'evidence_ids') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string') OR jsonb_array_length(parsing_item->'evidence_ids') < 1)) THEN RAISE EXCEPTION 'parsing record shape differs: ParsingAssessment' USING ERRCODE='23514'; END IF;
END LOOP;

 layer_key:=product->>'product_key'; operation:=product->>'operation';
 SELECT * INTO previous FROM ops.parsing_layer_product WHERE task_id=p_task AND product_key=layer_key;
 IF FOUND THEN
  IF previous.content_digest<>digest OR previous.payload<>p_payload OR previous.contract_digest<>p_contract THEN RAISE EXCEPTION 'immutable layered product replay differs' USING ERRCODE='23514'; END IF;
  RETURN digest;
 END IF;
 PERFORM sem.require_execution_operation(run.release_id,'publish_parsing_product');
 PERFORM sem.require_execution_operation(run.release_id,operation);
 PERFORM sem.require_parsing_contract(run.release_id);
 IF run.sealed OR run.status NOT IN ('created','running') OR job.status<>'running' THEN RAISE EXCEPTION 'run/attempt no longer accepts layered products' USING ERRCODE='P0004'; END IF;
 IF layer_key='' OR layer_key='source' OR operation IS DISTINCT FROM (CASE product->>'kind' WHEN 'text' THEN 'prepare_parsing_text' WHEN 'interpretation' THEN 'interpret_parsing_math' WHEN 'assessment' THEN 'assess_parsing_math' END) THEN RAISE EXCEPTION 'layer product kind/operation differs' USING ERRCODE='23514'; END IF;
 IF p_contract IS DISTINCT FROM '8bd209f9163b016738b7a896903358b91e7fa60711e9aeba37ad69d7d8c5fcf8' OR NOT EXISTS(SELECT FROM sem.input WHERE release_id=run.release_id AND input_kind='dependency' AND input_name='execution/schema/parsing_products' AND encode(sha256(content),'hex')=p_contract) THEN RAISE EXCEPTION 'layer contract is not archived by task release' USING ERRCODE='23514'; END IF;
 SELECT a INTO adapter FROM sem.registry_row m CROSS JOIN LATERAL jsonb_array_elements(convert_from(m.body,'UTF8')::jsonb->'parsing_adapters') a WHERE m.release_id=run.release_id AND m.kind='execution_model' AND a->>'adapter_id'=product->>'adapter_id';
 IF adapter IS NULL OR NOT (adapter->'capabilities') ? (CASE product->>'kind' WHEN 'text' THEN 'text/lexical-partition' WHEN 'interpretation' THEN 'math/interpretation' ELSE 'math/assessment' END) THEN RAISE EXCEPTION 'layer producer adapter capability unavailable' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT root FROM ops.parsing_layer_product WHERE task_id=(product->'root'->>'task_id')::bigint AND product_key=product->'root'->>'product_key' AND content_digest=product->'root'->>'content_digest' AND kind='source';
 IF root.release_id<>run.release_id OR NOT EXISTS(SELECT FROM ops.rendition_build b JOIN ops.run_rendition chosen ON chosen.document_id=b.document_id AND chosen.rendition_id=b.rendition_id JOIN ops.task origin_task ON origin_task.id=b.task_id JOIN ops.run origin ON origin.id=origin_task.run_id WHERE b.task_id=root.task_id AND chosen.run_id=run.id AND origin.project_id=run.project_id) THEN RAISE EXCEPTION 'root source build is outside task release/project/selection' USING ERRCODE='23514'; END IF;
 INSERT INTO ops.parsing_layer_product(task_id,product_key,content_digest,release_id,kind,root_task_id,root_product_key,root_content_digest,contract_digest,operation,adapter_id,lifecycle,semantic_state,coverage,payload)
 VALUES(p_task,layer_key,digest,run.release_id,product->>'kind',root.task_id,root.product_key,root.content_digest,p_contract,operation,product->>'adapter_id',product->>'lifecycle',product->>'semantic_state',product->>'coverage',p_payload);
 INSERT INTO kb.source_artifact(artifact_digest,content) SELECT encode(sha256(content),'hex'),content FROM unnest(p_artifacts) content ON CONFLICT DO NOTHING;
 INSERT INTO kb.parsing_layer_representation(task_id,representation_id,kind,unit,extent_length,text_content,partition_state,recognition_state,encoding,decoder,newline_policy,text_content_utf8_base64,product_key) SELECT p_task,item.representation_id,item.kind,item.unit,item.extent_length,item.text_content,item.partition_state,item.recognition_state,item.encoding,item.decoder,item.newline_policy,item.text_content_utf8_base64,layer_key FROM jsonb_populate_recordset(NULL::kb.parsing_layer_representation,COALESCE(product->'representations','[]'::jsonb)) item;
INSERT INTO kb.parsing_layer_component(task_id,component_id,ordinal,category,representation_id,unit,start_offset,end_offset,product_key) SELECT p_task,item.component_id,item.ordinal,item.category,item.representation_id,item.unit,item.start_offset,item.end_offset,layer_key FROM jsonb_populate_recordset(NULL::kb.parsing_layer_component,COALESCE(product->'components','[]'::jsonb)) item;
INSERT INTO kb.parsing_layer_node(task_id,node_id,kind,representation_id,unit,start_offset,end_offset,origin,origin_reason,name,value,ordinal,attribute_outcome,name_start_offset,name_end_offset,value_start_offset,value_end_offset,product_key,macro_event) SELECT p_task,item.node_id,item.kind,item.representation_id,item.unit,item.start_offset,item.end_offset,item.origin,item.origin_reason,item.name,item.value,item.ordinal,item.attribute_outcome,item.name_start_offset,item.name_end_offset,item.value_start_offset,item.value_end_offset,layer_key,item.macro_event FROM jsonb_populate_recordset(NULL::kb.parsing_layer_node,COALESCE(product->'nodes','[]'::jsonb)) item;
INSERT INTO kb.parsing_layer_relationship(task_id,relationship_id,kind,ordinal,product_key) SELECT p_task,item.relationship_id,item.kind,item.ordinal,layer_key FROM jsonb_populate_recordset(NULL::kb.parsing_layer_relationship,COALESCE(product->'relationships','[]'::jsonb)) item;
INSERT INTO kb.parsing_layer_endpoint(task_id,relationship_id,ordinal,role,target_task_id,component_id,node_id,dependency_name,product_key,target_product_key,target_content_digest) SELECT p_task,item.relationship_id,item.ordinal,item.role,COALESCE(item.target_task_id,p_task),item.component_id,item.node_id,item.dependency_name,layer_key,COALESCE(item.target_product_key,layer_key),COALESCE(item.target_content_digest,digest) FROM jsonb_populate_recordset(NULL::kb.parsing_layer_endpoint,COALESCE(product->'endpoints','[]'::jsonb)) item;
INSERT INTO kb.parsing_layer_mapping(task_id,mapping_id,operation,reason,fidelity,product_key) SELECT p_task,item.mapping_id,item.operation,item.reason,item.fidelity,layer_key FROM jsonb_populate_recordset(NULL::kb.parsing_layer_mapping,COALESCE(product->'mappings','[]'::jsonb)) item;
INSERT INTO kb.parsing_layer_mapping_endpoint(task_id,mapping_id,side,ordinal,target_task_id,dependency_name,representation_id,unit,start_offset,end_offset,product_key,target_product_key,target_content_digest) SELECT p_task,item.mapping_id,item.side,item.ordinal,COALESCE(item.target_task_id,p_task),item.dependency_name,item.representation_id,item.unit,item.start_offset,item.end_offset,layer_key,COALESCE(item.target_product_key,layer_key),COALESCE(item.target_content_digest,digest) FROM jsonb_populate_recordset(NULL::kb.parsing_layer_mapping_endpoint,COALESCE(product->'mapping_endpoints','[]'::jsonb)) item;
INSERT INTO kb.parsing_layer_dependency(task_id,product_key,name,kind,target_task_id,target_product_key,target_content_digest,artifact_digest) SELECT p_task,layer_key,item.name,item.kind,item.target_task_id,item.target_product_key,item.target_content_digest,item.artifact_digest FROM jsonb_populate_recordset(NULL::kb.parsing_layer_dependency,COALESCE(product->'dependencies','[]'::jsonb)) item;
INSERT INTO kb.parsing_layer_interpretation(task_id,product_key,interpretation_id,semantic_state,coverage,payload) SELECT p_task,layer_key,item->>'interpretation_id',item->>'semantic_state',item->>'coverage',convert_to(item::text,'UTF8') FROM jsonb_array_elements(COALESCE(product->'interpretations','[]'::jsonb)) item;
INSERT INTO kb.parsing_layer_assessment(task_id,product_key,assessment_id,semantic_state,coverage,payload) SELECT p_task,layer_key,item->>'assessment_id',item->>'outcome',item->>'coverage',convert_to(item::text,'UTF8') FROM jsonb_array_elements(COALESCE(product->'assessments','[]'::jsonb)) item;
 -- Named product dependencies carry exact content identity, release/project and root custody.
 IF EXISTS(SELECT FROM kb.parsing_layer_dependency d JOIN ops.parsing_layer_product target ON target.task_id=d.target_task_id AND target.product_key=d.target_product_key JOIN ops.task t ON t.id=target.task_id JOIN ops.run r ON r.id=t.run_id WHERE d.task_id=p_task AND d.product_key=layer_key AND (target.release_id<>run.release_id OR r.project_id<>run.project_id)) THEN RAISE EXCEPTION 'layer dependency is outside release/project/root custody' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_layer_endpoint e WHERE e.task_id=p_task AND e.product_key=layer_key AND ((e.target_task_id=p_task AND e.target_product_key=layer_key AND e.dependency_name IS NOT NULL) OR ((e.target_task_id<>p_task OR e.target_product_key<>layer_key) AND NOT EXISTS(SELECT FROM kb.parsing_layer_dependency d WHERE d.task_id=e.task_id AND d.product_key=e.product_key AND d.name=e.dependency_name AND d.kind='product' AND d.target_task_id=e.target_task_id AND d.target_product_key=e.target_product_key AND d.target_content_digest=e.target_content_digest)))) THEN RAISE EXCEPTION 'layer endpoint has no named exact dependency custody' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_layer_mapping_endpoint e WHERE e.task_id=p_task AND e.product_key=layer_key AND ((e.target_task_id=p_task AND e.target_product_key=layer_key AND e.dependency_name IS NOT NULL) OR ((e.target_task_id<>p_task OR e.target_product_key<>layer_key) AND NOT EXISTS(SELECT FROM kb.parsing_layer_dependency d WHERE d.task_id=e.task_id AND d.product_key=e.product_key AND d.name=e.dependency_name AND d.kind='product' AND d.target_task_id=e.target_task_id AND d.target_product_key=e.target_product_key AND d.target_content_digest=e.target_content_digest)))) THEN RAISE EXCEPTION 'layer mapping has no named exact dependency custody' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_layer_component c JOIN kb.parsing_layer_representation r USING(task_id,product_key,representation_id,unit) WHERE c.task_id=p_task AND c.product_key=layer_key AND c.end_offset>r.extent_length) OR EXISTS(SELECT FROM kb.parsing_layer_mapping_endpoint e JOIN kb.parsing_layer_representation r ON r.task_id=e.target_task_id AND r.product_key=e.target_product_key AND r.representation_id=e.representation_id AND r.unit=e.unit WHERE e.task_id=p_task AND e.product_key=layer_key AND e.end_offset>r.extent_length) THEN RAISE EXCEPTION 'layer component/mapping extent exceeds representation' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_layer_node n JOIN kb.parsing_layer_representation r USING(task_id,product_key,representation_id,unit) WHERE n.task_id=p_task AND n.product_key=layer_key AND n.end_offset>r.extent_length) THEN RAISE EXCEPTION 'layer node extent exceeds representation' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_layer_representation r WHERE r.task_id=p_task AND r.product_key=layer_key AND (r.kind='original' OR r.unit<>'codepoint' OR r.extent_length<>char_length(convert_from(ops.parsing_safe_utf8(CASE WHEN r.text_content IS NOT NULL THEN convert_to(r.text_content,'UTF8') ELSE decode(r.text_content_utf8_base64,'base64') END),'UTF8')))) THEN RAISE EXCEPTION 'layer representation content/coordinates differ' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM (SELECT c.*,lag(end_offset,1,0::bigint) OVER(PARTITION BY representation_id ORDER BY ordinal) previous,row_number() OVER(PARTITION BY representation_id ORDER BY ordinal)-1 expected FROM kb.parsing_layer_component c WHERE task_id=p_task AND product_key=layer_key) c JOIN kb.parsing_layer_representation r USING(task_id,product_key,representation_id) WHERE c.ordinal<>c.expected OR c.start_offset<c.previous OR (r.partition_state='complete' AND c.start_offset<>c.previous)) OR EXISTS(SELECT FROM kb.parsing_layer_representation r WHERE r.task_id=p_task AND r.product_key=layer_key AND r.partition_state='complete' AND r.extent_length<>COALESCE((SELECT max(c.end_offset) FROM kb.parsing_layer_component c WHERE c.task_id=r.task_id AND c.product_key=r.product_key AND c.representation_id=r.representation_id),0)) THEN RAISE EXCEPTION 'layer partition gap/overlap/order differs' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_layer_relationship r LEFT JOIN LATERAL(SELECT array_agg(e.role ORDER BY e.ordinal) roles,array_agg(e.ordinal ORDER BY e.ordinal) positions FROM kb.parsing_layer_endpoint e WHERE e.task_id=r.task_id AND e.product_key=r.product_key AND e.relationship_id=r.relationship_id) actual ON true WHERE r.task_id=p_task AND r.product_key=layer_key AND (actual.roles IS DISTINCT FROM (SELECT array_agg(endpoint->>'role' ORDER BY position) FROM sem.registry_row model CROSS JOIN LATERAL jsonb_array_elements(convert_from(model.body,'UTF8')::jsonb->'relationships') definition CROSS JOIN LATERAL jsonb_array_elements(definition->'endpoints') WITH ORDINALITY rows(endpoint,position) WHERE model.release_id=run.release_id AND model.kind='execution_model' AND definition->>'id'='parsing_'||r.kind) OR actual.positions IS DISTINCT FROM ARRAY(SELECT generate_series(0::bigint,cardinality(actual.roles)-1)))) THEN RAISE EXCEPTION 'layer relationship endpoint role/order differs' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_layer_component c JOIN kb.parsing_layer_representation r USING(task_id,product_key,representation_id) WHERE c.task_id=p_task AND c.product_key=layer_key AND r.recognition_state='complete' AND c.category='unknown') THEN RAISE EXCEPTION 'unknown components cannot establish complete recognition' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_layer_mapping m WHERE m.task_id=p_task AND m.product_key=layer_key AND (
  (m.fidelity IN ('exact','transformed') AND (NOT EXISTS(SELECT FROM kb.parsing_layer_mapping_endpoint e WHERE e.task_id=m.task_id AND e.product_key=m.product_key AND e.mapping_id=m.mapping_id AND side='source') OR NOT EXISTS(SELECT FROM kb.parsing_layer_mapping_endpoint e WHERE e.task_id=m.task_id AND e.product_key=m.product_key AND e.mapping_id=m.mapping_id AND side='target')))
  OR (m.fidelity='synthetic' AND (EXISTS(SELECT FROM kb.parsing_layer_mapping_endpoint e WHERE e.task_id=m.task_id AND e.product_key=m.product_key AND e.mapping_id=m.mapping_id AND side='source') OR NOT EXISTS(SELECT FROM kb.parsing_layer_mapping_endpoint e WHERE e.task_id=m.task_id AND e.product_key=m.product_key AND e.mapping_id=m.mapping_id AND side='target')))
  OR (m.fidelity='excluded' AND (NOT EXISTS(SELECT FROM kb.parsing_layer_mapping_endpoint e WHERE e.task_id=m.task_id AND e.product_key=m.product_key AND e.mapping_id=m.mapping_id AND side='source') OR EXISTS(SELECT FROM kb.parsing_layer_mapping_endpoint e WHERE e.task_id=m.task_id AND e.product_key=m.product_key AND e.mapping_id=m.mapping_id AND side='target'))))) THEN RAISE EXCEPTION 'layer mapping fidelity/extent sets differ' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM (SELECT ordinal,row_number() OVER(PARTITION BY mapping_id,side ORDER BY ordinal)-1 expected FROM kb.parsing_layer_mapping_endpoint WHERE task_id=p_task AND product_key=layer_key) e WHERE ordinal<>expected) THEN RAISE EXCEPTION 'layer mapping extent order has gaps' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_layer_mapping m WHERE m.task_id=p_task AND m.product_key=layer_key AND m.fidelity='exact' AND (m.operation<>'copy' OR (SELECT count(DISTINCT e.unit) FROM kb.parsing_layer_mapping_endpoint e WHERE e.task_id=m.task_id AND e.product_key=m.product_key AND e.mapping_id=m.mapping_id)<>1 OR
  (SELECT string_agg(ops.parsing_codepoint_slice(r.text_content,r.text_content_utf8_base64,e.start_offset,e.end_offset),''::bytea ORDER BY e.ordinal) FROM kb.parsing_layer_mapping_endpoint e JOIN kb.parsing_layer_representation r ON r.task_id=e.target_task_id AND r.product_key=e.target_product_key AND r.representation_id=e.representation_id WHERE e.task_id=m.task_id AND e.product_key=m.product_key AND e.mapping_id=m.mapping_id AND side='source') IS DISTINCT FROM
  (SELECT string_agg(ops.parsing_codepoint_slice(r.text_content,r.text_content_utf8_base64,e.start_offset,e.end_offset),''::bytea ORDER BY e.ordinal) FROM kb.parsing_layer_mapping_endpoint e JOIN kb.parsing_layer_representation r ON r.task_id=e.target_task_id AND r.product_key=e.target_product_key AND r.representation_id=e.representation_id WHERE e.task_id=m.task_id AND e.product_key=m.product_key AND e.mapping_id=m.mapping_id AND side='target'))) THEN RAISE EXCEPTION 'exact layer copy content differs' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_layer_endpoint e JOIN kb.parsing_layer_relationship r USING(task_id,product_key,relationship_id) WHERE r.task_id=p_task AND r.product_key=layer_key AND r.kind IN ('contains','structural_parent') AND (e.target_task_id<>p_task OR e.target_product_key<>layer_key OR e.node_id IS NULL)) THEN RAISE EXCEPTION 'layer containment requires local structural nodes' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_layer_relationship rel JOIN kb.parsing_layer_endpoint parent ON parent.task_id=rel.task_id AND parent.product_key=rel.product_key AND parent.relationship_id=rel.relationship_id AND parent.ordinal=0 JOIN kb.parsing_layer_endpoint child ON child.task_id=rel.task_id AND child.product_key=rel.product_key AND child.relationship_id=rel.relationship_id AND child.ordinal=1 JOIN kb.parsing_layer_node p ON p.task_id=parent.target_task_id AND p.product_key=parent.target_product_key AND p.node_id=parent.node_id JOIN kb.parsing_layer_node c ON c.task_id=child.target_task_id AND c.product_key=child.target_product_key AND c.node_id=child.node_id WHERE rel.task_id=p_task AND rel.product_key=layer_key AND rel.kind='contains' AND p.origin='literal' AND c.origin='literal' AND (p.representation_id<>c.representation_id OR p.start_offset>c.start_offset OR p.end_offset<c.end_offset)) THEN RAISE EXCEPTION 'layer containment extents differ' USING ERRCODE='23514'; END IF;
 IF EXISTS(WITH RECURSIVE edges AS(SELECT p.node_id parent,c.node_id child FROM kb.parsing_layer_relationship r JOIN kb.parsing_layer_endpoint p USING(task_id,product_key,relationship_id) JOIN kb.parsing_layer_endpoint c USING(task_id,product_key,relationship_id) WHERE r.task_id=p_task AND r.product_key=layer_key AND r.kind IN ('contains','structural_parent') AND p.ordinal=0 AND c.ordinal=1), walk AS(SELECT parent,child,ARRAY[parent,child] path,parent=child cycle FROM edges UNION ALL SELECT w.parent,e.child,w.path||e.child,e.child=ANY(w.path) FROM walk w JOIN edges e ON e.parent=w.child WHERE NOT w.cycle) SELECT FROM walk WHERE cycle) THEN RAISE EXCEPTION 'layer containment cycle' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(COALESCE(product->'interpretations','[]'::jsonb)) item WHERE product->>'kind'<>'interpretation' OR item->>'product_id'<>layer_key) OR EXISTS(SELECT FROM jsonb_array_elements(COALESCE(product->'assessments','[]'::jsonb)) item WHERE product->>'kind'<>'assessment' OR item->>'product_id'<>layer_key) THEN RAISE EXCEPTION 'semantic layer record kind/identity differs' USING ERRCODE='23514'; END IF;
 -- Semantic record references resolve actual occurrences, not merely JSON spelling.
 IF EXISTS(SELECT FROM jsonb_array_elements(COALESCE(product->'interpretations','[]'::jsonb)) interpretation
  WHERE NOT EXISTS(SELECT FROM kb.parsing_layer_node n WHERE n.task_id=p_task AND n.product_key=layer_key AND n.node_id=interpretation->>'interpretation_id')
  OR EXISTS(SELECT FROM jsonb_array_elements_text(interpretation->'occurrence_ids') identity
   WHERE NOT EXISTS(SELECT FROM kb.parsing_layer_node n WHERE n.task_id=p_task AND n.product_key=layer_key AND n.node_id=identity)
    AND NOT EXISTS(SELECT FROM kb.parsing_layer_component c WHERE c.task_id=p_task AND c.product_key=layer_key AND c.component_id=identity))) THEN
  RAISE EXCEPTION 'interpretation occurrence reference has no local custody' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(COALESCE(product->'assessments','[]'::jsonb)) assessment
  CROSS JOIN LATERAL jsonb_array_elements_text(assessment->'evidence_ids') identity
  WHERE NOT EXISTS(SELECT FROM kb.parsing_layer_node n WHERE n.task_id=p_task AND n.product_key=layer_key AND n.node_id=identity)) THEN
  RAISE EXCEPTION 'assessment evidence reference has no local node custody' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(COALESCE(product->'assessments','[]'::jsonb)) assessment
  CROSS JOIN LATERAL jsonb_array_elements_text(assessment->'interpretation_ids') identity
  WHERE NOT EXISTS(SELECT FROM kb.parsing_layer_relationship r
   JOIN kb.parsing_layer_endpoint target ON target.task_id=r.task_id AND target.product_key=r.product_key AND target.relationship_id=r.relationship_id AND target.ordinal=0
   JOIN kb.parsing_layer_endpoint source ON source.task_id=r.task_id AND source.product_key=r.product_key AND source.relationship_id=r.relationship_id AND source.ordinal=1
   JOIN kb.parsing_layer_dependency dependency ON dependency.task_id=source.task_id AND dependency.product_key=source.product_key AND dependency.name=source.dependency_name AND dependency.kind='product' AND dependency.target_task_id=source.target_task_id AND dependency.target_product_key=source.target_product_key AND dependency.target_content_digest=source.target_content_digest
   JOIN kb.parsing_layer_interpretation interpretation ON interpretation.task_id=source.target_task_id AND interpretation.product_key=source.target_product_key AND interpretation.interpretation_id=source.node_id
   WHERE r.task_id=p_task AND r.product_key=layer_key AND r.kind='derived_from'
    AND target.target_task_id=p_task AND target.target_product_key=layer_key AND (assessment->'evidence_ids') ? target.node_id AND source.node_id=identity)) THEN
  RAISE EXCEPTION 'assessment interpretation reference has no qualified interpretation custody' USING ERRCODE='23514'; END IF;
 -- Macro selection consumes typed status and source-qualified local ranges, never value text.
 IF EXISTS(SELECT FROM kb.parsing_layer_node n WHERE n.task_id=p_task AND n.product_key=layer_key AND n.kind='macro_event'
  AND (n.origin<>'literal' OR n.macro_event->>'command'='' OR ((n.macro_event->>'selected')::boolean AND n.macro_event->>'status'<>'accepted'))) THEN
  RAISE EXCEPTION 'macro-event metadata requires literal accepted selection custody' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_layer_node n
  CROSS JOIN LATERAL jsonb_each(n.macro_event) fields(name,ranges)
  CROSS JOIN LATERAL (SELECT (value->>'start_offset')::bigint first,(value->>'end_offset')::bigint last,
   lag((value->>'end_offset')::bigint,1,n.start_offset) OVER(ORDER BY position) previous
   FROM jsonb_array_elements(CASE WHEN fields.name IN ('name_ranges','body_ranges','default_ranges','count_ranges') THEN fields.ranges ELSE '[]'::jsonb END) WITH ORDINALITY pieces(value,position)) extent
  WHERE n.task_id=p_task AND n.product_key=layer_key AND n.kind='macro_event'
   AND fields.name IN ('name_ranges','body_ranges','default_ranges','count_ranges')
   AND (extent.first<extent.previous OR extent.first>=extent.last OR extent.last>n.end_offset)) THEN
  RAISE EXCEPTION 'macro-event metadata ranges exceed or disorder their parent extent' USING ERRCODE='23514'; END IF;
 -- Consumed source declarations retain a typed rule, applicability and qualified evidence view.
 IF EXISTS(SELECT FROM jsonb_array_elements(COALESCE(product->'interpretations','[]'::jsonb)) interpretation
  CROSS JOIN LATERAL jsonb_array_elements(COALESCE(interpretation->'declaration_basis','[]'::jsonb)) basis
  WHERE NOT EXISTS(SELECT FROM sem.registry_row model
   CROSS JOIN LATERAL jsonb_array_elements(convert_from(model.body,'UTF8')::jsonb->'analysis_profiles') profile
   WHERE model.release_id=run.release_id AND model.kind='execution_model' AND (profile->'local_declaration_rules') ? (basis->>'rule_id'))
   OR basis->'declaration'->>'symbol'='' OR basis->'declaration'->>'source_id'='' OR basis->'declaration'->>'evidence'='' OR basis->>'scope_key'=''
   OR basis->'declaration'->>'scope' IS DISTINCT FROM basis->>'scope_key'
   OR (basis->'declaration'->>'start')::bigint IS DISTINCT FROM (basis->>'scope_start')::bigint
   OR (basis->'declaration'->>'end')::bigint IS DISTINCT FROM (basis->>'scope_end')::bigint
   OR NOT ((basis->>'source_view_start')::bigint<=(basis->>'declaration_start')::bigint
    AND (basis->>'declaration_start')::bigint<=(basis->>'head_start')::bigint
    AND (basis->>'head_start')::bigint<(basis->>'head_end')::bigint
    AND (basis->>'head_end')::bigint<=(basis->>'declaration_end')::bigint
    AND (basis->>'declaration_end')::bigint<=(basis->>'source_view_end')::bigint
    AND (basis->>'source_view_end')::bigint<=(basis->>'scope_start')::bigint
    AND (basis->>'scope_start')::bigint<(basis->>'scope_end')::bigint)) THEN
  RAISE EXCEPTION 'source declaration rule/applicability basis differs' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(COALESCE(product->'interpretations','[]'::jsonb)) interpretation
  CROSS JOIN LATERAL jsonb_array_elements(COALESCE(interpretation->'declaration_basis','[]'::jsonb)) basis
  WHERE NOT EXISTS(SELECT FROM kb.parsing_layer_relationship relationship
   JOIN kb.parsing_layer_endpoint target ON target.task_id=relationship.task_id AND target.product_key=relationship.product_key AND target.relationship_id=relationship.relationship_id AND target.ordinal=0
   JOIN kb.parsing_layer_endpoint source ON source.task_id=relationship.task_id AND source.product_key=relationship.product_key AND source.relationship_id=relationship.relationship_id AND source.ordinal=1
   JOIN kb.parsing_layer_node view ON view.task_id=source.target_task_id AND view.product_key=source.target_product_key AND view.node_id=source.node_id
   JOIN kb.parsing_layer_representation representation ON representation.task_id=view.task_id AND representation.product_key=view.product_key AND representation.representation_id=view.representation_id AND representation.unit=view.unit
   JOIN ops.parsing_layer_product input ON input.task_id=view.task_id AND input.product_key=view.product_key AND input.content_digest=source.target_content_digest
   WHERE relationship.task_id=p_task AND relationship.product_key=layer_key AND relationship.relationship_id=basis->>'relationship_id' AND relationship.kind='derived_from'
    AND target.target_task_id=p_task AND target.target_product_key=layer_key AND target.node_id=interpretation->>'interpretation_id'
    AND input.kind='text' AND view.kind='parse_view' AND view.origin='literal' AND view.unit='codepoint' AND view.representation_id='canonical'
    AND view.node_id=basis->>'source_view_node_id' AND view.start_offset=(basis->>'source_view_start')::bigint AND view.end_offset=(basis->>'source_view_end')::bigint
    AND (basis->>'scope_end')::bigint<=representation.extent_length)) THEN
  RAISE EXCEPTION 'source declaration has no qualified canonical evidence-view custody' USING ERRCODE='23514'; END IF;
 RETURN digest;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION ops.publish_layered_parsing_product (bigint, bigint, text, text, bytea, bytea[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.publish_layered_parsing_product (bigint, bigint, text, text, bytea, bytea[]) TO corpus_sem_writer;
CREATE OR REPLACE FUNCTION ops.parsing_safe_utf8(p_bytes bytea) RETURNS bytea LANGUAGE sql IMMUTABLE RETURNS NULL ON NULL INPUT SET search_path TO 'pg_catalog', 'pg_temp' AS $$
 SELECT decode(replace(replace(regexp_replace(encode(p_bytes,'hex'),'(..)',E'\\1:','g'),'00:','01:'),':',''),'hex')
$$;
REVOKE ALL PRIVILEGES ON FUNCTION ops.parsing_safe_utf8 (bytea) FROM PUBLIC;
CREATE OR REPLACE FUNCTION ops.parsing_codepoint_slice(p_text text, p_encoded text, p_start bigint, p_end bigint) RETURNS bytea LANGUAGE plpgsql IMMUTABLE SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE original bytea; safe text; first_byte bigint; last_byte bigint;
BEGIN
 IF p_text IS NOT NULL THEN RETURN convert_to(substring(p_text FROM p_start::integer+1 FOR (p_end-p_start)::integer),'UTF8'); END IF;
 original:=decode(p_encoded,'base64'); safe:=convert_from(ops.parsing_safe_utf8(original),'UTF8');
 first_byte:=octet_length(convert_to(substring(safe FROM 1 FOR p_start::integer),'UTF8'));
 last_byte:=octet_length(convert_to(substring(safe FROM 1 FOR p_end::integer),'UTF8'));
 RETURN substring(original FROM first_byte::integer+1 FOR (last_byte-first_byte)::integer);
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION ops.parsing_codepoint_slice (text, text, bigint, bigint) FROM PUBLIC;
CREATE OR REPLACE FUNCTION sem.require_parsing_contract(r text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE model jsonb; expected jsonb; actual jsonb;
BEGIN
 SELECT convert_from(body,'UTF8')::jsonb INTO STRICT model FROM sem.registry_row WHERE release_id=r AND kind='execution_model';
 expected:=data.execution_contract_descriptor()->'parsing_relationship_profiles';
 SELECT jsonb_object_agg(substring(value->>'id' FROM 9),value) INTO actual FROM jsonb_array_elements(model->'relationships')
 WHERE expected ? substring(value->>'id' FROM 9);
 IF expected IS NULL OR actual IS DISTINCT FROM expected OR EXISTS(SELECT FROM jsonb_array_elements(model->'parsing_adapters') actual_adapter WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(data.execution_contract_descriptor()->'parsing_adapters') supported_adapter WHERE supported_adapter=actual_adapter)) THEN
  RAISE EXCEPTION 'unsupported parsing relationship profile; qualify implementation and deploy forward revision' USING ERRCODE='23514'; END IF;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION sem.require_parsing_contract (text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION sem.require_parsing_contract (text) TO corpus_sem_writer, corpus_sem_reader, corpus_sem_admitter, corpus_sem_evaluator;
CREATE OR REPLACE FUNCTION ops.parsing_origin_known(p_task bigint, p_rep text, p_first bigint, p_last bigint, p_path text[], p_adapter jsonb) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE representation kb.parsing_representation; mapping kb.parsing_mapping; source kb.parsing_mapping_endpoint; extent record; position bigint:=p_first;
BEGIN
 SELECT * INTO STRICT representation FROM kb.parsing_representation WHERE task_id=p_task AND representation_id=p_rep;
 IF p_first=p_last OR representation.kind='original' THEN RETURN true; END IF;
 IF cardinality(p_path)>=64 THEN RETURN false; END IF;
 FOR mapping IN SELECT DISTINCT m.* FROM kb.parsing_mapping_endpoint e JOIN kb.parsing_mapping m USING(task_id,mapping_id)
  WHERE e.task_id=p_task AND e.target_task_id=p_task AND e.representation_id=p_rep AND e.side='target' AND e.start_offset<p_last AND e.end_offset>p_first LOOP
  IF mapping.mapping_id=ANY(p_path) OR mapping.fidelity='unknown' THEN RETURN false; END IF;
  IF mapping.fidelity='synthetic' THEN
   IF p_adapter IS NULL OR NOT (p_adapter->'capabilities') ? 'mapping/synthetic' THEN RETURN false; END IF;
  ELSE
   IF NOT EXISTS(SELECT FROM kb.parsing_mapping_endpoint WHERE task_id=p_task AND mapping_id=mapping.mapping_id AND side='source') THEN RETURN false; END IF;
   FOR source IN SELECT * FROM kb.parsing_mapping_endpoint WHERE task_id=p_task AND mapping_id=mapping.mapping_id AND side='source' ORDER BY ordinal LOOP
    IF source.target_task_id<>p_task OR NOT ops.parsing_origin_known(p_task,source.representation_id,source.start_offset,source.end_offset,p_path||mapping.mapping_id,p_adapter) THEN RETURN false; END IF;
   END LOOP;
  END IF;
 END LOOP;
 FOR extent IN SELECT start_offset,end_offset FROM kb.parsing_mapping_endpoint
  WHERE task_id=p_task AND target_task_id=p_task AND representation_id=p_rep AND side='target' AND start_offset<p_last AND end_offset>p_first ORDER BY start_offset,end_offset LOOP
  IF extent.start_offset>position THEN RETURN false; END IF;
  position:=greatest(position,extent.end_offset);
 END LOOP;
 RETURN position>=p_last;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION ops.parsing_origin_known (bigint, text, bigint, bigint, text[], jsonb) FROM PUBLIC;
CREATE OR REPLACE FUNCTION ops.publish_parsing_product(p_task bigint, p_attempt bigint, p_holder text, p_contract text, p_payload bytea, p_original bytea) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE job ops.task; run ops.run; build ops.rendition_build; document kb.document;
 product jsonb; parsing_item jsonb; adapter jsonb; digest text; artifact text; previous ops.parsing_product;
BEGIN
 -- Match complete_unit's run-before-task order, including direct publication callers.
 SELECT r.* INTO STRICT run FROM ops.run r JOIN ops.task t ON t.run_id=r.id
  WHERE t.id=p_task FOR SHARE OF r;
 SELECT * INTO STRICT job FROM ops.task WHERE id=p_task AND run_id=run.id FOR UPDATE;
 PERFORM sem.require_execution_operation(run.release_id,'publish_parsing_product');
 PERFORM sem.require_parsing_contract(run.release_id);
