sing_item->'unit') IS DISTINCT FROM 'string' OR parsing_item->>'unit' NOT IN ('byte','codepoint'))) OR (parsing_item ? 'start_offset' AND (jsonb_typeof(parsing_item->'start_offset') IS DISTINCT FROM 'number' OR parsing_item->>'start_offset' !~ '^[0-9]+$')) OR (parsing_item ? 'start_offset' AND (parsing_item->>'start_offset')::numeric < 0) OR (parsing_item ? 'end_offset' AND (jsonb_typeof(parsing_item->'end_offset') IS DISTINCT FROM 'number' OR parsing_item->>'end_offset' !~ '^[0-9]+$')) OR (parsing_item ? 'end_offset' AND (parsing_item->>'end_offset')::numeric < 0)) AND (EXISTS(SELECT FROM jsonb_object_keys(parsing_item) key WHERE key<>ALL(ARRAY['kind','value','node_id','representation_id','unit','start_offset','end_offset','origin','origin_reason','name','ordinal'])) OR NOT (parsing_item ? 'kind') OR (parsing_item ? 'kind' AND (jsonb_typeof(parsing_item->'kind') IS DISTINCT FROM 'string')) OR parsing_item->>'kind' IS DISTINCT FROM 'unknown_macro' OR (parsing_item ? 'value' AND (jsonb_typeof(parsing_item->'value') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'node_id') OR (parsing_item ? 'node_id' AND (jsonb_typeof(parsing_item->'node_id') IS DISTINCT FROM 'string')) OR (parsing_item ? 'representation_id' AND (jsonb_typeof(parsing_item->'representation_id') IS DISTINCT FROM 'string')) OR (parsing_item ? 'unit' AND (jsonb_typeof(parsing_item->'unit') IS DISTINCT FROM 'string' OR parsing_item->>'unit' NOT IN ('byte','codepoint'))) OR (parsing_item ? 'start_offset' AND (jsonb_typeof(parsing_item->'start_offset') IS DISTINCT FROM 'number' OR parsing_item->>'start_offset' !~ '^[0-9]+$')) OR (parsing_item ? 'start_offset' AND (parsing_item->>'start_offset')::numeric < 0) OR (parsing_item ? 'end_offset' AND (jsonb_typeof(parsing_item->'end_offset') IS DISTINCT FROM 'number' OR parsing_item->>'end_offset' !~ '^[0-9]+$')) OR (parsing_item ? 'end_offset' AND (parsing_item->>'end_offset')::numeric < 0) OR NOT (parsing_item ? 'origin') OR (parsing_item ? 'origin' AND (jsonb_typeof(parsing_item->'origin') IS DISTINCT FROM 'string' OR parsing_item->>'origin' NOT IN ('derived','literal','synthetic'))) OR (parsing_item ? 'origin_reason' AND (jsonb_typeof(parsing_item->'origin_reason') IS DISTINCT FROM 'string')) OR (parsing_item ? 'name' AND (jsonb_typeof(parsing_item->'name') IS DISTINCT FROM 'string')) OR (parsing_item ? 'ordinal' AND (jsonb_typeof(parsing_item->'ordinal') IS DISTINCT FROM 'number' OR parsing_item->>'ordinal' !~ '^[0-9]+$')))) THEN RAISE EXCEPTION 'parsing record shape differs: ParsingNode' USING ERRCODE='23514'; END IF;
END LOOP;
FOR parsing_item IN SELECT value FROM jsonb_array_elements(COALESCE(product->'relationships','[]'::jsonb)) LOOP
IF jsonb_typeof(parsing_item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: ParsingRelationship' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(parsing_item) key WHERE key<>ALL(ARRAY['ordinal','relationship_id','kind'])) OR (parsing_item ? 'ordinal' AND (jsonb_typeof(parsing_item->'ordinal') IS DISTINCT FROM 'number' OR parsing_item->>'ordinal' !~ '^[0-9]+$')) OR (parsing_item ? 'ordinal' AND (parsing_item->>'ordinal')::numeric < 0) OR NOT (parsing_item ? 'relationship_id') OR (parsing_item ? 'relationship_id' AND (jsonb_typeof(parsing_item->'relationship_id') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'kind') OR (parsing_item ? 'kind' AND (jsonb_typeof(parsing_item->'kind') IS DISTINCT FROM 'string' OR parsing_item->>'kind' NOT IN ('attribute_of','binds','contains','derived_from','reference','sequence','structural_parent','text_of'))) THEN RAISE EXCEPTION 'parsing record shape differs: ParsingRelationship' USING ERRCODE='23514'; END IF;
END LOOP;
FOR parsing_item IN SELECT value FROM jsonb_array_elements(COALESCE(product->'endpoints','[]'::jsonb)) LOOP
IF jsonb_typeof(parsing_item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: ParsingEndpoint' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(parsing_item) key WHERE key<>ALL(ARRAY['relationship_id','ordinal','role','target_task_id','component_id','node_id','dependency_name'])) OR NOT (parsing_item ? 'relationship_id') OR (parsing_item ? 'relationship_id' AND (jsonb_typeof(parsing_item->'relationship_id') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'ordinal') OR (parsing_item ? 'ordinal' AND (jsonb_typeof(parsing_item->'ordinal') IS DISTINCT FROM 'number' OR parsing_item->>'ordinal' !~ '^[0-9]+$')) OR (parsing_item ? 'ordinal' AND (parsing_item->>'ordinal')::numeric < 0) OR NOT (parsing_item ? 'role') OR (parsing_item ? 'role' AND (jsonb_typeof(parsing_item->'role') IS DISTINCT FROM 'string' OR parsing_item->>'role' NOT IN ('argument','attribute','child','default','definition','fallback','invocation','member','owner','parent','source','target','text'))) OR (parsing_item ? 'target_task_id' AND (jsonb_typeof(parsing_item->'target_task_id') IS DISTINCT FROM 'number' OR parsing_item->>'target_task_id' !~ '^[0-9]+$')) OR (parsing_item ? 'target_task_id' AND (parsing_item->>'target_task_id')::numeric < 0) OR (parsing_item ? 'component_id' AND (jsonb_typeof(parsing_item->'component_id') IS DISTINCT FROM 'string')) OR (parsing_item ? 'node_id' AND (jsonb_typeof(parsing_item->'node_id') IS DISTINCT FROM 'string')) OR (parsing_item ? 'dependency_name' AND (jsonb_typeof(parsing_item->'dependency_name') IS DISTINCT FROM 'string')) THEN RAISE EXCEPTION 'parsing record shape differs: ParsingEndpoint' USING ERRCODE='23514'; END IF;
END LOOP;
FOR parsing_item IN SELECT value FROM jsonb_array_elements(COALESCE(product->'mappings','[]'::jsonb)) LOOP
IF jsonb_typeof(parsing_item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: ParsingMapping' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(parsing_item) key WHERE key<>ALL(ARRAY['mapping_id','operation','reason','fidelity'])) OR NOT (parsing_item ? 'mapping_id') OR (parsing_item ? 'mapping_id' AND (jsonb_typeof(parsing_item->'mapping_id') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'operation') OR (parsing_item ? 'operation' AND (jsonb_typeof(parsing_item->'operation') IS DISTINCT FROM 'string' OR parsing_item->>'operation' NOT IN ('copy','decode','exclude','expand','normalize','project','repair','synthetic'))) OR NOT (parsing_item ? 'reason') OR (parsing_item ? 'reason' AND (jsonb_typeof(parsing_item->'reason') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'fidelity') OR (parsing_item ? 'fidelity' AND (jsonb_typeof(parsing_item->'fidelity') IS DISTINCT FROM 'string' OR parsing_item->>'fidelity' NOT IN ('exact','excluded','synthetic','transformed','unknown'))) THEN RAISE EXCEPTION 'parsing record shape differs: ParsingMapping' USING ERRCODE='23514'; END IF;
END LOOP;
FOR parsing_item IN SELECT value FROM jsonb_array_elements(COALESCE(product->'mapping_endpoints','[]'::jsonb)) LOOP
IF jsonb_typeof(parsing_item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: ParsingMappingEndpoint' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(parsing_item) key WHERE key<>ALL(ARRAY['mapping_id','side','ordinal','target_task_id','dependency_name','representation_id','unit','start_offset','end_offset'])) OR NOT (parsing_item ? 'mapping_id') OR (parsing_item ? 'mapping_id' AND (jsonb_typeof(parsing_item->'mapping_id') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'side') OR (parsing_item ? 'side' AND (jsonb_typeof(parsing_item->'side') IS DISTINCT FROM 'string' OR parsing_item->>'side' NOT IN ('source','target'))) OR NOT (parsing_item ? 'ordinal') OR (parsing_item ? 'ordinal' AND (jsonb_typeof(parsing_item->'ordinal') IS DISTINCT FROM 'number' OR parsing_item->>'ordinal' !~ '^[0-9]+$')) OR (parsing_item ? 'ordinal' AND (parsing_item->>'ordinal')::numeric < 0) OR (parsing_item ? 'target_task_id' AND (jsonb_typeof(parsing_item->'target_task_id') IS DISTINCT FROM 'number' OR parsing_item->>'target_task_id' !~ '^[0-9]+$')) OR (parsing_item ? 'target_task_id' AND (parsing_item->>'target_task_id')::numeric < 0) OR (parsing_item ? 'dependency_name' AND (jsonb_typeof(parsing_item->'dependency_name') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'representation_id') OR (parsing_item ? 'representation_id' AND (jsonb_typeof(parsing_item->'representation_id') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'unit') OR (parsing_item ? 'unit' AND (jsonb_typeof(parsing_item->'unit') IS DISTINCT FROM 'string' OR parsing_item->>'unit' NOT IN ('byte','codepoint'))) OR NOT (parsing_item ? 'start_offset') OR (parsing_item ? 'start_offset' AND (jsonb_typeof(parsing_item->'start_offset') IS DISTINCT FROM 'number' OR parsing_item->>'start_offset' !~ '^[0-9]+$')) OR (parsing_item ? 'start_offset' AND (parsing_item->>'start_offset')::numeric < 0) OR NOT (parsing_item ? 'end_offset') OR (parsing_item ? 'end_offset' AND (jsonb_typeof(parsing_item->'end_offset') IS DISTINCT FROM 'number' OR parsing_item->>'end_offset' !~ '^[0-9]+$')) OR (parsing_item ? 'end_offset' AND (parsing_item->>'end_offset')::numeric < 0) THEN RAISE EXCEPTION 'parsing record shape differs: ParsingMappingEndpoint' USING ERRCODE='23514'; END IF;
END LOOP;
FOR parsing_item IN SELECT value FROM jsonb_array_elements(COALESCE(product->'dependencies','[]'::jsonb)) LOOP
IF jsonb_typeof(parsing_item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: ParsingDependency' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(parsing_item) key WHERE key<>ALL(ARRAY['name','target_task_id','artifact_digest'])) OR NOT (parsing_item ? 'name') OR (parsing_item ? 'name' AND (jsonb_typeof(parsing_item->'name') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'target_task_id') OR (parsing_item ? 'target_task_id' AND (jsonb_typeof(parsing_item->'target_task_id') IS DISTINCT FROM 'number' OR parsing_item->>'target_task_id' !~ '^[0-9]+$')) OR (parsing_item ? 'target_task_id' AND (parsing_item->>'target_task_id')::numeric < 0) OR NOT (parsing_item ? 'artifact_digest') OR (parsing_item ? 'artifact_digest' AND (jsonb_typeof(parsing_item->'artifact_digest') IS DISTINCT FROM 'string')) THEN RAISE EXCEPTION 'parsing record shape differs: ParsingDependency' USING ERRCODE='23514'; END IF;
END LOOP;

 IF p_contract IS DISTINCT FROM '8bd209f9163b016738b7a896903358b91e7fa60711e9aeba37ad69d7d8c5fcf8' OR NOT EXISTS(SELECT FROM sem.input WHERE release_id=run.release_id AND input_kind='dependency' AND input_name='execution/schema/parsing_products' AND encode(sha256(content),'hex')=p_contract) THEN
  RAISE EXCEPTION 'parsing contract is not bound to the source release' USING ERRCODE='23514'; END IF;
 SELECT a INTO adapter FROM sem.registry_row m CROSS JOIN LATERAL jsonb_array_elements(convert_from(m.body,'UTF8')::jsonb->'parsing_adapters') a WHERE m.release_id=run.release_id AND m.kind='execution_model' AND a->>'adapter_id'=product->>'adapter_id';
 IF product ? 'adapter_id' AND NOT EXISTS(SELECT FROM sem.registry_row m CROSS JOIN LATERAL jsonb_array_elements(convert_from(m.body,'UTF8')::jsonb->'parsing_adapters') a
  WHERE m.release_id=run.release_id AND m.kind='execution_model' AND a->>'adapter_id'=product->>'adapter_id') THEN
  RAISE EXCEPTION 'parsing adapter is not admitted by bound release' USING ERRCODE='23514'; END IF;
 IF document.content_hash IS DISTINCT FROM artifact OR product->>'artifact_digest' IS DISTINCT FROM artifact OR build.method_config_id<>job.method_config_id THEN
  RAISE EXCEPTION 'parsing original/configuration differs from the producing build' USING ERRCODE='23514'; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(product->'representations') r WHERE r->>'kind'='original')<>1
 OR EXISTS(SELECT FROM jsonb_array_elements(product->'representations') r WHERE r->>'kind'='original' AND ((r->>'extent_length')::bigint<>octet_length(p_original) OR r->>'unit'<>'byte'))
 OR (SELECT count(*) FROM jsonb_array_elements(product->'representations') r WHERE r->>'kind'='canonical')<>1
 OR NOT EXISTS(SELECT FROM jsonb_array_elements(product->'representations') r JOIN kb.rendition ren ON ren.id=build.rendition_id WHERE r->>'kind'='canonical' AND r->>'text_content'=ren.canonical_text) THEN
  RAISE EXCEPTION 'parsing representations differ from original/canonical source custody' USING ERRCODE='23514'; END IF;
 SELECT * INTO previous FROM ops.parsing_product WHERE task_id=p_task;
 IF FOUND THEN
  IF previous.payload IS DISTINCT FROM p_payload OR previous.contract_digest IS DISTINCT FROM p_contract THEN RAISE EXCEPTION 'parsing product differs on replay' USING ERRCODE='23505'; END IF;
  RETURN previous.product_digest;
 END IF;
 IF job.status<>'running' THEN RAISE EXCEPTION 'parsing publication requires a running task' USING ERRCODE='P0004'; END IF;
 INSERT INTO kb.source_artifact VALUES(artifact,p_original) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT FROM kb.source_artifact WHERE artifact_digest=artifact AND content=p_original) THEN RAISE EXCEPTION 'original artifact identity differs' USING ERRCODE='23505'; END IF;
 INSERT INTO ops.parsing_product(task_id,release_id,artifact_digest,contract_digest,product_digest,recipe,lifecycle,semantic_state,provenance_state,payload)
 VALUES(p_task,run.release_id,artifact,p_contract,digest,product->>'recipe',product->>'lifecycle',product->>'semantic_state',product->>'provenance_state',p_payload);
 INSERT INTO kb.parsing_representation(task_id,representation_id,kind,unit,extent_length,text_content,partition_state,recognition_state,encoding,decoder,newline_policy,text_content_utf8_base64) SELECT p_task,item.representation_id,item.kind,item.unit,item.extent_length,item.text_content,item.partition_state,item.recognition_state,item.encoding,item.decoder,item.newline_policy,item.text_content_utf8_base64 FROM jsonb_populate_recordset(NULL::kb.parsing_representation,COALESCE(product->'representations','[]'::jsonb)) item;
 INSERT INTO kb.parsing_component(task_id,component_id,ordinal,category,representation_id,unit,start_offset,end_offset) SELECT p_task,item.component_id,item.ordinal,item.category,item.representation_id,item.unit,item.start_offset,item.end_offset FROM jsonb_populate_recordset(NULL::kb.parsing_component,COALESCE(product->'components','[]'::jsonb)) item;
 INSERT INTO kb.parsing_node(task_id,node_id,kind,representation_id,unit,start_offset,end_offset,origin,origin_reason,name,value,ordinal,attribute_outcome,name_start_offset,name_end_offset,value_start_offset,value_end_offset) SELECT p_task,item.node_id,item.kind,item.representation_id,item.unit,item.start_offset,item.end_offset,item.origin,item.origin_reason,item.name,item.value,item.ordinal,item.attribute_outcome,item.name_start_offset,item.name_end_offset,item.value_start_offset,item.value_end_offset FROM jsonb_populate_recordset(NULL::kb.parsing_node,COALESCE(product->'nodes','[]'::jsonb)) item;
 INSERT INTO kb.parsing_relationship(task_id,relationship_id,kind,ordinal) SELECT p_task,item.relationship_id,item.kind,item.ordinal FROM jsonb_populate_recordset(NULL::kb.parsing_relationship,COALESCE(product->'relationships','[]'::jsonb)) item;
 INSERT INTO kb.parsing_mapping(task_id,mapping_id,operation,reason,fidelity) SELECT p_task,item.mapping_id,item.operation,item.reason,item.fidelity FROM jsonb_populate_recordset(NULL::kb.parsing_mapping,COALESCE(product->'mappings','[]'::jsonb)) item;
 INSERT INTO kb.parsing_dependency(task_id,name,target_task_id,artifact_digest) SELECT p_task,item.name,COALESCE(item.target_task_id,p_task),item.artifact_digest FROM jsonb_populate_recordset(NULL::kb.parsing_dependency,COALESCE(product->'dependencies','[]'::jsonb)) item;
 INSERT INTO kb.parsing_endpoint(task_id,relationship_id,ordinal,role,target_task_id,component_id,node_id,dependency_name) SELECT p_task,item.relationship_id,item.ordinal,item.role,COALESCE(item.target_task_id,p_task),item.component_id,item.node_id,item.dependency_name FROM jsonb_populate_recordset(NULL::kb.parsing_endpoint,COALESCE(product->'endpoints','[]'::jsonb)) item;
 INSERT INTO kb.parsing_mapping_endpoint(task_id,mapping_id,side,ordinal,target_task_id,dependency_name,representation_id,unit,start_offset,end_offset) SELECT p_task,item.mapping_id,item.side,item.ordinal,COALESCE(item.target_task_id,p_task),item.dependency_name,item.representation_id,item.unit,item.start_offset,item.end_offset FROM jsonb_populate_recordset(NULL::kb.parsing_mapping_endpoint,COALESCE(product->'mapping_endpoints','[]'::jsonb)) item;

 -- Cross-build references require the named dependency's artifact and the same release/project.
 IF EXISTS(SELECT FROM kb.parsing_dependency d JOIN ops.parsing_product target ON target.task_id=d.target_task_id
  JOIN ops.task t ON t.id=target.task_id JOIN ops.run r ON r.id=t.run_id
  WHERE d.task_id=p_task AND (d.artifact_digest<>target.artifact_digest OR r.release_id<>run.release_id OR r.project_id<>run.project_id)) THEN
  RAISE EXCEPTION 'parsing dependency is outside its declared release/project/artifact custody' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_relationship r LEFT JOIN LATERAL (
  SELECT array_agg(role ORDER BY ordinal) roles FROM kb.parsing_endpoint e WHERE e.task_id=p_task AND e.relationship_id=r.relationship_id) e ON true
  WHERE r.task_id=p_task AND e.roles IS DISTINCT FROM (SELECT array_agg(endpoint->>'role' ORDER BY position)
   FROM sem.registry_row model CROSS JOIN LATERAL jsonb_array_elements(convert_from(model.body,'UTF8')::jsonb->'relationships') definition
   CROSS JOIN LATERAL jsonb_array_elements(definition->'endpoints') WITH ORDINALITY endpoint_rows(endpoint,position)
   WHERE model.release_id=run.release_id AND model.kind='execution_model' AND definition->>'id'='parsing_'||r.kind)) THEN
  RAISE EXCEPTION 'relationship endpoint roles differ from supported contract' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_node WHERE task_id=p_task AND kind='attribute'
  AND (nullif(name,'') IS NULL OR value IS NULL OR ordinal IS NULL OR ordinal<0 OR attribute_outcome IS NULL OR attribute_outcome NOT IN ('retained','discarded_duplicate','unknown')))
 OR EXISTS(SELECT FROM kb.parsing_relationship rel JOIN kb.parsing_endpoint a ON a.task_id=rel.task_id AND a.relationship_id=rel.relationship_id AND a.role='attribute'
  JOIN kb.parsing_endpoint o ON o.task_id=rel.task_id AND o.relationship_id=rel.relationship_id AND o.role='owner'
  LEFT JOIN kb.parsing_node attribute ON attribute.task_id=a.target_task_id AND attribute.node_id=a.node_id
  LEFT JOIN kb.parsing_node owner ON owner.task_id=o.target_task_id AND owner.node_id=o.node_id
  WHERE rel.task_id=p_task AND rel.kind='attribute_of' AND (a.target_task_id<>p_task OR o.target_task_id<>p_task OR attribute.kind IS DISTINCT FROM 'attribute' OR owner.kind IS DISTINCT FROM 'element')) THEN
  RAISE EXCEPTION 'invalid typed attribute occurrence/ownership' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_node n CROSS JOIN LATERAL (VALUES(n.name_start_offset,n.name_end_offset),(n.value_start_offset,n.value_end_offset)) r(first,last)
  WHERE n.task_id=p_task AND ((r.first IS NULL)<>(r.last IS NULL) OR (r.first IS NOT NULL AND (n.kind<>'attribute' OR n.origin<>'literal' OR NOT n.start_offset<=r.first OR NOT r.first<=r.last OR NOT r.last<=n.end_offset)))) THEN
  RAISE EXCEPTION 'invalid attribute lexical subrange' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_representation r WHERE r.task_id=p_task AND (
 (r.kind='original' AND (r.unit<>'byte' OR r.text_content IS NOT NULL OR r.text_content_utf8_base64 IS NOT NULL))
 OR (r.kind<>'original' AND (r.unit<>'codepoint' OR num_nonnulls(r.text_content,r.text_content_utf8_base64)<>1
  OR r.extent_length<>CASE WHEN r.text_content IS NOT NULL THEN length(r.text_content)
    ELSE length(ops.parsing_safe_utf8(decode(r.text_content_utf8_base64,'base64')),'UTF8') END)))) THEN
  RAISE EXCEPTION 'representation content variant/unit/codepoint length differs' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_node WHERE task_id=p_task AND kind='text' AND origin='derived'
  AND (name NOT IN ('text','tail') OR name IS NULL OR value IS NULL OR ordinal IS NULL OR ordinal NOT IN (0,1)))
 OR EXISTS(SELECT FROM kb.parsing_relationship rel JOIN kb.parsing_endpoint t ON t.task_id=rel.task_id AND t.relationship_id=rel.relationship_id AND t.role='text'
  JOIN kb.parsing_endpoint o ON o.task_id=rel.task_id AND o.relationship_id=rel.relationship_id AND o.role='owner'
  LEFT JOIN kb.parsing_node slot ON slot.task_id=t.target_task_id AND slot.node_id=t.node_id
  LEFT JOIN kb.parsing_node owner ON owner.task_id=o.target_task_id AND owner.node_id=o.node_id
  WHERE rel.task_id=p_task AND rel.kind='text_of' AND (t.target_task_id<>p_task OR o.target_task_id<>p_task OR slot.kind IS DISTINCT FROM 'text' OR slot.origin IS DISTINCT FROM 'derived' OR owner.kind IS NULL OR owner.kind NOT IN ('element','comment')))
 OR EXISTS(SELECT FROM kb.parsing_relationship rel JOIN kb.parsing_endpoint t ON t.task_id=rel.task_id AND t.relationship_id=rel.relationship_id AND t.role='target'
  JOIN kb.parsing_node slot ON slot.task_id=t.target_task_id AND slot.node_id=t.node_id
  WHERE rel.task_id=p_task AND rel.kind='derived_from' AND slot.kind='text' AND slot.origin='derived' AND (rel.ordinal IS NULL OR rel.ordinal<0)) THEN
  RAISE EXCEPTION 'invalid derived final text slot/ownership/contribution order' USING ERRCODE='23514'; END IF;
 -- Bounds, ordered partition and recognition are independent of provenance.
 IF EXISTS(SELECT FROM kb.parsing_component c JOIN kb.parsing_representation r USING(task_id,representation_id,unit)
  WHERE c.task_id=p_task AND c.end_offset>r.extent_length)
 OR EXISTS(SELECT FROM kb.parsing_node n JOIN kb.parsing_representation r USING(task_id,representation_id,unit)
  WHERE n.task_id=p_task AND n.end_offset>r.extent_length)
 OR EXISTS(SELECT FROM kb.parsing_mapping_endpoint e JOIN kb.parsing_representation r ON r.task_id=e.target_task_id AND r.representation_id=e.representation_id AND r.unit=e.unit
  WHERE e.task_id=p_task AND e.end_offset>r.extent_length) THEN
  RAISE EXCEPTION 'parsing extent exceeds its representation' USING ERRCODE='23514'; END IF;
 IF EXISTS(WITH ordered AS (SELECT c.*,row_number() OVER w-1 expected,lag(end_offset,1,0::bigint) OVER w previous_end
  FROM kb.parsing_component c WHERE task_id=p_task WINDOW w AS (PARTITION BY representation_id ORDER BY ordinal))
  SELECT FROM ordered c JOIN kb.parsing_representation r USING(task_id,representation_id,unit)
  WHERE c.ordinal<>c.expected OR c.start_offset<c.previous_end OR (r.partition_state='complete' AND c.start_offset<>c.previous_end))
 OR EXISTS(SELECT FROM kb.parsing_representation r WHERE task_id=p_task AND partition_state='complete'
  AND r.extent_length<>COALESCE((SELECT max(end_offset) FROM kb.parsing_component c WHERE c.task_id=p_task AND c.representation_id=r.representation_id),0))
 OR EXISTS(SELECT FROM kb.parsing_representation r JOIN kb.parsing_component c USING(task_id,representation_id)
  WHERE r.task_id=p_task AND r.recognition_state='complete' AND c.category='unknown') THEN
  RAISE EXCEPTION 'parsing partition/order/recognition claim differs' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_relationship r LEFT JOIN kb.parsing_endpoint e USING(task_id,relationship_id)
  WHERE r.task_id=p_task GROUP BY r.relationship_id HAVING count(e.ordinal)<2 OR min(e.ordinal)<>0 OR max(e.ordinal)<>count(e.ordinal)-1)
 OR EXISTS(SELECT FROM kb.parsing_mapping_endpoint WHERE task_id=p_task GROUP BY mapping_id,side HAVING min(ordinal)<>0 OR max(ordinal)<>count(*)-1) THEN
  RAISE EXCEPTION 'parsing endpoint order or multiplicity differs' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_relationship r WHERE r.task_id=p_task AND r.kind IN ('contains','structural_parent') AND (
  (SELECT count(*) FROM kb.parsing_endpoint e WHERE e.task_id=p_task AND e.relationship_id=r.relationship_id)<>2
  OR NOT EXISTS(SELECT FROM kb.parsing_endpoint e WHERE e.task_id=p_task AND e.relationship_id=r.relationship_id AND e.ordinal=0 AND e.role='parent' AND e.node_id IS NOT NULL AND e.target_task_id=p_task)
  OR NOT EXISTS(SELECT FROM kb.parsing_endpoint e WHERE e.task_id=p_task AND e.relationship_id=r.relationship_id AND e.ordinal=1 AND e.role='child' AND e.node_id IS NOT NULL AND e.target_task_id=p_task)))
 OR EXISTS(SELECT FROM kb.parsing_relationship r JOIN kb.parsing_endpoint p ON p.task_id=r.task_id AND p.relationship_id=r.relationship_id AND p.ordinal=0
  JOIN kb.parsing_endpoint c ON c.task_id=r.task_id AND c.relationship_id=r.relationship_id AND c.ordinal=1
  JOIN kb.parsing_node a ON a.task_id=p.target_task_id AND a.node_id=p.node_id
  JOIN kb.parsing_node b ON b.task_id=c.target_task_id AND b.node_id=c.node_id
  WHERE r.task_id=p_task AND r.kind='contains' AND a.origin='literal' AND b.origin='literal'
  AND (a.representation_id<>b.representation_id OR a.start_offset>b.start_offset OR a.end_offset<b.end_offset)) THEN
  RAISE EXCEPTION 'invalid structural containment' USING ERRCODE='23514'; END IF;
 IF EXISTS(WITH RECURSIVE edges AS (
  SELECT p.node_id parent,c.node_id child FROM kb.parsing_relationship r
  JOIN kb.parsing_endpoint p ON p.task_id=r.task_id AND p.relationship_id=r.relationship_id AND p.ordinal=0
  JOIN kb.parsing_endpoint c ON c.task_id=r.task_id AND c.relationship_id=r.relationship_id AND c.ordinal=1
  WHERE r.task_id=p_task AND r.kind IN ('contains','structural_parent')), walk(parent,child,path,cycle) AS (
  SELECT parent,child,ARRAY[parent,child],parent=child FROM edges UNION ALL
  SELECT w.parent,e.child,w.path||e.child,e.child=ANY(w.path) FROM walk w JOIN edges e ON e.parent=w.child WHERE NOT w.cycle)
  SELECT FROM walk WHERE cycle) THEN RAISE EXCEPTION 'structural containment cycle' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_mapping m CROSS JOIN LATERAL (
  SELECT count(*) FILTER(WHERE side='source') sources,count(*) FILTER(WHERE side='target') targets
  FROM kb.parsing_mapping_endpoint e WHERE e.task_id=p_task AND e.mapping_id=m.mapping_id) n
  WHERE m.task_id=p_task AND ((m.fidelity='exact' AND (n.sources=0 OR n.targets=0)) OR (m.fidelity='synthetic' AND (n.sources<>0 OR n.targets=0)) OR (m.fidelity='excluded' AND (n.sources=0 OR n.targets<>0)))) THEN
  RAISE EXCEPTION 'mapping fidelity contradicts source/target extent sets' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_mapping m WHERE m.task_id=p_task AND m.fidelity='exact' AND (
  m.operation<>'copy' OR (SELECT count(DISTINCT unit) FROM kb.parsing_mapping_endpoint e WHERE e.task_id=p_task AND e.mapping_id=m.mapping_id)<>1
  OR (SELECT string_agg(CASE WHEN e.unit='byte' THEN substring(a.content FROM e.start_offset::integer+1 FOR (e.end_offset-e.start_offset)::integer)
       ELSE ops.parsing_codepoint_slice(r.text_content,r.text_content_utf8_base64,e.start_offset,e.end_offset) END,''::bytea ORDER BY e.ordinal)
      FROM kb.parsing_mapping_endpoint e JOIN kb.parsing_representation r ON r.task_id=e.target_task_id AND r.representation_id=e.representation_id
      JOIN ops.parsing_product pp ON pp.task_id=e.target_task_id JOIN kb.source_artifact a ON a.artifact_digest=pp.artifact_digest
      WHERE e.task_id=p_task AND e.mapping_id=m.mapping_id AND side='source')
    IS DISTINCT FROM
     (SELECT string_agg(CASE WHEN e.unit='byte' THEN substring(a.content FROM e.start_offset::integer+1 FOR (e.end_offset-e.start_offset)::integer)
       ELSE ops.parsing_codepoint_slice(r.text_content,r.text_content_utf8_base64,e.start_offset,e.end_offset) END,''::bytea ORDER BY e.ordinal)
      FROM kb.parsing_mapping_endpoint e JOIN kb.parsing_representation r ON r.task_id=e.target_task_id AND r.representation_id=e.representation_id
      JOIN ops.parsing_product pp ON pp.task_id=e.target_task_id JOIN kb.source_artifact a ON a.artifact_digest=pp.artifact_digest
      WHERE e.task_id=p_task AND e.mapping_id=m.mapping_id AND side='target'))) THEN
  RAISE EXCEPTION 'exact copy transformation content differs' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.parsing_mapping m WHERE m.task_id=p_task AND m.fidelity='transformed' AND (
 adapter IS NULL OR NOT (adapter->'capabilities') ? ('mapping/'||m.operation)
 OR NOT EXISTS(SELECT FROM kb.parsing_mapping_endpoint e WHERE e.task_id=p_task AND e.mapping_id=m.mapping_id AND e.side='source')
 OR NOT EXISTS(SELECT FROM kb.parsing_mapping_endpoint e WHERE e.task_id=p_task AND e.mapping_id=m.mapping_id AND e.side='target'))) THEN
  RAISE EXCEPTION 'transformed contributions require admitted adapter/operation and extent sets' USING ERRCODE='23514'; END IF;
 IF product->>'provenance_state'='complete' AND (product->>'provenance_universe' IS DISTINCT FROM 'canonical_output'
 OR EXISTS(SELECT FROM kb.parsing_representation r WHERE r.task_id=p_task AND r.kind='canonical' AND NOT ops.parsing_origin_known(p_task,r.representation_id,0,r.extent_length,ARRAY[]::text[],adapter))) THEN
  RAISE EXCEPTION 'complete canonical-output provenance is not rooted in original bytes/admitted synthetic rules' USING ERRCODE='23514'; END IF;
 PERFORM ops.register_parsing_source(p_task);
 RETURN digest;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION ops.publish_parsing_product (bigint, bigint, text, text, bytea, bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.publish_parsing_product (bigint, bigint, text, text, bytea, bytea) TO corpus_sem_writer;
GRANT SELECT ON TABLE kb.source_artifact TO corpus_sem_writer, corpus_sem_reader, corpus_sem_admitter, corpus_sem_evaluator;
GRANT SELECT ON TABLE ops.parsing_product TO corpus_sem_writer, corpus_sem_reader, corpus_sem_admitter, corpus_sem_evaluator;
GRANT SELECT ON TABLE kb.parsing_representation TO corpus_sem_writer, corpus_sem_reader, corpus_sem_admitter, corpus_sem_evaluator;
GRANT SELECT ON TABLE kb.parsing_component TO corpus_sem_writer, corpus_sem_reader, corpus_sem_admitter, corpus_sem_evaluator;
GRANT SELECT ON TABLE kb.parsing_node TO corpus_sem_writer, corpus_sem_reader, corpus_sem_admitter, corpus_sem_evaluator;
GRANT SELECT ON TABLE kb.parsing_relationship TO corpus_sem_writer, corpus_sem_reader, corpus_sem_admitter, corpus_sem_evaluator;
GRANT SELECT ON TABLE kb.parsing_endpoint TO corpus_sem_writer, corpus_sem_reader, corpus_sem_admitter, corpus_sem_evaluator;
GRANT SELECT ON TABLE kb.parsing_mapping TO corpus_sem_writer, corpus_sem_reader, corpus_sem_admitter, corpus_sem_evaluator;
GRANT SELECT ON TABLE kb.parsing_mapping_endpoint TO corpus_sem_writer, corpus_sem_reader, corpus_sem_admitter, corpus_sem_evaluator;
GRANT SELECT ON TABLE kb.parsing_dependency TO corpus_sem_writer, corpus_sem_reader, corpus_sem_admitter, corpus_sem_evaluator;
CREATE OR REPLACE FUNCTION ops.retain_source_artifact(p_document bigint, p_original bytea) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE digest text:=encode(sha256(p_original),'hex');
BEGIN
 IF NOT EXISTS(SELECT FROM kb.document WHERE id=p_document AND content_hash=digest) THEN
  RAISE EXCEPTION 'original artifact differs from registered document' USING ERRCODE='23514'; END IF;
 INSERT INTO kb.source_artifact VALUES(digest,p_original) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT FROM kb.source_artifact WHERE artifact_digest=digest AND content=p_original) THEN
  RAISE EXCEPTION 'original artifact identity differs' USING ERRCODE='23505'; END IF;
 RETURN digest;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION ops.retain_source_artifact (bigint, bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.retain_source_artifact (bigint, bytea) TO corpus_sem_writer;
CREATE OR REPLACE FUNCTION ops.require_parsing_product(p_task bigint, p_contract text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE product ops.parsing_product; original bytea;
BEGIN
 SELECT * INTO STRICT product FROM ops.parsing_product WHERE task_id=p_task;
 PERFORM sem.require_execution_operation(product.release_id,'read_parsing_product');
 PERFORM sem.require_parsing_contract(product.release_id);
 SELECT content INTO original FROM kb.source_artifact WHERE artifact_digest=product.artifact_digest;
 IF product.contract_digest IS DISTINCT FROM p_contract OR product.product_digest<>encode(sha256(product.payload),'hex')
 OR original IS NULL OR product.artifact_digest<>encode(sha256(original),'hex')
 OR NOT EXISTS(SELECT FROM sem.input WHERE release_id=product.release_id AND input_kind='dependency' AND input_name='execution/schema/parsing_products' AND encode(sha256(content),'hex')=p_contract) THEN
  RAISE EXCEPTION 'retained parsing product/contract/source custody differs' USING ERRCODE='23514'; END IF;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION ops.require_parsing_product (bigint, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.require_parsing_product (bigint, text) TO corpus_sem_writer, corpus_sem_reader, corpus_sem_admitter, corpus_sem_evaluator;
SET LOCAL role TO '__MIGRATION_OWNER__';
CREATE OR REPLACE FUNCTION ops.guard_execution_task() RETURNS trigger LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE prior text; result text; agent boolean;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM sem.release WHERE release_id=NEW.release_id AND profile='semantic-2') THEN RETURN NEW; END IF;
 result:=ops.execution_task_state(NEW);
 SELECT (m.tier='agent' OR m.family='agent') INTO STRICT agent FROM ops.method_config c JOIN ops.method m ON m.id=c.method_id WHERE c.id=NEW.method_config_id;
 IF TG_OP='INSERT' THEN
  PERFORM sem.require_execution_operation(NEW.release_id,'schedule');
  IF NEW.status NOT IN ('pending','awaiting_agent','reused','skipped') OR NEW.attempt<>0 OR NEW.claimed_by IS NOT NULL OR NEW.lease_until IS NOT NULL
    OR result<>NEW.status THEN RAISE EXCEPTION 'invalid initial task combination' USING ERRCODE='23514'; END IF;
  IF NEW.status IN ('pending','awaiting_agent') AND (NEW.status='awaiting_agent')<>agent THEN
   RAISE EXCEPTION 'task channel differs from method contract' USING ERRCODE='23514'; END IF;
  IF NEW.status='skipped' AND nullif(NEW.reason,'') IS NULL THEN RAISE EXCEPTION 'skipped task requires reason' USING ERRCODE='23514'; END IF;
  IF agent AND EXISTS (SELECT 1 FROM sem.operation_effect e WHERE e.release_id=NEW.release_id
    AND e.operation_id='schedule' AND e.effect_id='schedule_pending_or_reused_or_skipped' AND e.effect_version='2')
    AND ((NEW.status='skipped' AND NEW.packet_hash IS NOT NULL)
      OR (NEW.status<>'skipped' AND NEW.packet_hash IS NULL)) THEN
   RAISE EXCEPTION 'agent packet presence differs from invocation disposition' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 prior:=ops.execution_task_state(OLD);
 IF NEW.attempt IS DISTINCT FROM OLD.attempt THEN
  PERFORM ops.require_transition(NEW.release_id,'claim',prior,result);
 ELSIF NEW.status='awaiting_agent' AND OLD.status='running' THEN
  PERFORM ops.require_transition(NEW.release_id,'release_claim',prior,result);
 ELSIF NEW.status IN ('done','empty','failed') AND OLD.status='running' THEN
  PERFORM ops.require_transition(NEW.release_id,'complete',prior,result);
 ELSIF NEW.status='cancelled' AND OLD.status<>'cancelled' THEN
  PERFORM ops.require_transition(NEW.release_id,'end_run',prior,result);
 ELSIF prior<>result THEN
  PERFORM ops.require_transition(NEW.release_id,'hold_submission',prior,result);
 ELSIF NEW.lease_until IS DISTINCT FROM OLD.lease_until THEN
  PERFORM sem.require_execution_operation(NEW.release_id,'renew_claim');
 END IF;

 IF NEW.attempt IS DISTINCT FROM OLD.attempt THEN
  IF NEW.attempt<>OLD.attempt+1 OR NEW.status<>'running' OR nullif(NEW.claimed_by,'') IS NULL
    OR NEW.lease_until IS NULL OR NEW.lease_until<=clock_timestamp()
    OR (OLD.status='running' AND (OLD.lease_until IS NULL OR OLD.lease_until>=clock_timestamp()))
    OR NOT ops.execution_edge(NEW.release_id,'task',prior,result) THEN
   RAISE EXCEPTION 'invalid claim or reclaim ownership' USING ERRCODE='23514'; END IF;
 ELSIF NEW.claimed_by IS DISTINCT FROM OLD.claimed_by
  AND NOT(current_user='corpus_sem_publisher' AND NEW.status='awaiting_agent'
   AND NEW.claimed_by IS NULL AND ops.execution_edge(NEW.release_id,'task',prior,result)) THEN
  RAISE EXCEPTION 'holder mutation requires a new attempt' USING ERRCODE='23514';
 ELSIF prior<>result AND NOT ops.execution_edge(NEW.release_id,'task',prior,result) THEN
  RAISE EXCEPTION 'undeclared task transition % -> %',prior,result USING ERRCODE='23514';
 END IF;
 IF NEW.attempt=OLD.attempt AND NEW.lease_until IS DISTINCT FROM OLD.lease_until
  AND NEW.status='running' AND current_user<>'corpus_sem_publisher' THEN
  RAISE EXCEPTION 'lease renewal requires protected current ownership' USING ERRCODE='23514'; END IF;
 IF NEW.status IN ('done','empty','failed','cancelled') AND current_user<>'corpus_sem_publisher' THEN
  RAISE EXCEPTION 'terminal task effects require protected publication' USING ERRCODE='23514'; END IF;
 IF NEW.status IN ('done','empty','failed') AND NEW.result_digest IS NULL THEN
  RAISE EXCEPTION 'completed task requires an immutable result receipt' USING ERRCODE='23514'; END IF;
 IF NEW.status='failed' AND (NEW.error IS NULL OR jsonb_typeof(NEW.error)<>'object') THEN
  RAISE EXCEPTION 'failed task requires typed failure diagnostics' USING ERRCODE='23514'; END IF;
 IF OLD.error ? 'semantic_proposal_first_result' AND OLD.error->'semantic_proposal_first_result'
  IS DISTINCT FROM NEW.error->'semantic_proposal_first_result' THEN
  RAISE EXCEPTION 'held first result is immutable' USING ERRCODE='23514';
 END IF;
 IF NEW.status<>'running' AND NEW.lease_until IS NOT NULL THEN
  RAISE EXCEPTION 'terminal task cannot retain a live lease' USING ERRCODE='23514'; END IF;
 IF NEW.status='running' AND (NEW.attempt<=0 OR nullif(NEW.claimed_by,'') IS NULL OR NEW.lease_until IS NULL) THEN
  RAISE EXCEPTION 'running task requires current attempt ownership' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION ops.guard_execution_run() RETURNS trigger LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE prior text; result text;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM sem.release WHERE release_id=NEW.release_id AND profile='semantic-2') THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  PERFORM sem.require_execution_operation(NEW.release_id,'start_run');
  IF NEW.status<>'created' OR NEW.sealed OR NEW.result_realization_id IS NOT NULL THEN
   RAISE EXCEPTION 'invalid initial run combination' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 prior:=OLD.status || CASE WHEN OLD.status IN ('failed','cancelled') THEN CASE WHEN OLD.sealed THEN '_sealed' ELSE '_open' END ELSE '' END;
 result:=NEW.status || CASE WHEN NEW.status IN ('failed','cancelled') THEN CASE WHEN NEW.sealed THEN '_sealed' ELSE '_open' END ELSE '' END;
 IF prior<>result THEN
  PERFORM ops.require_transition(NEW.release_id,CASE WHEN NEW.status='running' THEN 'execute_source'
   WHEN NEW.status='consolidating' THEN 'capture_cut' WHEN NEW.status='finished' THEN 'evaluate' ELSE 'end_run' END,prior,result);
 END IF;

 IF prior<>result AND NOT ops.execution_edge(NEW.release_id,'run',prior,result) THEN
  RAISE EXCEPTION 'undeclared run transition % -> %',prior,result USING ERRCODE='23514'; END IF;
 IF NEW.status IN ('finished','failed','cancelled') THEN
  IF current_user<>'corpus_sem_publisher' THEN
   RAISE EXCEPTION 'terminal run effects require protected publication' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT 1 FROM ops.task WHERE run_id=NEW.id AND status IN ('pending','awaiting_agent','running')) THEN
   RAISE EXCEPTION 'terminal run requires all source tasks to be terminal' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.sealed<>(NEW.status IN ('consolidating','finished') OR (NEW.status IN ('failed','cancelled') AND OLD.sealed)) THEN
  RAISE EXCEPTION 'invalid run sealing combination' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
REVOKE UPDATE (status) ON TABLE ops.run FROM corpus_sem_writer;
REVOKE UPDATE (status, attempt, claimed_by, lease_until, started_at, finished_at) ON TABLE ops.task FROM corpus_sem_writer;
CREATE OR REPLACE FUNCTION ops.guard_source_selection() RETURNS trigger LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE bound ops.run; document bigint;
BEGIN
 bound := ops.lock_execution_run(NEW.run_id,'schedule');
 IF TG_TABLE_NAME='task' THEN
   IF TG_OP='UPDATE' AND NEW.trigger IS DISTINCT FROM OLD.trigger THEN
     RAISE EXCEPTION 'task routing provenance is immutable';
   END IF;
   IF NEW.unit_type<>'document' THEN RETURN NEW; END IF;
   document:=NEW.unit_id;
 ELSE document:=NEW.document_id;
 END IF;
 IF bound.options ? 'corpus' AND NOT EXISTS(
   SELECT 1 FROM kb.document d WHERE d.id=document AND d.project_id=bound.project_id
     AND bound.options->'corpus'->'documents' ? d.key
 ) THEN RAISE EXCEPTION 'source document is outside immutable declared corpus'; END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION ops.guard_task_lifecycle() RETURNS trigger LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE bound ops.run;
BEGIN
 bound := ops.lock_execution_run(NEW.run_id,'schedule');
 IF TG_OP='UPDATE' AND OLD.status IN ('done','empty','failed','reused','skipped','cancelled') AND NEW IS DISTINCT FROM OLD THEN
   RAISE EXCEPTION 'terminal source task is immutable';
 END IF;
 IF (TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status) AND (bound.sealed OR bound.status IN ('finished','failed','cancelled'))
 AND NOT(TG_OP='UPDATE' AND current_user='corpus_sem_publisher' AND NEW.status IN ('failed','cancelled')) THEN
   RAISE EXCEPTION 'task run is closed';
 END IF;
 IF TG_OP='UPDATE' AND (OLD.run_id,OLD.release_id,OLD.method_config_id,OLD.input_hash,OLD.packet_hash,OLD.unit_type,OLD.unit_id,OLD.unit_key,OLD.invocation_key)
 IS DISTINCT FROM (NEW.run_id,NEW.release_id,NEW.method_config_id,NEW.input_hash,NEW.packet_hash,NEW.unit_type,NEW.unit_id,NEW.unit_key,NEW.invocation_key) THEN
   RAISE EXCEPTION 'task inputs are immutable';
 END IF;
 IF NEW.status IN ('done','empty') AND current_user<>'corpus_sem_publisher' THEN RAISE EXCEPTION 'successful source completion requires protected result publication'; END IF;
 IF NEW.status='reused' AND NEW.reused_task_id IS NULL THEN RAISE EXCEPTION 'reuse requires a completed origin'; END IF;
 IF NOT ops.valid_reuse(NEW) THEN RAISE EXCEPTION 'reuse origin has another bound source context'; END IF;
 IF NEW.unit_type='document' AND NOT EXISTS(SELECT 1 FROM kb.document WHERE id=NEW.unit_id AND project_id=bound.project_id) THEN
   RAISE EXCEPTION 'task document is outside bound project';
 ELSIF NEW.unit_type='source_view' AND NOT EXISTS(SELECT FROM ops.run_source_view WHERE run_id=NEW.run_id AND source_view_id=NEW.unit_id) THEN
   RAISE EXCEPTION 'task source view outside bound run';
 ELSIF NEW.unit_type='rendition' AND NOT EXISTS(SELECT 1 FROM ops.run_rendition WHERE run_id=NEW.run_id AND rendition_id=NEW.unit_id) THEN
   RAISE EXCEPTION 'task rendition is outside bound run';
 ELSIF NEW.unit_type='segment' AND NOT EXISTS(SELECT 1 FROM kb.segment s JOIN ops.run_rendition rr ON rr.rendition_id=s.rendition_id WHERE rr.run_id=NEW.run_id AND s.id=NEW.unit_id) THEN
   RAISE EXCEPTION 'task segment is outside bound run';
 END IF;
 RETURN NEW;
END $$;
SET LOCAL role TO 'corpus_sem_publisher';

DO $reference$ BEGIN IF to_regclass('pg_temp.semantic_physical_checks') IS NOT NULL THEN RAISE EXCEPTION 'preexisting physical contract workspace'; END IF; END $reference$;
CREATE TEMP TABLE semantic_physical_checks(relation_name text,constraint_name text,expression text) ON COMMIT DROP;
GRANT SELECT,INSERT ON pg_temp.semantic_physical_checks TO corpus_sem_publisher,SESSION_USER;

DO $repair$ DECLARE n text; owner_name text; previous_name text:=current_user; BEGIN SELECT pg_get_userbyid(relowner) INTO owner_name FROM pg_class WHERE oid='data.alternative_group'::regclass; EXECUTE format('SET LOCAL ROLE %I',owner_name); IF to_regclass('pg_temp.semantic_check_reference') IS NOT NULL THEN RAISE EXCEPTION 'preexisting migration CHECK reference'; END IF; EXECUTE 'CREATE TEMPORARY TABLE semantic_check_reference (
	realization_id TEXT, 
	release_id TEXT, 
	group_id TEXT, 
	reason TEXT, 
